    /// <summary>
    /// Computes Average Directional Index using zero-allocation fast path.
    /// Uses OscillatorCore with span-based computation directly into pooled buffer.
    /// </summary>
    private static (ComputeBuffer Plus, ComputeBuffer Minus) DirectionalIndicators(StockData data,
        ComputeContext context, int length, MovingAvgType maType)
    {
        if (!ComponentAverage.HasOverrides && StrengthWindow.Supports(maType))
        {
            var (prices, highs, lows, _, _) = CalculationsHelper.GetInputValuesList(data);
            using var window = new DirectionalIndexWindow(maType, Math.Max(1, length), Math.Max(1, prices.Count));
            var plus = context.Rent(prices.Count); var minus = context.Rent(prices.Count);
            for (var i = 0; i < prices.Count; i++) { var point = window.Next(highs[i], lows[i], prices[i], true); plus.WritableSpan[i] = point.Plus; minus.WritableSpan[i] = point.Minus; }
            return (plus, minus);
        }

        // The pair CalculateAverageDirectionalIndex publishes as DiPlus and DiMinus: how much of the smoothed
        // true range each direction's movement accounts for. The index itself and every indicator that reads
        // the pair start here, so they cannot drift apart.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var high = SpanCompat.AsReadOnlySpan(highList);
        var low = SpanCompat.AsReadOnlySpan(lowList);

        using var dmPlusBuffer = context.Rent(count);
        using var dmMinusBuffer = context.Rent(count);
        using var trBuffer = context.Rent(count);
        var dmPlus = dmPlusBuffer.WritableSpan;
        var dmMinus = dmMinusBuffer.WritableSpan;
        var trueRange = trBuffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentHigh = high[i];
            var currentLow = low[i];
            var prevHigh = i >= 1 ? high[i - 1] : currentHigh;
            var prevLow = i >= 1 ? low[i - 1] : currentLow;

            // The first bar has no previous close, and the current one keeps its true range from opening
            // at the whole day's move.
            var prevClose = i >= 1 ? input[i - 1] : input[i];
            var highDiff = currentHigh - prevHigh;
            var lowDiff = prevLow - currentLow;

            dmPlus[i] = highDiff > lowDiff ? Math.Max(highDiff, 0) : 0;
            dmMinus[i] = highDiff < lowDiff ? Math.Max(lowDiff, 0) : 0;
            trueRange[i] = CalculationsHelper.CalculateTrueRange(currentHigh, currentLow, prevClose);
        }

        using var smoothedPlusBuffer = context.Rent(count);
        using var smoothedMinusBuffer = context.Rent(count);
        using var smoothedRangeBuffer = context.Rent(count);
        var smoothedPlus = smoothedPlusBuffer.WritableSpan;
        var smoothedMinus = smoothedMinusBuffer.WritableSpan;
        var smoothedRange = smoothedRangeBuffer.WritableSpan;
        MovingAverage(data, maType, length, dmPlus, smoothedPlus);
        MovingAverage(data, maType, length, dmMinus, smoothedMinus);
        MovingAverage(data, maType, length, trueRange, smoothedRange);

        var plusBuffer = context.Rent(count);
        var minusBuffer = context.Rent(count);
        var diPlus = plusBuffer.WritableSpan;
        var diMinus = minusBuffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var range = smoothedRange[i];
            diPlus[i] = range != 0 ? MathHelper.MinOrMax(100 * smoothedPlus[i] / range, 100, 0) : 0;
            diMinus[i] = range != 0 ? MathHelper.MinOrMax(100 * smoothedMinus[i] / range, 100, 0) : 0;
        }

        return (plusBuffer, minusBuffer);
    }

    /// <summary>
    /// Computes the upward directional indicator that the ADX is built from.
    /// </summary>
    internal static ComputeBuffer ComputeDiPlusFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        var (plusBuffer, minusBuffer) = DirectionalIndicators(data, context, length, maType);
        minusBuffer.Dispose();
        return plusBuffer;
    }

    /// <summary>
    /// Computes the downward directional indicator that the ADX is built from.
    /// </summary>
    internal static ComputeBuffer ComputeDiMinusFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        var (plusBuffer, minusBuffer) = DirectionalIndicators(data, context, length, maType);
        plusBuffer.Dispose();
        return minusBuffer;
    }

    internal static ComputeBuffer ComputeAdxFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        if (!ComponentAverage.HasOverrides && StrengthWindow.Supports(maType))
        {
            var (prices, highs, lows, _, _) = CalculationsHelper.GetInputValuesList(data);
            using var window = new DirectionalIndexWindow(maType, Math.Max(1, length), Math.Max(1, prices.Count));
            var result = context.Rent(prices.Count);
            for (var i = 0; i < prices.Count; i++) result.WritableSpan[i] = window.Next(highs[i], lows[i], prices[i], true).Adx;
            return result;
        }

        // CalculateAverageDirectionalIndex smooths how far apart the two directional indicators are with
        // whichever average it was given, so the core's hardcoded Wilder's smoothing answered for one type
        // only.
        var (plusBuffer, minusBuffer) = DirectionalIndicators(data, context, length, maType);
        using var diPlusBuffer = plusBuffer;
        using var diMinusBuffer = minusBuffer;
        var diPlus = diPlusBuffer.Span;
        var diMinus = diMinusBuffer.Span;
        var count = diPlus.Length;

        using var diBuffer = context.Rent(count);
        var di = diBuffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var diSum = diPlus[i] + diMinus[i];
            di[i] = diSum != 0
                ? MathHelper.MinOrMax(100 * Math.Abs(diPlus[i] - diMinus[i]) / diSum, 100, 0)
                : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, di, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Chande Momentum Oscillator using zero-allocation fast path.
    /// Uses OscillatorCore with span-based computation directly into pooled buffer.
    /// </summary>
    internal static ComputeBuffer ComputeCmoFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);

        var buffer = context.Rent(inputList.Count);
        OscillatorCore.ChandeMomentumOscillator(inputSpan, buffer.WritableSpan, length);

        return buffer;
    }

    /// <summary>
    /// Computes Percentage Price Oscillator using zero-allocation fast path.
    /// Uses OscillatorCore with span-based computation directly into pooled buffer.
    /// </summary>
    internal static ComputeBuffer ComputePpoFast(StockData data, ComputeContext context, int fastLength = 12,
        int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int signalLength = 9,
        MacdSeries series = MacdSeries.Line)
    {
        // CalculatePercentagePriceOscillator is the gap between two averages of the chained series as a
        // percentage of the slower one, smoothed again over signalLength for its Signal and differenced
        // against that for its Histogram. Only the oscillator was produced, so both other keys carried it,
        // and neither signalLength nor maType reached the arm - OscillatorCore's routine takes neither.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fast = context.Rent(count);
        using var slow = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fast.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slow.WritableSpan);

        using var oscillator = context.Rent(count);
        var osc = oscillator.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            osc[i] = RoundedPercentageChange.Of(fast.Span[i], slow.Span[i]);
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (series == MacdSeries.Line)
        {
            oscillator.Span.CopyTo(output);
            return buffer;
        }

        using var signalLine = context.Rent(count);
        var signalCount = 0;
        while (signalCount < count && !double.IsInfinity(osc[signalCount])) signalCount++;
        MovingAverage(data, maType, signalLength, oscillator.Span.Slice(0, signalCount), signalLine.WritableSpan.Slice(0, signalCount));
        signalLine.WritableSpan.Slice(signalCount).Fill(double.NaN);

        if (series == MacdSeries.Signal)
        {
            signalLine.Span.CopyTo(output);
            return buffer;
        }

        for (var i = 0; i < count; i++)
        {
            output[i] = oscillator.Span[i] - signalLine.Span[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Absolute Price Oscillator using zero-allocation fast path.
    /// Uses OscillatorCore with span-based computation directly into pooled buffer.
    /// </summary>
    internal static ComputeBuffer ComputeApoFast(StockData data, ComputeContext context, int fastLength = 12,
        int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateAbsolutePriceOscillator is the difference of two averages of the chained series, taken
        // with whichever average it was given. OscillatorCore.AbsolutePriceOscillator has no average to give
        // it - the arm never took a maType at all - so the type the caller configured reached nothing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fast = context.Rent(count);
        using var slow = context.Rent(count);
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var fastMean = new Streaming.RoundedSimpleMovingAverageSmoother(fastLength);
            using var slowMean = new Streaming.RoundedSimpleMovingAverageSmoother(slowLength);
            for (var i = 0; i < count; i++)
            {
                fast.WritableSpan[i] = fastMean.Next(input[i], true);
                slow.WritableSpan[i] = slowMean.Next(input[i], true);
            }
        }
        else
        {
            MovingAverage(data, maType, fastLength, input, fast.WritableSpan);
            MovingAverage(data, maType, slowLength, input, slow.WritableSpan);
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var fastSpan = fast.Span;
        var slowSpan = slow.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = fastSpan[i] - slowSpan[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ultimate Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeUltimateOscillatorFast(StockData data, ComputeContext context, int length1 = 7,
        int length2 = 14, int length3 = 28)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var output = context.Rent(input.Count);
        OscillatorCore.UltimateOscillator(SpanCompat.AsReadOnlySpan(data.HighPrices), SpanCompat.AsReadOnlySpan(data.LowPrices), SpanCompat.AsReadOnlySpan(input), output.WritableSpan, length1, length2, length3);
        return output;
    }

    /// <summary>
    /// Computes True Strength Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTsiFast(StockData data, ComputeContext context, int longLength = 25,
        int shortLength = 13, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // TsiSpecOptions is an alias of TrueStrengthIndexSpecOptions - both bind
        // IndicatorName.TrueStrengthIndex, and its LongLength and ShortLength are that batch's length1 and
        // length2 - so it delegates rather than keeping a second implementation that can drift away.
        return ComputeTrueStrengthIndexFast(data, context, longLength, shortLength, maType);
    }

    /// <summary>
    /// Computes Aroon Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the three series the Aroon routine publishes.
    /// </summary>
    internal enum AroonSeries
    {
        /// <summary>Aroon Up less Aroon Down.</summary>
        Oscillator,

        /// <summary>The upward leg on its own.</summary>
        Up,

        /// <summary>The downward leg on its own.</summary>
        Down
    }

    internal static ComputeBuffer ComputeAroonOscillatorFast(StockData data, ComputeContext context, int length = 25,
        AroonSeries series = AroonSeries.Oscillator)
    {
        // CalculateAroonOscillator counts the bars since the chained series last touched the high and the low
        // of its own window and publishes the difference of the two readings. Where a value repeats it takes
        // the most recent bar carrying it, so the search runs backwards from the current bar. The core this
        // replaced measured the bars' highs and lows instead of the series being chained.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(Math.Max(length, 2));
        for (var i = 0; i < count; i++)
        {
            window.Add(input[i]);
            var maxPrice = window.Max;
            var minPrice = window.Min;

            var maxIndex = i;
            while (maxIndex > 0 && input[maxIndex] != maxPrice)
            {
                maxIndex--;
            }

            var minIndex = i;
            while (minIndex > 0 && input[minIndex] != minPrice)
            {
                minIndex--;
            }

            var aroonUp = (double)(length - (i - maxIndex)) / length * 100;
            var aroonDown = (double)(length - (i - minIndex)) / length * 100;

            // Both legs were already being computed here and then discarded, which is why every key
            // answered with the oscillator. They are taken from the chained series, so ComputeAroonUpFast
            // and ComputeAroonDownFast - which read the bars' highs and lows - are a different reading and
            // would not satisfy Value == AroonUp - AroonDown.
            output[i] = series switch
            {
                AroonSeries.Up => aroonUp,
                AroonSeries.Down => aroonDown,
                _ => aroonUp - aroonDown
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes TRIX indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTrixFast(StockData data, ComputeContext context, int length = 15,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var custom = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var first = context.Rent(input.Count); using var second = context.Rent(input.Count); using var third = context.Rent(input.Count);
        if (custom)
        {
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), first.WritableSpan);
            MovingAverage(data, maType, length, first.Span, second.WritableSpan);
            MovingAverage(data, maType, length, second.Span, third.WritableSpan);
        }
        var result = context.Rent(input.Count); using var window = new TrixWindow(maType, length, initializeFallback: !custom);
        for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true, custom ? first.Span[i] : null, custom ? second.Span[i] : null, custom ? third.Span[i] : null).Publish();
        if (ComponentAverage.HasOverrides)
        {
            using var signal = context.Rent(input.Count);
            MovingAverage(data, maType, 9, result.Span, signal.WritableSpan);
        }
        return result;
    }

    /// <summary>
    /// Computes Mass Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMassIndexFast(StockData data, ComputeContext context, int length1 = 21,
        int length2 = 21, int length3 = 25, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null, int signalLength = 9)
    {
        length1=Math.Max(1,length1);length2=Math.Max(1,length2);length3=Math.Max(1,length3);signalLength=Math.Max(1,signalLength);
        var output=context.Rent(data.Count);
        if(ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var ranges=context.Rent(data.Count);for(var i=0;i<data.Count;i++)ranges.WritableSpan[i]=MassIndexWindow.Range(data.HighPrices[i],data.LowPrices[i]).Publish();
            using var first=context.Rent(data.Count);using var second=context.Rent(data.Count);using var line=context.Rent(data.Count);using var signal=context.Rent(data.Count);
            MovingAverage(data,maType,length1,ranges.Span,first.WritableSpan);MovingAverage(data,maType,length2,first.Span,second.WritableSpan);
            var sum=new MassIndexSum(length3);for(var i=0;i<data.Count;i++)line.WritableSpan[i]=sum.Next(new(first.Span[i]),new(second.Span[i]),true).Publish();
            MovingAverage(data,maType,signalLength,line.Span,signal.WritableSpan);
            (outputKey=="Signal"?signal.Span:line.Span).CopyTo(output.WritableSpan);
        }
        else
        {
            using var window=new MassIndexWindow(maType,length1,length2,length3,signalLength,data.Count);
            for(var i=0;i<data.Count;i++){var result=window.Next(data.HighPrices[i],data.LowPrices[i],true);output.WritableSpan[i]=outputKey=="Signal"?result.Signal:result.Value;}
        }
        return output;
    }

