    /// <summary>
    /// Computes Disparity Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDisparityIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateDisparityIndex measures the input series against an average of it, of whichever type it was
        // given. This read the close rather than the input series as well, so a chained indicator measured a
        // price the caller had already replaced.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);

        using var averageBuffer = context.Rent(count);
        var average = averageBuffer.WritableSpan;
        if (maType == MovingAvgType.SimpleMovingAverage) BollingerArithmetic.Mean(inputSpan, average, length);
        else MovingAverage(data, maType, length, inputSpan, average);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = RoundedPercentageChange.Of(inputSpan[i], average[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Directional Trend Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDirectionalTrendIndexFast(StockData data, ComputeContext context,
        int length1 = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length2 = 10,
        int length3 = 5)
    {
        // CalculateDirectionalTrendIndex nets how far each bar reached beyond the last bar's range in each
        // direction, then smooths that net and its magnitude three times over, and reports what share of the
        // movement was directional.
        var (_, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = highList.Count;

        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var window = new DirectionalStrengthWindow(maType, length1, length2, length3, count);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = window.Next(highList[i], lowList[i], true);
            return stable;
        }

        using var netBuffer = context.Rent(count);
        using var magnitudeBuffer = context.Rent(count);
        var net = netBuffer.WritableSpan;
        var magnitude = magnitudeBuffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentHigh = highList[i];
            var currentLow = lowList[i];
            var prevHigh = i >= 1 ? highList[i - 1] : 0;
            var prevLow = i >= 1 ? lowList[i - 1] : 0;

            var highMovedUp = currentHigh - prevHigh > 0 ? currentHigh - prevHigh : 0;
            var lowMovedDown = currentLow - prevLow < 0 ? (currentLow - prevLow) * -1 : 0;

            net[i] = highMovedUp - lowMovedDown;
            magnitude[i] = Math.Abs(net[i]);
        }

        // The three smoothings alternate between the two pairs of buffers rather than renting six.
        using var smoothedNetBuffer = context.Rent(count);
        using var smoothedMagnitudeBuffer = context.Rent(count);
        var smoothedNet = smoothedNetBuffer.WritableSpan;
        var smoothedMagnitude = smoothedMagnitudeBuffer.WritableSpan;

        MovingAverage(data, maType, length1, net, smoothedNet);
        MovingAverage(data, maType, length1, magnitude, smoothedMagnitude);
        MovingAverage(data, maType, length2, smoothedNet, net);
        MovingAverage(data, maType, length2, smoothedMagnitude, magnitude);
        MovingAverage(data, maType, length3, net, smoothedNet);
        MovingAverage(data, maType, length3, magnitude, smoothedMagnitude);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            output[i] = smoothedMagnitude[i] != 0
                ? MathHelper.MinOrMax(100 * smoothedNet[i] / smoothedMagnitude[i], 100, -100)
                : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Double Smoothed Stochastic using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDoubleSmoothedStochasticFast(StockData data, ComputeContext context, int length1 = 2, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length2 = 3, int length3 = 15, string? outputKey = null, int length4 = 3)
    {
        if (outputKey is not (null or "Dss" or "Signal")) throw new ArgumentOutOfRangeException(nameof(outputKey));
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        var components = external ? DoubleSmoothedStochasticWindow.Components(data, input, high, low, maType, length1, length2, length3, length4) : null; using var window = new DoubleSmoothedStochasticWindow(maType, length1, length2, length3, length4, external);
        var output = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], true, components?[0][i], components?[1][i], components?[2][i]); output.WritableSpan[i] = outputKey == "Signal" ? point.SignalLine : point.Dss; } return output; } catch { output.Dispose(); throw; }
    }

    /// <summary>
    /// Computes Dynamic Momentum Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDynamicMomentumIndexFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length1 = 5, int length2 = 10,
        int length3 = 14, int upLimit = 30, int dnLimit = 5, string? outputKey = null)
    {
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var means = !StrengthWindow.Supports(maType) || ComponentAverage.HasOverrides ? DynamicMomentumWindow.Components(data, input, maType, length1, length2, true) : null;
        using var window = new DynamicMomentumWindow(maType, length1, length2, length3, dnLimit, upLimit); var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true, means?[i]); output.WritableSpan[i] = outputKey == "Signal" ? point.SignalLine : outputKey == "Histogram" ? point.Histogram : point.Line; }
        return output;
    }

    /// <summary>
    /// Computes Ergodic Candlestick Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeErgodicCandlestickOscillatorFast(StockData data, ComputeContext context, int length1 = 32,
        int length2 = 12, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? key = null)
    {
        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var close = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
            using var window = new ErgodicCandleWindow(maType, length1, length2, close.Count); var result = context.Rent(close.Count);
            for (var i = 0; i < close.Count; i++)
            { var value = window.Next(close[i], data.OpenPrices[i], data.HighPrices[i], data.LowPrices[i], true); result.WritableSpan[i] = key == "Signal" ? value.Signal : value.Eco; }
            return result;
        }

        // CalculateErgodicCandlestickOscillator double-smooths the candle body and the candle range by
        // length1 then length2 and publishes the body as a percentage of the range. The arm this replaced
        // delegated to OscillatorCore.ErgodicCandlestickOscillator with a hard-wired first length of 5 and
        // no moving average type. The spec's only length binds to length2; length1 keeps its batch default.
        var count = data.Count;
        var closes = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var body = context.Rent(count);
        using var range = context.Rent(count);
        var xco = body.WritableSpan;
        var xhl = range.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            xco[i] = closes[i] - opens[i];
            xhl[i] = highs[i] - lows[i];
        }

        using var bodyFirst = context.Rent(count);
        using var bodySecond = context.Rent(count);
        MovingAverage(data, maType, length1, body.Span, bodyFirst.WritableSpan);
        MovingAverage(data, maType, length2, bodyFirst.Span, bodySecond.WritableSpan);

        using var rangeFirst = context.Rent(count);
        using var rangeSecond = context.Rent(count);
        MovingAverage(data, maType, length1, range.Span, rangeFirst.WritableSpan);
        MovingAverage(data, maType, length2, rangeFirst.Span, rangeSecond.WritableSpan);

        var xcoEma2 = bodySecond.Span;
        var xhlEma2 = rangeSecond.Span;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = xhlEma2[i] != 0 ? 100 * xcoEma2[i] / xhlEma2[i] : 0;
        }

        return key == "Signal" ? SmoothPublished(data, context, buffer, length2, maType) : buffer;
    }

    /// <summary>
    /// Computes Demarker Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDemarkerFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        length = Math.Max(1, length); var (_, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var result = context.Rent(high.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var ups = context.Rent(high.Count); using var downs = context.Rent(high.Count); using var upMean = context.Rent(high.Count); using var downMean = context.Rent(high.Count);
            for (var i = 0; i < high.Count; i++) { var up = DemarkerWindow.PositiveDifference(high[i], i > 0 ? high[i - 1] : high[i]); var down = DemarkerWindow.PositiveDifference(i > 0 ? low[i - 1] : low[i], low[i]); ups.WritableSpan[i] = up.Mantissa * (up.Doubled ? 2 : 1); downs.WritableSpan[i] = down.Mantissa * (down.Doubled ? 2 : 1); }
            MovingAverage(data, maType, length, ups.Span, upMean.WritableSpan); MovingAverage(data, maType, length, downs.Span, downMean.WritableSpan);
            for (var i = 0; i < high.Count; i++) result.WritableSpan[i] = DemarkerWindow.Ratio(new StrengthValue(upMean.Span[i]), new StrengthValue(downMean.Span[i]));
        }
        else { using var window = new DemarkerWindow(maType, length, high.Count); for (var i = 0; i < high.Count; i++) result.WritableSpan[i] = window.Next(high[i], low[i], true); }
        return result;
    }

