    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        VolatilityCore.StandardError(SpanCompat.AsReadOnlySpan(inputList), buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Keltner Channel Width using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKeltnerChannelWidthFast(StockData data, ComputeContext context, int length = 20,
        double multiplier = 2)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var result = context.Rent(input.Count);
        using var window = new KeltnerWindow(MovingAvgType.ExponentialMovingAverage, length, length, capacityHint: Math.Max(1, input.Count));
        for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], true); result.WritableSpan[i] = KeltnerWindow.Width(point.Middle, point.Atr, multiplier); }
        return result;
    }

    /// <summary>
    /// Computes Bollinger Bands Width using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsWidthFast(StockData data, ComputeContext context, int length = 20,
        double stdDevMult = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateBollingerBandsWidth publishes the span between the bands as a fraction of the middle band,
        // not as a percentage of it, and measures the chained series the bands were built on, not the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var middle = context.Rent(count);
        if (maType == MovingAvgType.SimpleMovingAverage) BollingerArithmetic.Mean(input, middle.WritableSpan, length);
        else MovingAverage(data, maType, length, input, middle.WritableSpan);
        var ma = middle.Span;

        using var deviation = new ExactPopulationWindow(length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = BollingerArithmetic.Width(ma[i], deviation.Next(input[i], true), stdDevMult);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Relative Volatility Index using zero-allocation fast path via VolatilityCore.
    /// </summary>
    internal static ComputeBuffer ComputeRviVolatilityFast(StockData data, ComputeContext context, int length = 14)
    {
        // RviVolatilitySpecOptions is an alias of RelativeVolatilityIndexSpecOptions - both bind
        // IndicatorName.RelativeVolatilityIndexV1 and both carry only a length - so it delegates rather than
        // keeping a second implementation that can drift away from the first.
        return ComputeRelativeVolatilityIndexFast(data, context, length);
    }

    /// <summary>
    /// Computes Donchian Channel Width using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDonchianChannelWidthFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool signalOutput = false, int smoothLength = 22)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var center = context.Rent(count); using var signal = context.Rent(count);
        if (external) MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(input), center.WritableSpan);
        var result = context.Rent(count); using var window = new DonchianWidthWindow(maType, length, smoothLength, external, Math.Max(1, count));
        for (var i = 0; i < count; i++) { var point = window.Next(high[i], low[i], input[i], true); result.WritableSpan[i] = point.Width; signal.WritableSpan[i] = point.Signal; }
        if (external) MovingAverage(data, maType, Math.Max(1, smoothLength), result.Span, signal.WritableSpan);
        if (signalOutput) signal.Span.CopyTo(result.WritableSpan);
        return result;
    }

