    /// <summary>
    /// Computes Elliott Wave Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeElliottWaveOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 5, int slowLength = 35, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // OscillatorCore's routine takes a simple average whatever it is asked for, which is this oscillator's
        // own default but not what a caller asking for another average gets from the batch.
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        var count = data.Count;

        using var fastBuffer = context.Rent(count);
        using var slowBuffer = context.Rent(count);
        fastBuffer.WritableSpan.Clear();
        slowBuffer.WritableSpan.Clear();
        StochasticSmooth(data, maType, fastLength, close, fastBuffer.WritableSpan);
        StochasticSmooth(data, maType, slowLength, close, slowBuffer.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = fastBuffer.Span[i] - slowBuffer.Span[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Forecast Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeForecastOscillatorFast(StockData data, ComputeContext context, int length = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool signal = false)
    {
        length = Math.Max(1, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var window = new OneBarReturnWindow(false, maType, length, !signal || external, input.Count); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var p = window.Next(input[i], true); result.WritableSpan[i] = signal && !external ? p.Signal : p.Value; }
        if (signal && external) { using var values = context.Rent(input.Count); result.Span.CopyTo(values.WritableSpan); MovingAverage(data, maType, length, values.Span, result.WritableSpan); } return result;
    }

    /// <summary>
    /// Computes Derivative Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDerivativeOscillatorFast(StockData data, ComputeContext context,
        int length1 = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length2 = 9,
        int length3 = 5, int length4 = 3)
    {
        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
            using var window = new DerivativeWindow(maType, length1, length2, length3, length4); var result = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true);
            return result;
        }

        // CalculateDerivativeOscillator smooths the relative strength index twice and then reports how far
        // that sits above its own length2 average, so it reads as a histogram around zero.
        using var rsi = context.Rent(data.Count);
        if (StrengthWindow.Supports(maType))
        {
            var prices = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; using var rsiWindow = new PriceRsiWindow(maType, length1, prices.Count);
            for (var i = 0; i < prices.Count; i++) rsi.WritableSpan[i] = rsiWindow.Next(prices[i], true);
        }
        else { using var ordinary = ComputeRsiFast(data, context, length1, maType); ordinary.Span.CopyTo(rsi.WritableSpan); }
        var count = rsi.Span.Length;

        using var firstBuffer = context.Rent(count);
        MovingAverage(data, maType, length3, rsi.Span, firstBuffer.WritableSpan);

        using var secondBuffer = context.Rent(count);
        MovingAverage(data, maType, length4, firstBuffer.Span, secondBuffer.WritableSpan);
        var smoothed = secondBuffer.Span;

        var smoothedSum = new RollingSum();

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            smoothedSum.Add(smoothed[i]);
            output[i] = smoothed[i] - smoothedSum.Average(length2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Gator Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the gator oscillator's two published series an arm has been asked for. The top is the gap
    /// between the alligator's jaw and teeth and the bottom is the negated gap between teeth and lips, so
    /// they are not an upper and a lower band around anything.
    /// </summary>
    internal enum GatorJaw
    {
        Top,
        Bottom
    }

    internal static ComputeBuffer ComputeGatorOscillatorFast(StockData data, ComputeContext context, int jawLength = 13,
        int jawOffset = 8, int teethLength = 8, int teethOffset = 5, int lipsLength = 5, int lipsOffset = 3,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, GatorJaw jaw = GatorJaw.Top)
    {
        // CalculateGatorOscillator measures the alligator's own lines: the top is the absolute gap between
        // jaw and teeth, the bottom the negated absolute gap between teeth and lips. Each line averages the
        // median price and is displaced by its own offset, which AlligatorLine already does - the arm this
        // replaced delegated to OscillatorCore.GatorOscillator on the raw high and low instead.
        using var jawLine = AlligatorLine(data, context, jawLength, jawOffset, maType);
        using var teethLine = AlligatorLine(data, context, teethLength, teethOffset, maType);
        var jaws = jawLine.Span;
        var teeth = teethLine.Span;

        var count = data.Count;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (jaw == GatorJaw.Top)
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = Math.Abs(jaws[i] - teeth[i]);
            }

            return buffer;
        }

        using var lipsLine = AlligatorLine(data, context, lipsLength, lipsOffset, maType);
        var lips = lipsLine.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = -Math.Abs(teeth[i] - lips[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fractal Chaos Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFractalChaosOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        _ = length; // Not used in this oscillator
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.FractalChaosOscillator(high, low, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Rahul Mohindar Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the four series the Rahul Mohindar routine publishes.
    /// </summary>
    internal enum RahulMohindarSeries
    {
        /// <summary>The long exponential average of the swing, which the indicator stands for.</summary>
        Rmo,

        /// <summary>The swing itself.</summary>
        SwingTrade1,

        /// <summary>Its exponential average over length3.</summary>
        SwingTrade2,

        /// <summary>That average smoothed again by the same length.</summary>
        SwingTrade3
    }

    internal static ComputeBuffer ComputeRahulMohindarOscillatorFast(StockData data, ComputeContext context, int length2 = 10,
        int length1 = 2, int length3 = 30, int length4 = 81, RahulMohindarSeries series = RahulMohindarSeries.Rmo)
    {
        var values = RmoWindow.Calculate(data, length1, length2, length3, length4, true, series);
        var selected = series == RahulMohindarSeries.SwingTrade1 ? values.Swing1 : series == RahulMohindarSeries.SwingTrade2 ? values.Swing2
            : series == RahulMohindarSeries.SwingTrade3 ? values.Swing3 : values.Rmo;
        var result = context.Rent(selected.Length); selected.AsSpan().CopyTo(result.WritableSpan); return result;
    }

    /// <summary>
    /// Computes Repulse Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRepulseFast(StockData data, ComputeContext context, int length = 5,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        length = Math.Max(1, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new RepulseWindow(maType, length); var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var bullPower = context.Rent(input.Count); using var bearPower = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) { var powers = window.Powers(data.OpenPrices[i], data.HighPrices[i], data.LowPrices[i], input[i], true); bullPower.WritableSpan[i] = powers.Bull.Publish(); bearPower.WritableSpan[i] = powers.Bear.Publish(); }
            using var bull = context.Rent(input.Count); using var bear = context.Rent(input.Count); var powerPeriod = RepulseWindow.PowerPeriod(length);
            MovingAverage(data, maType, powerPeriod, bullPower.Span, bull.WritableSpan); MovingAverage(data, maType, powerPeriod, bearPower.Span, bear.WritableSpan);
            using var line = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) line.WritableSpan[i] = bull.Span[i] - bear.Span[i];
            using var signal = context.Rent(input.Count); MovingAverage(data, maType, length, line.Span, signal.WritableSpan);
            (outputKey == "Signal" ? signal.Span : line.Span).CopyTo(result.WritableSpan);
        }
        else for (var i = 0; i < input.Count; i++) { var value = window.Next(data.OpenPrices[i], data.HighPrices[i], data.LowPrices[i], input[i], true); result.WritableSpan[i] = outputKey == "Signal" ? value.Signal : value.Line; }
        return result;
    }

    /// <summary>
    /// Computes Gann HiLo Activator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGannHiLoActivatorFast(StockData data, ComputeContext context, int length = 3,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateGannHiLoActivator flips between the averaged low and the averaged high as the chained
        // series crosses the previous bar's averages, and holds its last value in between.
        // TrendCore.GannHiLoActivator took the close and used the raw extremes rather than their averages.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var highAverage = context.Rent(count);
        using var lowAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.HighPrices), highAverage.WritableSpan);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.LowPrices), lowAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var highMa = highAverage.Span;
        var lowMa = lowAverage.Span;
        for (var i = 0; i < count; i++)
        {
            var prevHighMa = i >= 1 ? highMa[i - 1] : 0;
            var prevLowMa = i >= 1 ? lowMa[i - 1] : 0;
            var previous = i >= 1 ? output[i - 1] : 0;

            output[i] = input[i] > prevHighMa ? lowMa[i] : input[i] < prevLowMa ? highMa[i] : previous;
        }

        return buffer;
    }

    /// <summary>
    /// Computes HalfTrend indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHalfTrendFast(StockData data, ComputeContext context, int length = 2,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var window = new HalfTrendWindow(maType, length, 100, external); using ComputeBuffer? atr = external ? ComputeAtrFast(data, context, 100, maType) : null;
        using ComputeBuffer? highMean = external ? context.Rent(input.Count) : null; using ComputeBuffer? lowMean = external ? context.Rent(input.Count) : null;
        if (external) { MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(high), highMean!.Value.WritableSpan); MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(low), lowMean!.Value.WritableSpan); }
        var result = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(high[i], low[i], input[i], true, external ? atr!.Value.Span[i] : null, external ? highMean!.Value.Span[i] : null, external ? lowMean!.Value.Span[i] : null).Value; return result; }
        catch { result.Dispose(); throw; }
    }

