    /// <summary>
    /// Computes Chande Trend Score using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeTrendScoreFast(StockData data, ComputeContext context,
        int startLength = 11, int endLength = 20)
    {
        // CalculateChandeTrendScore scores one point for every lookback between startLength and endLength the
        // price now sits above, and one against for every one it sits below. Before the series is that long
        // the missing bar counts as zero, so the price is above it and the point is scored.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = inputList[i];
            var score = 0d;

            for (var j = startLength; j <= endLength; j++)
            {
                var priorValue = i >= j ? inputList[i - j] : 0;
                score += currentValue >= priorValue ? 1 : -1;
            }

            output[i] = score;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Chop Zone using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChopZoneFast(StockData data, ComputeContext context, int length1 = 30,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length2 = 34)
    {
        length1 = Math.Max(1, length1); length2 = Math.Max(1, length2); var selected = data.ChainedValues.Count > 0; var close = selected ? data.ChainedValues : data.ClosePrices;
        var custom = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var average = context.Rent(close.Count);
        if (custom) MovingAverage(data, maType, length2, SpanCompat.AsReadOnlySpan(close), average.WritableSpan);
        using var window = new ChopZoneWindow(maType, length1, length2, close.Count); var result = context.Rent(close.Count);
        for (var i = 0; i < close.Count; i++) result.WritableSpan[i] = window.Next(data.HighPrices[i], data.LowPrices[i], close[i], selected, true, custom ? average.Span[i] : null);
        return result;
    }

    /// <summary>
    /// Computes Auto Line using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAutoLineFast(StockData data, ComputeContext context, int length = 500)
    {
        // CalculateAutoLine holds its line until the chained value escapes a band one windowed deviation either
        // side of it, then snaps the line to that value. TrendCore.AutoLine read the close and measured a
        // different band.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);
        var dev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevX = i >= 1 ? output[i - 1] : currentValue;

            output[i] = currentValue > prevX + dev[i] ? currentValue
                : currentValue < prevX - dev[i] ? currentValue
                : prevX;
        }

        return buffer;
    }

