        int length1 = 5, int length2 = 10, int length3 = 20)
    {
        // CalculateChandeMomentumOscillatorAverage averages the momentum reading over three windows. Unlike
        // its siblings it does not hold back the first bar, so the opening move counts as a full advance.
        var buffer = context.Rent(data.Count);
        MomentumOscillatorWindowAverage(data, buffer.WritableSpan, length1, length2, length3);

        return buffer;
    }

    /// <summary>
    /// Computes Double Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDoubleStochasticOscillatorFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length = 14, int smoothLength = 3, string? outputKey = null)
    {
        // CalculateDoubleStochasticOscillator rescales a raw stochastic against its own range and smooths
        // that once. The second smoothing there is the Signal line, not the series this arm is bound to.
        // Read the selected series directly: fallback smoothing may leave legacy signal metadata
        // on this shared batch context, which must not change a later output's input selection.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        using var stochasticBuffer = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length, stochasticBuffer.WritableSpan);
        var stochastic = stochasticBuffer.Span;

        using var doubleKBuffer = context.Rent(count);
        var doubleK = doubleKBuffer.WritableSpan;
        var stochasticWindow = new RollingMinMax(Math.Max(length, 2));

        for (var i = 0; i < count; i++)
        {
            stochasticWindow.Add(stochastic[i]);

            doubleK[i] = ClampedRangePosition.Percent(stochastic[i], stochasticWindow.Min, stochasticWindow.Max);
        }

        var buffer = context.Rent(count);
        StochasticSmooth(data, maType, smoothLength, doubleK, buffer.WritableSpan);

        if (outputKey != "Signal") return buffer;
        var signal = context.Rent(count);
        StochasticSmooth(data, maType, smoothLength, buffer.Span, signal.WritableSpan);
        buffer.Dispose();
        return signal;
    }

    /// <summary>
    /// Computes DTOscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDTOscillatorFast(StockData data, ComputeContext context, int length1 = 13,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, int length2 = 8, int length3 = 5, int length4 = 3, string? outputKey = null)
    {
        length1 = Math.Max(1, length1); var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); double[]? rsi = null;
        if (external) { var caller = data.CaptureInputSeries(); rsi = new double[input.Count]; RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(input), length1, maType, rsi); data.RestoreInputSeries(caller); }
        using var window = new DtOscillatorWindow(maType, length1, length2, length3, length4, external); var output = context.Rent(input.Count);
        try { for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true, rsi?[i]); output.WritableSpan[i] = outputKey == "Signal" ? point.SignalLine : point.Line; } return output; } catch { output.Dispose(); throw; }
    }

    /// <summary>
    /// Refuses the Compare Price Momentum Oscillator, which one series cannot produce.
    /// </summary>
    /// <remarks>
    /// CalculateComparePriceMomentumOscillator is PMO(stock) - PMO(market): it takes a second StockData and
    /// subtracts that series' oscillator. A one-series arm has nothing to subtract, and this one used to hand
    /// back a plain single-series PMO under the compare indicator's name - a different indicator, served
    /// silently. The multi-series path is the one that computes this: IndicatorCatalog's overload passes both
    /// handles through MultiStockIndicatorOptions, and SeriesEvaluator computes it from
    /// ComparePriceMomentumOscillatorState. Refusing here keeps the wrong series from reaching a caller if the
    /// obsolete one-series options type is ever served.
    /// </remarks>
    internal static ComputeBuffer ComputeComparePriceMomentumOscillatorFast(StockData data, ComputeContext context, int length = 35)
    {
        throw new CalculationException(
            "ComparePriceMomentumOscillator compares a stock against a market series, so it cannot be computed "
            + "from one series. Use IndicatorCatalog.ComparePriceMomentumOscillator, which takes the market "
            + "series as a handle.");
    }

    /// <summary>
    /// Computes Daily Average Price Delta using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDailyAveragePriceDeltaFast(StockData data, ComputeContext context,
        int length = 21, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool lower = false)
    {
        length=Math.Max(1,length);var high=data.HighPrices;var low=data.LowPrices;var output=context.Rent(high.Count);
        using var window=new DailyDeltaWindow(maType,length,high.Count);
        if(ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var ah=context.Rent(high.Count);using var al=context.Rent(low.Count);
            MovingAverage(data,maType,length,SpanCompat.AsReadOnlySpan(high),ah.WritableSpan);MovingAverage(data,maType,length,SpanCompat.AsReadOnlySpan(low),al.WritableSpan);
            for(var i=0;i<high.Count;i++){var v=DailyDeltaWindow.Finish(high[i],low[i],ah.Span[i],al.Span[i]);output.WritableSpan[i]=lower?v.Lower:v.Upper;}
        }
        else for(var i=0;i<high.Count;i++){var v=window.Next(high[i],low[i],true);output.WritableSpan[i]=lower?v.Lower:v.Upper;}
        return output;
    }

    /// <summary>
    /// Computes Drunkard Walk from the selected candle ranges.
    /// </summary>
    internal static ComputeBuffer ComputeDrunkardWalkFast(StockData data, ComputeContext context, int length1 = 80, int length2 = 14, bool down = false)
    {
        _ = length2;
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var buffer = context.Rent(input.Count); var window = new DrunkardWalkWindow(length1);
        for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], true); buffer.WritableSpan[i] = down ? point.Down : point.Up; }
        return buffer;
    }

    internal static ComputeBuffer ComputeDemandOscillatorFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length1 = 10, int length2 = 2,
        int length3 = 20, bool signal = false)
    {
        var (input, high, low, _, volume) = CalculationsHelper.GetInputValuesList(data);
        var buffer = context.Rent(input.Count);
        if (!StrengthWindow.Supports(maType) || ComponentAverage.HasOverrides)
        {
            var components = DemandOscillatorWindow.Components(data, input, high, low, maType, length1, length2, length3, true, signal);
            (signal ? components.Signal : components.Line).AsSpan().CopyTo(buffer.WritableSpan);
        }
        else
        {
            using var window = new DemandOscillatorWindow(maType, length1, length2, length3);
            for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], volume[i], true); buffer.WritableSpan[i] = signal ? point.SignalLine : point.Line; }
        }
        return buffer;
    }

    /// <summary>
    /// Computes Double Smoothed Relative Strength Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDoubleSmoothedRelativeStrengthIndexFast(StockData data, ComputeContext context, int length1 = 2,
        int length2 = 5, int length3 = 25, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string outputKey = "Dsrsi") =>
        ComputeRangeGainLossFast(data, context, maType, Math.Max(2, length1), new[] { length2, length3 }, length3, outputKey);

    internal static ComputeBuffer ComputeMomentaRelativeStrengthIndexFast(StockData data, ComputeContext context, int length1 = 2,
        int length2 = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string outputKey = "Mrsi") =>
        ComputeRangeGainLossFast(data, context, maType, Math.Max(1, length1), new[] { length2 }, length2, outputKey);

    private static ComputeBuffer ComputeRangeGainLossFast(StockData data, ComputeContext context, MovingAvgType kind,
        int lookback, int[] periods, int signalLength, string outputKey)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = input.Count;
        var buffer = context.Rent(count);
        if (StrengthWindow.Supports(kind) && !ComponentAverage.HasOverrides)
        {
            using var window = new RangeGainLossWindow(kind, lookback, periods, signalLength, count);
            for (var i = 0; i < count; i++)
            {
                var next = window.Next(input[i], true);
                buffer.WritableSpan[i] = outputKey == "Signal" ? next.Signal : next.Value;
            }
            return buffer;
        }
        var up = new double[count]; var down = new double[count];
        var range = new RollingMinMax(lookback);
        for (var i = 0; i < count; i++)
        {
            range.Add(input[i]); up[i] = input[i] - range.Min; down[i] = range.Max - input[i];
        }
        foreach (var period in periods)
        {
            var next = new double[count]; MovingAverage(data, kind, period, up, next); up = next;
        }
        foreach (var period in periods)
        {
            var next = new double[count]; MovingAverage(data, kind, period, down, next); down = next;
        }
        for (var i = 0; i < count; i++) buffer.WritableSpan[i] = down[i] == 0 ? 100 : up[i] == 0 ? 0 : Math.Max(0, Math.Min(100, 100 * up[i] / (up[i] + down[i])));
        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, signalLength, kind) : buffer;
    }

    /// <summary>
    /// Computes Dynamic Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDynamicMomentumOscillatorFast(StockData data, ComputeContext context,
        int length1 = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length2 = 20)
    {
        // CalculateDynamicMomentumOscillator smooths a length1 stochastic by length1 and again by length2,
        // then swings the midpoint of the running range of the faster line by the gap between the two.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var high = SpanCompat.AsReadOnlySpan(highList);
        var low = SpanCompat.AsReadOnlySpan(lowList);
        var count = inputList.Count;

        using var fastBuffer = context.Rent(count);
        var fast = fastBuffer.WritableSpan;
        var highWindow = new RollingMinMax(length1);
        var lowWindow = new RollingMinMax(length1);

        for (var i = 0; i < count; i++)
        {
            highWindow.Add(high[i]);
            lowWindow.Add(low[i]);

            fast[i] = ClampedRangePosition.Percent(input[i], lowWindow.Min, highWindow.Max);
        }

        using var smoothedBuffer = context.Rent(count);
        using var signalBuffer = context.Rent(count);
        StochasticSmooth(data, maType, length1, fast, smoothedBuffer.WritableSpan);
        StochasticSmooth(data, maType, length2, smoothedBuffer.Span, signalBuffer.WritableSpan);

        var smoothed = smoothedBuffer.Span;
        var signal = signalBuffer.Span;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double highest = 0;
        var lowest = double.MaxValue;

        for (var i = 0; i < count; i++)
        {
            var value = smoothed[i];
            highest = value > highest ? value : highest;
            lowest = value < lowest ? value : lowest;

            var midpoint = MathHelper.MinOrMax((lowest + highest) / 2, 100, 0);
            output[i] = MathHelper.MinOrMax(midpoint - (signal[i] - value), 100, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Average Money Flow Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAverageMoneyFlowOscillatorFast(StockData data, ComputeContext context, int length = 5, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, int smoothLength = 3)
    {
        var (input, _, _, _, volumes) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        var components = external ? AverageMoneyFlowWindow.Components(data, input, volumes, maType, length, smoothLength) : null; using var window = new AverageMoneyFlowWindow(maType, length, smoothLength, external);
        var output = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = window.Next(input[i], volumes[i], true, components?[0][i], components?[1][i], components?[2][i]).Value; return output; } catch { output.Dispose(); throw; }
    }

    /// <summary>
    /// Computes DMI Stochastic using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDMIStochasticFast(StockData data, ComputeContext context,
        int length1 = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length2 = 10,
        int length3 = 3, int length4 = 3)
    {
        // CalculateDMIStochastic rescales the gap between the two directional indicators against its own
        // length2 range and then smooths that twice, with whichever average it was given.
        var (plusBuffer, minusBuffer) = DirectionalIndicators(data, context, length1, maType);
        using var diPlusBuffer = plusBuffer;
        using var diMinusBuffer = minusBuffer;
        var diPlus = diPlusBuffer.Span;
        var diMinus = diMinusBuffer.Span;
        var count = diPlus.Length;

        using var fastKBuffer = context.Rent(count);
        var fastK = fastKBuffer.WritableSpan;
        var window = new RollingMinMax(Math.Max(length2, 2));

        for (var i = 0; i < count; i++)
        {
            var oscillator = diMinus[i] - diPlus[i];
            window.Add(oscillator);

            var range = window.Max - window.Min;
            fastK[i] = range != 0 ? MathHelper.MinOrMax((oscillator - window.Min) / range * 100, 100, 0) : 0;
        }

        using var slowKBuffer = context.Rent(count);
        MovingAverage(data, maType, length3, fastK, slowKBuffer.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length4, slowKBuffer.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes CCT Stoch RSI using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeCCTStochRelativeStrengthIndexFast(StockData data, ComputeContext context,
        int length2 = 8, int length3 = 13, int length5 = 21, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        string? outputKey = null, int length1 = 5, int length4 = 14, int smoothLength1 = 3, int smoothLength2 = 8)
    {
        var (rsiLength, numeratorLength, lowLength, highLength, smoothing) = outputKey switch
        {
            "Type2" => (length5, length5, length5, length5, 0),
            "Type3" => (length4, length4, length4, length4, 0),
            "Type4" => (length5, length3, length3, length2, smoothLength2),
            "Type5" => (length1, length1, length1, length1, smoothLength1),
            "Type6" => (length3, length3, length3, length3, smoothLength1),
            "TypeCustom" => (length2, length2, length2, length2, smoothLength1),
            "Signal" => (length5, length2, length3, length3, 9),
            _ => (length5, length2, length3, length3, 0)
        };
        using var rsi = ComputeRsiFast(data, context, rsiLength, maType);
        var strength = rsi.Span;
        var numeratorWindow = new RollingMinMax(numeratorLength);
        var lowWindow = new RollingMinMax(lowLength);
        var highWindow = new RollingMinMax(highLength);
        var buffer = context.Rent(strength.Length);
        var output = buffer.WritableSpan;
        for (var i = 0; i < strength.Length; i++)
        {
            numeratorWindow.Add(strength[i]);
            lowWindow.Add(strength[i]);
            highWindow.Add(strength[i]);
            output[i] = CctRsiRatio.Percent(strength[i], numeratorWindow.Min, lowWindow.Min, highWindow.Max);
        }
        return smoothing > 0 ? SmoothStrength(data, context, buffer, smoothing, maType) : buffer;
    }

    /// <summary>
    /// Computes Bilateral Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeBilateralStochasticOscillatorFast(StockData data, ComputeContext context, int length = 100, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null, int signalLength = 20)
    {
        if (outputKey is not (null or "Bso" or "Bull" or "Bear" or "Signal")) throw new ArgumentOutOfRangeException(nameof(outputKey));
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        var components = external ? BilateralStochasticWindow.Components(data, input, maType, length, signalLength) : null; using var window = new BilateralStochasticWindow(maType, length, signalLength, external);
        var output = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true, components?[0][i], components?[1][i], components?[2][i]); output.WritableSpan[i] = outputKey == "Bull" ? point.Bull : outputKey == "Bear" ? point.Bear : outputKey == "Signal" ? point.SignalLine : point.Bso; } return output; } catch { output.Dispose(); throw; }
    }

