    /// <summary>
    /// Computes Rex Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNormalizedVigorFast(StockData data, ComputeContext context, int length, MovingAvgType kind, string? outputKey = null)
    {
        var input=data.ChainedValues.Count>0?data.ChainedValues:data.InputValues; var output=context.Rent(input.Count);
        if(ComponentAverage.HasOverrides || (!StrengthWindow.Supports(kind) && kind!=MovingAvgType.SymmetricallyWeightedMovingAverage))
        {
            length=Math.Max(1,length); using var bodies=context.Rent(input.Count); using var ranges=context.Rent(input.Count); using var body=context.Rent(input.Count); using var range=context.Rent(input.Count); using var ratios=context.Rent(input.Count);
            for(var i=0;i<input.Count;i++){bodies.WritableSpan[i]=NormalizedVigorWindow.Difference(input[i],data.OpenPrices[i]).Publish();ranges.WritableSpan[i]=NormalizedVigorWindow.Difference(data.HighPrices[i],data.LowPrices[i]).Publish();}
            MovingAverage(data,kind,length,bodies.Span,body.WritableSpan);MovingAverage(data,kind,length,ranges.Span,range.WritableSpan);
            using var window=new NormalizedVigorWindow(kind,length,input.Count);for(var i=0;i<input.Count;i++)ratios.WritableSpan[i]=window.Ratio(new RocBankValue(body.Span[i]),new RocBankValue(range.Span[i]),true).Publish();
            if(outputKey=="Signal")MovingAverage(data,kind,length,ratios.Span,output.WritableSpan);else ratios.Span.CopyTo(output.WritableSpan);
        }
        else {using var window=new NormalizedVigorWindow(kind,length,input.Count);for(var i=0;i<input.Count;i++){var r=window.Next(input[i],data.OpenPrices[i],data.HighPrices[i],data.LowPrices[i],true);output.WritableSpan[i]=outputKey=="Signal"?r.Signal:r.Value;}}
        return output;
    }

    internal static ComputeBuffer ComputeRexOscillatorFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, bool signal = false)
    {
        length = Math.Max(1, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var output = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var tvb = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) tvb.WritableSpan[i] = RexWindow.TrueValue(input[i], data.OpenPrices[i], data.HighPrices[i], data.LowPrices[i]).Publish();
            if (signal) { using var first = context.Rent(input.Count); MovingAverage(data, maType, length, tvb.Span, first.WritableSpan); MovingAverage(data, maType, length, first.Span, output.WritableSpan); } else MovingAverage(data, maType, length, tvb.Span, output.WritableSpan);
        }
        else { using var window = new RexWindow(maType, length, input.Count); for (var i = 0; i < input.Count; i++) { var r = window.Next(input[i], data.OpenPrices[i], data.HighPrices[i], data.LowPrices[i], true); output.WritableSpan[i] = signal ? r.Signal : r.Value; } }
        return output;
    }

    /// <summary>
    /// Computes Sentiment Zone Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSentimentZoneOscillatorFast(StockData data, ComputeContext context, int fastLength = 14,
        MovingAvgType maType = MovingAvgType.TripleExponentialMovingAverage)
    {
        // CalculateSentimentZoneOscillator scores each bar of the chained series as plus or minus one against
        // the bar before it, smooths that score and scales it by the fast length. The slow length and the
        // factor only place the overbought and oversold levels, which this series is not. The core this
        // replaced read the close and the volume, and the volume has no part in this indicator.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var scores = context.Rent(count);
        var r = scores.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            r[i] = input[i] > prevValue ? 1 : -1;
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, fastLength, scores.Span, smoothed.WritableSpan);
        var sp = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = fastLength != 0 ? 100 * sp[i] / fastLength : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Wave Trend Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWaveTrendOscillatorFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 21, int smoothLength = 4, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        var signal = outputKey == "Signal";
        var values = WaveTrendWindow.Calculate(data, maType, length1, length2, smoothLength, fast: true, includeSignal: signal);
        var selected = signal ? values.SignalLine : values.Line; var output = context.Rent(selected.Length);
        try { selected.AsSpan().CopyTo(output.WritableSpan); return output; } catch { output.Dispose(); throw; }
    }

    /// <summary>
    /// Computes WAMI Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWamiOscillatorFast(StockData data, ComputeContext context, int length1 = 13,
        int length2 = 4, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateWamiOscillator smooths the first difference of the chained series three times: a weighted
        // average over the short length, then the chosen average twice over the long one. The core routine
        // took high, low and close and had no second length.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var window = new WamiWindow(maType, length1, length2, count);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = window.Next(input[i], true);
            return stable;
        }

        using var difference = context.Rent(count);
        var diff = difference.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            diff[i] = CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue);
        }

        using var weighted = context.Rent(count);
        MovingAverageCore.WeightedMovingAverage(difference.Span, weighted.WritableSpan, length2);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length1, weighted.Span, smoothed.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length1, smoothed.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Volume Accumulation Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVolumeAccumulationOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var output = context.Rent(input.Count);
        using var window = new VolumeBalanceWindow(length, VolumeBalanceKind.Accumulation);
        for (var i = 0; i < input.Count; i++)
            output.WritableSpan[i] = window.Next(data.OpenPrices[i], data.HighPrices[i], data.LowPrices[i], input[i], data.Volumes[i], true);
        return output;
    }

