    /// <summary>
    /// Computes Smoothed Delta Ratio Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSmoothedDeltaRatioOscillatorFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSmoothedDeltaRatioOscillator measures how much of the series' movement over the window the
        // moving average kept: the average's change across the window divided by the smoothed absolute change
        // of the series itself, clamped to the unit interval.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var window = new SmoothedDeltaWindow(maType, length, count);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = window.Next(inputList[i], true);
            return stable;
        }

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        using var absoluteChange = context.Rent(count);
        using var averageChange = context.Rent(count);
        var absChg = absoluteChange.WritableSpan;
        var b = averageChange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            var prevSma = i >= length ? sma[i - length] : 0;

            absChg[i] = Math.Abs(CalculationsHelper.MinPastValues(i, length, input[i] - prevValue));
            b[i] = CalculationsHelper.MinPastValues(i, length, sma[i] - prevSma);
        }

        using var smoothedChange = context.Rent(count);
        MovingAverage(data, maType, length, absoluteChange.Span, smoothedChange.WritableSpan);
        var a = smoothedChange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = a[i] != 0 ? MathHelper.MinOrMax(b[i] / a[i], 1, 0) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fast Slow Degree Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFastSlowDegreeOscillatorFast(StockData data, ComputeContext context,
        int length = 100, int fastLength = 3, int slowLength = 2, int signalLength = 14,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        var (prices, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var external = !StrengthWindow.Supports(maType) || ComponentAverage.HasOverrides;
        using var window = new FastSlowDegreeWindow(maType, length, fastLength, slowLength, signalLength, external);
        var component = series != MacdSeries.Line && external ? FastSlowDegreeWindow.ComponentSignal(data, prices, maType, length, fastLength, slowLength, signalLength, true) : null;
        var buffer = context.Rent(prices.Count);
        for (var i = 0; i < prices.Count; i++) { var point = window.Next(prices[i], true, component?[i], series != MacdSeries.Line); buffer.WritableSpan[i] = series == MacdSeries.Signal ? point.SignalLine : series == MacdSeries.Histogram ? point.Histogram : point.Line; }
        return buffer;
    }

    /// <summary>
    /// Computes Robust Weighting Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRobustWeightingOscillatorFast(StockData data, ComputeContext context, int length = 200,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateRobustWeightingOscillator fits the chained series against the bar index - the correlation
        // scaled by the ratio of the two standard deviations gives the slope, and the two moving averages give
        // the intercept - then smooths the residual the fit leaves behind. OscillatorCore.RobustWeightingOscillator
        // took the close and measured something else.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var window = Math.Max(length, 1);

        using var index = context.Rent(count);
        var indexValues = index.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            indexValues[i] = i;
        }

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        using var indexAverage = context.Rent(count);
        MovingAverage(data, maType, length, index.Span, indexAverage.WritableSpan);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, window);
        using var indexDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(index.Span, indexDeviation.WritableSpan, window);

        using var residual = context.Rent(count);
        var l = residual.WritableSpan;
        var correlation = new RollingCorrelation();
        for (var i = 0; i < count; i++)
        {
            correlation.Add(i, input[i]);
            var corr = correlation.R(length);
            corr = MathHelper.IsValueNullOrInfinity(corr) ? 0 : corr;

            var slope = indexDeviation.Span[i] != 0 ? corr * (deviation.Span[i] / indexDeviation.Span[i]) : 0;
            var intercept = average.Span[i] - (slope * indexAverage.Span[i]);
            l[i] = input[i] - slope - (intercept * input[i]);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, residual.Span, buffer.WritableSpan);
        return buffer;
    }

