    /// <summary>
    /// Computes Ehlers Universal Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersUniversalSignalFast(StockData data, ComputeContext context, int length, MovingAvgType maType)
    {
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        { using var line = ComputeEhlersUniversalOscillatorFast(data, context, length); var result = context.Rent(data.Count); MovingAverage(data, maType, 9, line.Span, result.WritableSpan); return result; }
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var buffer = context.Rent(input.Count);
        using var window = new UniversalOscillatorWindow(maType, length);
        for (var i = 0; i < input.Count; i++) buffer.WritableSpan[i] = window.Next(input[i], true).Signal;
        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersUniversalOscillatorFast(StockData data, ComputeContext context, int length = 20)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var buffer = context.Rent(input.Count);
        using var window = new UniversalOscillatorWindow(MovingAvgType.ExponentialMovingAverage, length);
        for (var i = 0; i < input.Count; i++) buffer.WritableSpan[i] = window.Line(input[i], true);
        return buffer;
    }


    /// <summary>
    /// Computes Ehlers Recursive Median Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersRecursiveMedianOscillatorFast(StockData data, ComputeContext context, int length1 = 5, int length2 = 12, int length3 = 30)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var window = new RecursiveMedianOscillatorWindow(length1, length2, length3); var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = window.Next(input[i], true);
        return output;
    }


    /// <summary>
    /// Computes Ehlers Stochastic Center of Gravity Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersStochasticCenterOfGravityOscillatorFast(StockData data, ComputeContext context, int length = 8)
    {
        var input=data.ChainedValues.Count>0?data.ChainedValues:data.InputValues;var output=context.Rent(input.Count);using var window=new StochasticGravityWindow(length,input.Count);for(var i=0;i<input.Count;i++)output.WritableSpan[i]=window.Next(input[i],true);return output;
    }

    /// <summary>
    /// Computes Ehlers Fisherized Deviation Scaled Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersFisherizedDeviationScaledOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 20, int slowLength = 40)
    {
        // CalculateEhlersFisherizedDeviationScaledOscillator fisherises the deviation scaled moving average
        // itself, holding the previous reading whenever that average leaves the transform's domain. Its slow
        // length is the average's own, not twice the fast one, so it needs the two length helper.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var scaled = context.Rent(count);
        EhlersDeviationScaledMovingAverage(data, context, SpanCompat.AsReadOnlySpan(inputList), fastLength, slowLength,
            MovingAvgType.Ehlers2PoleSuperSmootherFilterV2, scaled.WritableSpan);
        var filter = scaled.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var half = filter[i] / 2;
            output[i] = Math.Abs(filter[i]) < 2 ? FisherArithmetic.Transform(half) : i >= 1 ? output[i - 1] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Adaptive Center of Gravity Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersAdaptiveCenterOfGravityOscillatorFast(StockData data, ComputeContext context, int length = 5)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var window = new AdaptiveGravityWindow(length); var result = context.Rent(selected.Count);
        for (var i = 0; i < selected.Count; i++) result.WritableSpan[i] = window.Next(selected[i], true);
        return result;
    }

    /// <summary>
    /// Computes Ehlers' adaptive cyber cycle and the dominant cycle period it measures, so that indicators
    /// built on either series can reach it without materialising a second indicator's output dictionary.
    /// </summary>
    internal static ComputeBuffer ComputeDominantCycleTunedRsiFast(StockData data, ComputeContext context, int length = 5)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var window = new CycleTunedRsiWindow(length); var result = context.Rent(selected.Count);
        for (var i = 0; i < selected.Count; i++) result.WritableSpan[i] = window.Next(selected[i], true);
        return result;
    }

    internal static ComputeBuffer ComputeEhlersAdaptiveCyberCycleFast(StockData data, ComputeContext context, int length = 5, double alpha = .07, bool periodOutput = false)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var window = new AdaptiveCyberWindow(length, alpha); var result = context.Rent(selected.Count);
        for (var i = 0; i < selected.Count; i++) { var point = window.Next(selected[i], true); result.WritableSpan[i] = periodOutput ? point.Period : point.Cycle; }
        return result;
    }
    private static void EhlersAdaptiveCyberCycle(ComputeContext context, ReadOnlySpan<double> input, int length,
        double alpha, Span<double> adaptiveCycle, Span<double> period)
    {
        var window = new AdaptiveCyberWindow(length, alpha);
        for (var i = 0; i < input.Length; i++) { var point = window.Next(input[i], true); adaptiveCycle[i] = point.Cycle; period[i] = point.Period; }
    }

    #endregion

    #region Additional Oscillators (Batch 12) - Vervoort and Specialized

    /// <summary>
    /// Computes Vervoort Smoothed Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the Vervoort smoothed oscillator's two published series an arm has been asked for: the
    /// position of the zero-lag rainbow within its own band, or the smoothed stochastic of the rainbow.
    /// </summary>
    internal enum VervoortSmoothedSeries
    {
        Oscillator,
        Stochastic
    }

    internal static ComputeBuffer ComputeVervoortSmoothedOscillatorFast(StockData data, ComputeContext context,
        int length1 = 18, int length2 = 30, int length3 = 2, int smoothLength = 3, double stdDevMult = 2,
        VervoortSmoothedSeries series = VervoortSmoothedSeries.Oscillator)
    {
        // CalculateVervoortSmoothedOscillator builds a rainbow from ten successive simple averages of the
        // close, weighted 5-4-3-2 then 1 apiece, zero-lags it through a pair of exponential averages, smooths
        // that with a triple exponential average, and reports where the result sits inside a band of
        // stdDevMult deviations about its own weighted average. The stochastic leg takes its numerator from
        // the lowest LOW of the window and its denominator from the lowest rainbow-close midpoint, which is a
        // mismatch in the batch that is reproduced here rather than corrected.
        var (inputList, highList, lowList, _, closeList, _) =
            CalculationsHelper.GetInputValuesList(InputName.TypicalPrice, data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(highList);
        var lows = SpanCompat.AsReadOnlySpan(lowList);
        var closes = SpanCompat.AsReadOnlySpan(closeList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);
        smoothLength = Math.Max(smoothLength, 1);

        using var stageA = context.Rent(count);
        using var stageB = context.Rent(count);
        using var rainbowBuffer = context.Rent(count);
        var rainbow = rainbowBuffer.WritableSpan;
        rainbow.Clear();

        Span<int> weights = stackalloc int[10] { 5, 4, 3, 2, 1, 1, 1, 1, 1, 1 };
        var intoA = true;
        ReadOnlySpan<double> source = closes;
        for (var stage = 0; stage < weights.Length; stage++)
        {
            var destination = intoA ? stageA.WritableSpan : stageB.WritableSpan;
            MovingAverage(data, MovingAvgType.SimpleMovingAverage, length3, source, destination);
            for (var i = 0; i < count; i++)
            {
                rainbow[i] += weights[stage] * destination[i];
            }

            source = intoA ? stageA.Span : stageB.Span;
            intoA = !intoA;
        }

        for (var i = 0; i < count; i++)
        {
            rainbow[i] /= 20;
        }

        using var ema1 = context.Rent(count);
        using var ema2 = context.Rent(count);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, smoothLength, rainbowBuffer.Span, ema1.WritableSpan);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, smoothLength, ema1.Span, ema2.WritableSpan);

        using var zeroLagRainbow = context.Rent(count);
        var zlrb = zeroLagRainbow.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            zlrb[i] = (2 * ema1.Span[i]) - ema2.Span[i];
        }

        using var smoothedRainbow = context.Rent(count);
        MovingAverage(data, MovingAvgType.TripleExponentialMovingAverage, smoothLength, zeroLagRainbow.Span,
            smoothedRainbow.WritableSpan);
        var tz = smoothedRainbow.Span;

        using var halfWidth = context.Rent(count);
        using var weightedSmoothed = context.Rent(count);
        VolatilityCore.StandardDeviation(tz, halfWidth.WritableSpan, length1);
        MovingAverage(data, MovingAvgType.WeightedMovingAverage, length1, tz, weightedSmoothed.WritableSpan);
        var hwidth = halfWidth.Span;
        var wmatz = weightedSmoothed.Span;

        using var bandPosition = !ComponentAverage.HasOverrides ? new Streaming.VervoortBandPosition(length1, length3, smoothLength, stdDevMult) : null;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length2);
        var lowWindow = new RollingMinMax(length2);
        var midpointWindow = new RollingMinMax(length2);
        var fastKSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var rbc = (rainbow[i] + input[i]) / 2;
            midpointWindow.Add(rbc);
            var den = highWindow.Max - midpointWindow.Min;
            var fastK = den != 0 ? MathHelper.MinOrMax(100 * (rbc - lowWindow.Min) / den, 100, 0) : 0;
            fastKSum.Add(fastK);

            output[i] = series == VervoortSmoothedSeries.Stochastic
                ? fastKSum.Average(smoothLength)
                : bandPosition is not null ? bandPosition.Next(closes[i], true) : stdDevMult * hwidth[i] != 0 ? 100 * (tz[i] + (stdDevMult * hwidth[i]) - wmatz[i]) / (2 * stdDevMult * hwidth[i]) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Relative Difference of Squares Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRelativeDifferenceOfSquaresOscillatorFast(StockData data, ComputeContext context, int length = 20)
    {
        // CalculateRelativeDifferenceOfSquaresOscillator publishes "Rdos": the squared count of advances less
        // the squared count of declines, over the squared total of advances, declines and unchanged bars.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var advances = new RollingSum();
        var declines = new RollingSum();
        var unchanged = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;

            advances.Add(input[i] > prevValue ? 1 : 0);
            declines.Add(input[i] < prevValue ? 1 : 0);
            unchanged.Add(input[i] == prevValue ? 1 : 0);

            var aSum = advances.Sum(length);
            var dSum = declines.Sum(length);
            var nSum = unchanged.Sum(length);
            output[i] = aSum > 0 || dSum > 0 || nSum > 0
                ? (MathHelper.Pow(aSum, 2) - MathHelper.Pow(dSum, 2)) / MathHelper.Pow(aSum + nSum + dSum, 2) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Linear Quadratic Convergence Divergence Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearQuadraticConvergenceDivergenceOscillatorFast(StockData data, ComputeContext context,
        int length = 50, int signalLength = 25, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var result = LinearQuadraticWindow.Calculate(data, maType, length, signalLength);
            var exactBuffer = context.Rent(result.Values.Count);
            for (var i = 0; i < result.Values.Count; i++) exactBuffer.WritableSpan[i] = result.Values[i];
            return exactBuffer;
        }
        // CalculateLinearQuadraticConvergenceDivergenceOscillator publishes its HISTOGRAM as "Lqcdo": the
        // quadratic regression less the linear one is the convergence line, and the histogram takes its
        // signal average off that line twice over, once to make the oscillator and once again to make the
        // histogram. Both regressions read the caller's series rather than each other's output, which is
        // what the batch's CaptureInputSeries and RestoreInputSeries pair is there to guarantee.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var linear = context.Rent(count);
        var linreg = linear.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                linreg[i] = regression.Next(input[i], isFinal: true).Last;
            }
        }

        using var quadratic = ComputeQuadraticRegressionFast(data, context, length, maType);
        var quadreg = quadratic.Span;

        using var convergence = context.Rent(count);
        var lqcd = convergence.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            lqcd[i] = quadreg[i] - linreg[i];
        }

        using var signalLine = context.Rent(count);
        MovingAverage(data, maType, signalLength, convergence.Span, signalLine.WritableSpan);
        var sign = signalLine.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var oscillator = convergence.Span[i] - sign[i];
            output[i] = oscillator - sign[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stationary Extrapolated Levels Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStationaryExtrapolatedLevelsOscillatorFast(StockData data, ComputeContext context, int length = 200,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateStationaryExtrapolatedLevelsOscillator detrends the series by its moving average, then
        // extrapolates that residual forward from the values one and two windows back, and publishes the raw
        // stochastic of the extrapolation over twice the length. The extrapolation, not the close, is the
        // series the stochastic is taken of.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, input, smoothed.WritableSpan);
        var sma = smoothed.Span;

        using var residual = context.Rent(count);
        using var extrapolated = context.Rent(count);
        var y = residual.WritableSpan;
        var ext = extrapolated.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            y[i] = input[i] - sma[i];

            var prevY = i >= length ? y[i - length] : 0;
            var prevY2 = i >= length * 2 ? y[i - (length * 2)] : 0;
            ext[i] = ((2 * prevY) - prevY2) / 2;
        }

        var buffer = context.Rent(count);
        StochasticFastK(data, context, extrapolated.Span, length * 2, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Percentage Price Oscillator Leader using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePercentagePriceOscillatorLeaderFast(StockData data, ComputeContext context,
        int fastLength = 12, int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
        => ComputeLeaderOscillatorFast(data, context, fastLength, slowLength, 9, maType, true, "Ppo");

    internal static ComputeBuffer ComputeLeaderOscillatorFast(StockData data, ComputeContext context, int fastLength,
        int slowLength, int signalLength, MovingAvgType maType, bool percentage, string key)
    {
        var values = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        double[] Smooth(IReadOnlyList<double> input, int period)
        {
            var finite = FiniteSignalInput.Create(input, out var count);
            var output = new double[finite.Count];
            StochasticSmooth(data, maType, period, SpanCompat.AsReadOnlySpan(finite), output);
            for (var i = count; i < output.Length; i++) output[i] = double.NaN;
            return output;
        }
        var fast = Smooth(values, fastLength);
        var slow = Smooth(values, slowLength);
        var fastDistance = Smooth(values.Select((v, i) => v - fast[i]).ToArray(), fastLength);
        var slowDistance = Smooth(values.Select((v, i) => v - slow[i]).ToArray(), slowLength);
        var first = fast.Select((v, i) => v + fastDistance[i]).ToArray();
        var second = slow.Select((v, i) => v + slowDistance[i]).ToArray();
        var macd = first.Select((v, i) => v - second[i]).ToArray();
        // The MACD signal is an unpublished customer stage, also consumed by PPO's batch composition.
        _ = Smooth(macd, signalLength);
        var line = percentage ? first.Select((v, i) => RoundedFractionalEma.Percentage(v, second[i])).ToArray() : macd;
        var signal = percentage ? Smooth(line, signalLength) : Array.Empty<double>();
        var result = context.Rent(values.Count);
        for (var i = 0; i < values.Count; i++) result.WritableSpan[i] = key switch
        {
            "I1" => first[i], "I2" => second[i], "Signal" => signal[i], "Histogram" => line[i] - signal[i], _ => line[i]
        };
        return result;
    }


    /// <summary>
    /// Computes Kaufman Adaptive Correlation Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the three series the Kaufman adaptive correlation routine publishes.
    /// </summary>
    internal enum KaufmanCorrelationSeries
    {
        /// <summary>The correlation itself.</summary>
        Correlation,

        /// <summary>The standardised bar index.</summary>
        IndexStandardised,

        /// <summary>The standardised source series.</summary>
        SourceStandardised
    }

    internal static ComputeBuffer ComputeKaufmanAdaptiveCorrelationOscillatorFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.KaufmanAdaptiveMovingAverage,
        KaufmanCorrelationSeries series = KaufmanCorrelationSeries.Correlation)
    {
        // CalculateKaufmanAdaptiveCorrelationOscillator is the Pearson correlation of the chained series with
        // the bar index, with every moment taken through the adaptive average rather than a plain window.
        // OscillatorCore.KaufmanAdaptiveCorrelationOscillator read the close and used neither the chained
        // series nor that average.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        // Both standardised series are filled by the routine and were being disposed unused, which is why
        // their keys answered with the correlation.
        var indexDeviation = context.Rent(count);
        var sourceDeviation = context.Rent(count);
        var correlation = context.Rent(count);
        KaufmanAdaptiveCorrelation(data, context, input, length, maType, indexDeviation.WritableSpan,
            sourceDeviation.WritableSpan, correlation.WritableSpan);

        switch (series)
        {
            case KaufmanCorrelationSeries.IndexStandardised:
                sourceDeviation.Dispose();
                correlation.Dispose();
                return indexDeviation;
            case KaufmanCorrelationSeries.SourceStandardised:
                indexDeviation.Dispose();
                correlation.Dispose();
                return sourceDeviation;
            default:
                indexDeviation.Dispose();
                sourceDeviation.Dispose();
                return correlation;
        }
    }

    // The three series CalculateKaufmanAdaptiveCorrelationOscillator publishes - IndexSt, SrcSt and Kaco -
    // in one pass, so the oscillator arm and the least squares average that reads all three cannot drift
    // apart. Every moment is smoothed with the same adaptive average the batch uses.
    private static void KaufmanAdaptiveCorrelation(StockData data, ComputeContext context, ReadOnlySpan<double> input,
        int length, MovingAvgType maType, Span<double> indexDeviation, Span<double> sourceDeviation,
        Span<double> correlation)
    {
        var count = input.Length;
        if (maType == MovingAvgType.KaufmanAdaptiveMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var moments = new Streaming.KaufmanRegressionMoments(length);
            for (var i = 0; i < count; i++)
                moments.Next(input[i], true, out indexDeviation[i], out sourceDeviation[i], out correlation[i]);
            return;
        }


        using var indexes = context.Rent(count);
        using var indexSource = context.Rent(count);
        using var indexSquared = context.Rent(count);
        using var sourceSquared = context.Rent(count);
        var index = indexes.WritableSpan;
        var indexSource1 = indexSource.WritableSpan;
        var index2 = indexSquared.WritableSpan;
        var source2 = sourceSquared.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            index[i] = i;
            indexSource1[i] = i * input[i];
            source2[i] = input[i] * input[i];
            index2[i] = index[i] * index[i];
        }

        using var sourceAverage = context.Rent(count);
        using var indexAverage = context.Rent(count);
        using var indexSourceAverage = context.Rent(count);
        using var indexSquaredAverage = context.Rent(count);
        using var sourceSquaredAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, sourceAverage.WritableSpan);
        MovingAverage(data, maType, length, indexes.Span, indexAverage.WritableSpan);
        MovingAverage(data, maType, length, indexSource.Span, indexSourceAverage.WritableSpan);
        MovingAverage(data, maType, length, indexSquared.Span, indexSquaredAverage.WritableSpan);
        MovingAverage(data, maType, length, sourceSquared.Span, sourceSquaredAverage.WritableSpan);

        for (var i = 0; i < count; i++)
        {
            var sourceMa = sourceAverage.Span[i];
            var indexMa = indexAverage.Span[i];

            var indexVariance = indexSquaredAverage.Span[i] - MathHelper.Pow(indexMa, 2);
            indexDeviation[i] = indexVariance >= 0 ? MathHelper.Sqrt(indexVariance) : 0;

            var sourceVariance = sourceSquaredAverage.Span[i] - MathHelper.Pow(sourceMa, 2);
            sourceDeviation[i] = sourceVariance >= 0 ? MathHelper.Sqrt(sourceVariance) : 0;

            var covariance = indexSourceAverage.Span[i] - (indexMa * sourceMa);
            var scale = indexDeviation[i] * sourceDeviation[i];
            correlation[i] = scale != 0 ? covariance / scale : 0;
        }
    }

    /// <summary>
    /// Computes Stochastic MACD Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStochasticMacdOscillatorFast(StockData data, ComputeContext context, int length = 45,
        int fastLength = 12, int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateStochasticMovingAverageConvergenceDivergenceOscillator stochastically rescales the fast
        // and slow averages of the chained series against the high/low range of the window and publishes ten
        // times their difference. The arm this replaced delegated to OscillatorCore.StochasticMacdOscillator,
        // a different derivation. signalLength only feeds the Signal and Histogram keys.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        using var highSeries = context.Rent(count);
        using var lowSeries = context.Rent(count);
        CustomRange(data, input, highSeries.WritableSpan, lowSeries.WritableSpan);
        var highs = highSeries.Span;
        var lows = lowSeries.Span;

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        StochasticSmooth(data, maType, fastLength, input, fastAverage.WritableSpan);
        StochasticSmooth(data, maType, slowLength, input, slowAverage.WritableSpan);
        var fastEma = fastAverage.Span;
        var slowEma = slowAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            output[i] = RoundedStochasticMacd.Of(fastEma[i], slowEma[i], highWindow.Max, lowWindow.Min);
        }

        if (outputKey is "Signal" or "Histogram")
        {
            using var signal = context.Rent(count);
            var finite = FiniteSignalInput.Create(buffer.ToArray(), out var finiteCount);
            StochasticSmooth(data, maType, 9, SpanCompat.AsReadOnlySpan(finite), signal.WritableSpan);
            for (var i = finiteCount; i < count; i++) signal.WritableSpan[i] = double.NaN;
            for (var i = 0; i < count; i++)
                output[i] = outputKey == "Signal" ? signal.Span[i] : output[i] - signal.Span[i];
        }
        return buffer;
    }

    /// <summary>
    /// Computes McClellan Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMcClellanOscillatorFast(StockData data, ComputeContext context, int fastLength = 19,
        int slowLength = 39, double mult = 1000, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateMcClellanOscillator counts advances and declines over the fast window, scales their net by
        // mult to build the ratio adjusted net advances, and publishes the convergence divergence of that
        // series - the fast moving average of it less the slow one - as "Mo". Its spec option Length is
        // marked obsolete because no parameter of the batch call corresponds to it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        using var netAdvances = context.Rent(count);
        var rana = netAdvances.WritableSpan;
        var advancesSumWindow = new RollingSum();
        var declinesSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            advancesSumWindow.Add(input[i] > prevValue ? 1d : 0d);
            declinesSumWindow.Add(input[i] < prevValue ? 1d : 0d);

            var advanceSum = advancesSumWindow.Sum(fastLength);
            var declineSum = declinesSumWindow.Sum(fastLength);
            output[i] = outputKey == "AdvSum" ? advanceSum : declineSum;
            rana[i] = advanceSum + declineSum != 0 ? mult * (advanceSum - declineSum) / (advanceSum + declineSum) : 0;
        }

        if (outputKey is "AdvSum" or "DecSum") return buffer;

        using var fast = context.Rent(count);
        using var slow = context.Rent(count);
        MovingAverage(data, maType, fastLength, netAdvances.Span, fast.WritableSpan);
        MovingAverage(data, maType, slowLength, netAdvances.Span, slow.WritableSpan);


        for (var i = 0; i < count; i++)
        {
            output[i] = fast.Span[i] - slow.Span[i];
        }

        if (outputKey is "Signal" or "Histogram")
        {
            using var smoothed = context.Rent(count);
            MovingAverage(data, maType, 9, buffer.Span, smoothed.WritableSpan);
            for (var i = 0; i < count; i++) output[i] = outputKey == "Signal" ? smoothed.Span[i] : output[i] - smoothed.Span[i];
        }

        return buffer;
    }

