    /// <summary>
    /// Computes Moving Average V3 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageV3Fast(StockData data, ComputeContext context, int length1 = 14, int length2 = 3,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var second = context.Rent(input.Count);
            MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(input), result.WritableSpan);
            MovingAverage(data, maType, length2, SpanCompat.AsReadOnlySpan(input), second.WritableSpan);
            for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = MovingAverageV3Window.Combine(result.Span[i], second.Span[i], length1, length2);
        }
        else
        {
            using var window = new MovingAverageV3Window(maType, length1, length2);
            for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true);
        }
        return result;
    }

    /// <summary>
    /// Computes One LC Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOneLCLeastSquaresMovingAverageFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var input = SpanCompat.AsReadOnlySpan(inputList); length = Math.Max(1, length);
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); var result = context.Rent(input.Length);
        try
        {
            if (external) MovingAverage(data, maType, length, input, result.WritableSpan);
            using var window = new OneLcWindow(maType, length, external);
            for (var i = 0; i < input.Length; i++) result.WritableSpan[i] = window.Next(input[i], true, external ? result.Span[i] : null).Value;
            return result;
        }
        catch { result.Dispose(); throw; }
    }

