    /// <summary>
    /// Computes Quadratic Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of a quadratic least squares fit's two published series an arm has been asked for: the fit
    /// evaluated at the current bar, or the same parabola extrapolated forward by the forecast length.
    /// </summary>
    internal enum QuadraticFitSeries
    {
        Value,
        Forecast
    }

    internal static ComputeBuffer ComputeQuadraticLeastSquaresMovingAverageFast(StockData data, ComputeContext context,
        int length = 50, int forecastLength = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        QuadraticFitSeries series = QuadraticFitSeries.Value)
    {
        // CalculateQuadraticLeastSquaresMovingAverage solves the normal equations for a parabola in the bar
        // index over a rolling window: the covariances come from moving averages of n, n^2, n^3, n*value and
        // n^2*value, and the two variances from the deviation of n and n^2 about their own window means, which
        // is what GetStandardDeviationList computes. The forecast series is the same parabola evaluated
        // forecastLength bars ahead.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            var result = context.Rent(count);
            using var fit = new Streaming.QuadraticLeastSquaresWindow(length);
            for (var i = 0; i < count; i++)
            {
                var point = fit.Next(input[i], forecastLength, true);
                result.WritableSpan[i] = series == QuadraticFitSeries.Forecast ? point.Forecast : point.Value;
            }
            return result;
        }

        using var indices = context.Rent(count);
        using var squares = context.Rent(count);
        using var cubes = context.Rent(count);
        using var squareValues = context.Rent(count);
        using var indexValues = context.Rent(count);
        var n = indices.WritableSpan;
        var n2 = squares.WritableSpan;
        var nn2 = cubes.WritableSpan;
        var n2v = squareValues.WritableSpan;
        var nv = indexValues.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double index = i;
            n[i] = index;
            n2[i] = MathHelper.Pow(index, 2);
            nn2[i] = index * n2[i];
            n2v[i] = n2[i] * input[i];
            nv[i] = index * input[i];
        }

        using var average = context.Rent(count);
        using var indexAverage = context.Rent(count);
        using var squareAverage = context.Rent(count);
        using var cubeAverage = context.Rent(count);
        using var squareValueAverage = context.Rent(count);
        using var indexValueAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        MovingAverage(data, maType, length, indices.Span, indexAverage.WritableSpan);
        MovingAverage(data, maType, length, squares.Span, squareAverage.WritableSpan);
        MovingAverage(data, maType, length, squareValues.Span, squareValueAverage.WritableSpan);
        MovingAverage(data, maType, length, indexValues.Span, indexValueAverage.WritableSpan);
        MovingAverage(data, maType, length, cubes.Span, cubeAverage.WritableSpan);
        var sma = average.Span;
        var nSma = indexAverage.Span;
        var n2Sma = squareAverage.Span;
        var nn2Sma = cubeAverage.Span;
        var n2vSma = squareValueAverage.Span;
        var nvSma = indexValueAverage.Span;

        using var indexDeviation = context.Rent(count);
        using var squareDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(indices.Span, indexDeviation.WritableSpan, length);
        VolatilityCore.StandardDeviation(squares.Span, squareDeviation.WritableSpan, length);
        var nDev = indexDeviation.Span;
        var n2Dev = squareDeviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var nVariance = nDev[i] * nDev[i];
            var n2Variance = n2Dev[i] * n2Dev[i];
            var nn2Cov = nn2Sma[i] - (nSma[i] * n2Sma[i]);
            var n2vCov = n2vSma[i] - (n2Sma[i] * sma[i]);
            var nvCov = nvSma[i] - (nSma[i] * sma[i]);

            var norm = (n2Variance * nVariance) - MathHelper.Pow(nn2Cov, 2);
            var a = norm != 0 ? ((n2vCov * nVariance) - (nvCov * nn2Cov)) / norm : 0;
            var b = norm != 0 ? ((nvCov * n2Variance) - (n2vCov * nn2Cov)) / norm : 0;
            var c = sma[i] - (a * n2Sma[i]) - (b * nSma[i]);

            output[i] = series == QuadraticFitSeries.Forecast
                ? (a * MathHelper.Pow(i + forecastLength, 2)) + (b * (i + forecastLength)) + c
                : (a * n2[i]) + (b * i) + c;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Quadratic Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeQuadraticMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(selected.Count);
        MovingAverageCore.QuadraticMovingAverage(SpanCompat.AsReadOnlySpan(selected), buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Quadratic Regression using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeQuadraticRegressionFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        length = Math.Max(1, length); var count = input.Count;
        using var xm = context.Rent(count); using var qm = context.Rent(count); using var ym = context.Rent(count);
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        if (external)
        {
            using var indices = context.Rent(count); using var squares = context.Rent(count);
            for (var i = 0; i < count; i++) { indices.WritableSpan[i] = i; squares.WritableSpan[i] = (double)i * i; }
            MovingAverage(data, maType, length, indices.Span, xm.WritableSpan); MovingAverage(data, maType, length, squares.Span, qm.WritableSpan);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), ym.WritableSpan);
        }
        var result = context.Rent(count); using var window = new QuadraticProjectionWindow(maType, length, Math.Max(1, count));
        for (var i = 0; i < count; i++) result.WritableSpan[i] = window.Next(input[i], true, external ? xm.Span[i] : null, external ? qm.Span[i] : null, external ? ym.Span[i] : null);
        return result;
    }

    /// <summary>
    /// Fits the quadratic of CalculateQuadraticRegression to an arbitrary series, so that an indicator built
    /// on that fit can reach it without publishing it first.
    /// </summary>
    /// <remarks>
    /// The regression is solved in coordinates relative to the current bar over the trailing
    /// window, but the covariances divide by the requested length rather than by how many bars the window
    /// actually holds, and the three coefficients are centred on moving averages of the same length. Both are
    /// reproduced here exactly: they are what the published series is.
    /// </remarks>
    private static void QuadraticRegression(StockData data, ComputeContext context, ReadOnlySpan<double> input,
        int length, MovingAvgType maType, Span<double> output)
    {
        var count = input.Length;
        length = Math.Max(length, 1);

        using var firstPower = context.Rent(count);
        using var secondPower = context.Rent(count);
        var x1s = firstPower.WritableSpan;
        var x2s = secondPower.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double x1 = i;
            x1s[i] = x1;
            x2s[i] = MathHelper.Pow(x1, 2);
        }

        using var firstPowerAverage = context.Rent(count);
        using var secondPowerAverage = context.Rent(count);
        using var seriesAverage = context.Rent(count);
        MovingAverage(data, maType, length, firstPower.Span, firstPowerAverage.WritableSpan);
        MovingAverage(data, maType, length, secondPower.Span, secondPowerAverage.WritableSpan);
        MovingAverage(data, maType, length, input, seriesAverage.WritableSpan);
        var max1 = firstPowerAverage.Span;
        var max2 = secondPowerAverage.Span;
        var may = seriesAverage.Span;

        using var window = new Streaming.QuadraticRegressionWindow(length);
        for (var i = 0; i < count; i++)
            output[i] = Streaming.QuadraticRegressionWindow.Evaluate(window.Next(input[i], true), i, max1[i], max2[i], may[i]);
    }

    /// <summary>
    /// Computes R2 Adaptive Regression using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeR2AdaptiveRegressionFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateR2AdaptiveRegression blends three estimates of the series by how well each explains it: the
        // linear regression line, a line fitted to the indicator's OWN previous output, and that previous
        // output itself, weighted by the squared correlations of the first two and whatever is left over. The
        // second line's slope is the price window's deviation times the correlation, over the deviation of the
        // previous output - both halves of one ratio measured the same way, which is what issue #223 settled.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var linear = context.Rent(count);
        var linreg = linear.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                linreg[i] = regression.Next(input[i], isFinal: true).Last;
            }
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var x2Correlation = new RollingCorrelation();
        var y1Correlation = new RollingCorrelation();
        var y2Correlation = new RollingCorrelation();
        var x2Total = new RollingSum();
        var x2PowTotal = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var y1 = linear.Span[i];
            y1Correlation.Add(y1, currentValue);

            var x2 = i >= 1 ? output[i - 1] : currentValue;
            x2Total.Add(x2);
            x2Correlation.Add(x2, currentValue);

            var r2x2 = x2Correlation.R(length);
            r2x2 = MathHelper.IsValueNullOrInfinity(r2x2) ? 0 : r2x2;
            var x2Average = x2Total.Average(length);
            x2PowTotal.Add(MathHelper.Pow(x2 - x2Average, 2));

            var x2PowAverage = x2PowTotal.Average(length);
            var x2StdDev = x2PowAverage >= 0 ? MathHelper.Sqrt(x2PowAverage) : 0;
            var a = x2StdDev != 0 ? stdDev[i] * r2x2 / x2StdDev : 0;
            var b = sma[i] - (a * x2Average);

            var y2 = (a * x2) + b;
            y2Correlation.Add(y2, currentValue);

            var ry1 = Math.Pow(y1Correlation.R(length), 2);
            ry1 = MathHelper.IsValueNullOrInfinity(ry1) ? 0 : ry1;
            var ry2 = Math.Pow(y2Correlation.R(length), 2);
            ry2 = MathHelper.IsValueNullOrInfinity(ry2) ? 0 : ry2;

            output[i] = (ry1 * y1) + (ry2 * y2) + ((1 - (ry1 + ry2)) * x2);
        }

        return buffer;
    }

