    /// <summary>
    /// Computes Adaptive Autonomous Recursive Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAdaptiveAutonomousRecursiveMovingAverageFast(StockData data, ComputeContext context,
        int length = 14, double gamma = 3, bool deviation = false)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        // The routine fills both series in one pass and the band width was being thrown away, which is why
        // the D key answered with the average.
        var average = context.Rent(count);
        var deviations = context.Rent(count);
        AdaptiveAutonomousRecursiveMovingAverage(context, SpanCompat.AsReadOnlySpan(inputList), length, gamma,
            average.WritableSpan, deviations.WritableSpan);

        if (deviation)
        {
            average.Dispose();
            return deviations;
        }

        deviations.Dispose();
        return average;
    }

    /// <summary>
    /// Writes the adaptive autonomous recursive moving average into <paramref name="average"/> and the band
    /// width it was built from into <paramref name="deviation"/>, which are the Aarma and D series
    /// CalculateAdaptiveAutonomousRecursiveMovingAverage publishes.
    /// </summary>
    /// <remarks>
    /// The average bands the series by the running mean of its own distance from the average, scaled by
    /// gamma, and then smooths the banded value twice - each pass weighted by Kaufman's efficiency ratio, so
    /// the average follows a trending series closely and a noisy one barely at all. The trailing stop built
    /// on it needs both series, so the two are filled in one pass rather than measured twice.
    /// </remarks>
    private static void AdaptiveAutonomousRecursiveMovingAverage(ComputeContext context, ReadOnlySpan<double> input,
        int length, double gamma, Span<double> average, Span<double> deviation)
    {
        using var window = new AdaptiveAutonomousWindow(length, gamma);
        for (var i = 0; i < input.Length; i++) { var value = window.Next(input[i], true); average[i] = value.Average; deviation[i] = value.Deviation; }
    }

    /// <summary>
    /// Writes Kaufman's efficiency ratio of an arbitrary series, so that an indicator weighted by it can
    /// reach it without publishing the adaptive moving average that owns it.
    /// </summary>
    /// <remarks>
    /// The ratio is how much of the window's total bar-to-bar travel the series actually covered over it:
    /// one for a straight line, near zero for a market that ends where it started. This is the "Er" output
    /// of CalculateKaufmanAdaptiveMovingAverage, which neither the fast nor the slow length reaches.
    /// </remarks>
    private static void EfficiencyRatio(ReadOnlySpan<double> input, int length, Span<double> output)
    {
        length = Math.Max(length, 1);
        var volatilitySumWindow = new RollingSum();
        for (var i = 0; i < input.Length; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var priorValue = i >= length ? input[i - length] : 0;

            volatilitySumWindow.Add(Math.Abs(CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue)));
            var volatilitySum = volatilitySumWindow.Sum(length);
            var momentum = Math.Abs(CalculationsHelper.MinPastValues(i, length, input[i] - priorValue));

            output[i] = volatilitySum != 0 ? momentum / volatilitySum : 0;
        }
    }

