    internal static ComputeBuffer ComputePolarizedFractalEfficiencyFast(StockData data, ComputeContext context, int length = 9,
        int smoothLength = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var values = PolarizedEfficiencyWindow.Calculate(data, input, maType, length, smoothLength, true);
        var buffer = context.Rent(values.Length); values.AsSpan().CopyTo(buffer.WritableSpan); return buffer;
    }

    /// <summary>
    /// Computes Schaff Trend Cycle using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSchaffTrendCycleFast(StockData data, ComputeContext context, int cycleLength = 10,
        int fastLength = 23, int slowLength = 50, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var window = new SchaffFirstPassWindow(maType, fastLength, slowLength, cycleLength, external); using ComputeBuffer? fast = external ? context.Rent(input.Count) : null; using ComputeBuffer? slow = external ? context.Rent(input.Count) : null;
        if (external) { MovingAverage(data, maType, Math.Max(1, fastLength), SpanCompat.AsReadOnlySpan(input), fast!.Value.WritableSpan); MovingAverage(data, maType, Math.Max(1, slowLength), SpanCompat.AsReadOnlySpan(input), slow!.Value.WritableSpan); }
        var result = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true, external ? fast!.Value.Span[i] : null, external ? slow!.Value.Span[i] : null).Value; return result; }
        catch { result.Dispose(); throw; }
    }

    /// <summary>
    /// Computes Smoothed Rate of Change using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSmoothedRateOfChangeFast(StockData data, ComputeContext context, int length = 21,
        int smoothingLength = 13, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateSmoothedRateOfChange smooths the chained series first and takes the rate of change of that
        // average, not of price; where the older average is still zero the rate is reported as a flat hundred,
        // which is why the batch opens at 100 and the two core-routine arms this replaced opened at zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var window = new SmoothedReturnWindow(maType, length, smoothingLength, count);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = window.Next(inputList[i], true);
            return stable;
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, smoothingLength, SpanCompat.AsReadOnlySpan(inputList), smoothed.WritableSpan);
        var ma = smoothed.Span;

        var buffer = context.Rent(count);
        var sroc = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousMa = i >= length ? ma[i - length] : 0;
            sroc[i] = previousMa != 0 ? RoundedPercentageChange.Of(ma[i], previousMa) : 100;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Floor Pivot Point using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which level a pivot routine publishes. The three-support types leave the fourth unused.
    /// </summary>
    internal enum PivotSeries
    {
        /// <summary>The pivot itself.</summary>
        Pivot,

        /// <summary>Support levels one to four.</summary>
        Support1, Support2, Support3, Support4,

        /// <summary>Resistance levels one to four.</summary>
        Resistance1, Resistance2, Resistance3, Resistance4,

        /// <summary>Midpoints one to six.</summary>
        Mid1, Mid2, Mid3, Mid4, Mid5, Mid6
    }

    /// <summary>
    /// Projects one level per period onto the bars of its own period.
    /// </summary>
    private static ComputeBuffer PivotLevels(StockData data, ComputeContext context, InputLength inputLength,
        Func<int, List<double>, List<double>, List<double>, double> level)
    {
        // Every pivot type shares this: one level per PERIOD, derived from the PRECEDING period, projected
        // back onto that period's bars. See ComputeDemarkPivotPointFast for what passing raw per-bar spans
        // to TrendCore did instead - it moved the level on every bar and matched the batch on no series at
        // all, the primary included.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data, inputLength);

        var periods = inputList.Count;
        var levels = new List<double>(periods);
        for (var i = 0; i < periods; i++)
        {
            levels.Add(level(i, inputList, highList, lowList));
        }

        var groupIndexes = CalculationsHelper.GetInputLengthGroupIndexes(data, inputLength);
        var expanded = CalculationsHelper.ExpandPeriodValuesToBars(levels, groupIndexes);

        var buffer = context.Rent(data.Count);
        var output = buffer.WritableSpan;
        output.Clear();
        for (var i = 0; i < output.Length && i < expanded.Count; i++)
        {
            output[i] = expanded[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeFloorPivotPointFast(StockData data, ComputeContext context,
        InputLength inputLength = InputLength.Day, PivotSeries series = PivotSeries.Pivot)
    {
        var (close,high,low,_,_)=PivotPeriodInputs.Read(data,inputLength);var groups=CalculationsHelper.GetInputLengthGroupIndexes(data,inputLength);
        var slot=series switch { PivotSeries.Support1=>1,PivotSeries.Support2=>2,PivotSeries.Support3=>3,
            PivotSeries.Resistance1=>4,PivotSeries.Resistance2=>5,PivotSeries.Resistance3=>6,
            PivotSeries.Mid1=>7,PivotSeries.Mid2=>8,PivotSeries.Mid3=>9,PivotSeries.Mid4=>10,PivotSeries.Mid5=>11,PivotSeries.Mid6=>12,_=>0 };
        var levels=new double[close.Count];for(var i=1;i<levels.Length;i++)levels[i]=FloorPivotMath.Levels(high[i-1],low[i-1],close[i-1])[slot];
        var buffer=context.Rent(data.Count);for(var i=0;i<data.Count;i++)buffer.WritableSpan[i]=levels[groups[i]];return buffer;
    }

