    /// <summary>
    /// Computes Ehlers Moving Average Difference Indicator.
    /// MAD = 100 * (fastMA - slowMA) / slowMA
    /// </summary>
    internal static ComputeBuffer ComputeEhlersMovingAverageDifferenceFast(StockData data, ComputeContext context, int fastLength = 8, int slowLength = 23, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        fastLength=Math.Max(1,fastLength);slowLength=Math.Max(1,slowLength);var input=data.ChainedValues.Count>0?data.ChainedValues:data.InputValues;var output=context.Rent(input.Count);
        if(ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var fast=context.Rent(input.Count);using var slow=context.Rent(input.Count);
            MovingAverage(data,maType,fastLength,SpanCompat.AsReadOnlySpan(input),fast.WritableSpan);MovingAverage(data,maType,slowLength,SpanCompat.AsReadOnlySpan(input),slow.WritableSpan);
            for(var i=0;i<input.Count;i++)output.WritableSpan[i]=AverageGapWindow.Gap(fast.Span[i],slow.Span[i]);
        }
        else{using var window=new AverageGapWindow(maType,fastLength,slowLength,input.Count);for(var i=0;i<input.Count;i++)output.WritableSpan[i]=window.Next(input[i],true);}
        return output;
    }

    /// <summary>
    /// Computes Elder Market Thermometer with signal line.
    /// </summary>
    internal static ComputeBuffer ComputeElderMarketThermometerFast(StockData data, ComputeContext context, int length = 22, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, bool signal = false)
    {
        var custom = ComponentAverage.HasOverrides;
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        if (custom)
        {
            using var priceMean = context.Rent(data.Count);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), priceMean.WritableSpan);
        }
        using var raw = context.Rent(data.Count);
        var output = context.Rent(data.Count);
        using var thermometer = new ElderThermometerWindow(maType, length);
        for (var i = 0; i < data.Count; i++)
        {
            var value = thermometer.Next(data.HighPrices[i], data.LowPrices[i], true);
            raw.WritableSpan[i] = value.Value;
            output.WritableSpan[i] = signal ? value.Signal : value.Value;
        }
        if (custom)
        {
            using var smoothed = context.Rent(data.Count);
            MovingAverage(data, maType, length, raw.Span, smoothed.WritableSpan);
            if (signal) smoothed.Span.CopyTo(output.WritableSpan);
        }
        return output;
    }

    /// <summary>
    /// Computes DEMA 2 Lines indicator (fast DEMA line).
    /// Returns the fast DEMA line for crossover signals.
    /// </summary>
    internal static ComputeBuffer ComputeDema2LinesFast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 40, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateDema2Lines publishes its fast line as the chained series smoothed twice over the fast
        // length - not the usual double exponential average, which leans the first pass against the second.
        // The switch this replaced computed that other average and fell back to it for most types anyway.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var firstPass = context.Rent(count);
        MovingAverage(data, maType, fastLength, SpanCompat.AsReadOnlySpan(inputList), firstPass.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, fastLength, firstPass.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Gain Loss Moving Average with signal line.
    /// </summary>
    internal static ComputeBuffer ComputeGainLossMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, int signalLength = 7, bool signal = false)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            var changes = input.Select((price, i) => GainLossAverageWindow.Change(price, i == 0 ? 0 : input[i - 1], i > 0)).ToArray();
            using var first = context.Rent(input.Count);
            MovingAverage(data, maType, length, changes, first.WritableSpan);
            if (signal) MovingAverage(data, maType, signalLength, first.Span, result.WritableSpan);
            else first.Span.CopyTo(result.WritableSpan);
        }
        else
        {
            using var window = new GainLossAverageWindow(maType, length, signalLength, Math.Max(1, input.Count));
            for (var i = 0; i < input.Count; i++) { var value = window.Next(input[i], true); result.WritableSpan[i] = signal ? value.Signal : value.Value; }
        }
        return result;
    }

    /// <summary>
    /// Computes one EMA Wave residual output.
    /// </summary>
    internal static ComputeBuffer ComputeEmaWaveFast(StockData data, ComputeContext context, int length1, int length2, int length3, int smoothLength, string? outputKey)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new ResidualAverageWindow(MovingAvgType.ExponentialMovingAverage, outputKey == "Wb" ? length2 : outputKey == "Wc" ? length3 : length1, MovingAvgType.SimpleMovingAverage, smoothLength);
        var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true).Value;
        return result;
    }

    /// <summary>Computes Ergodic Mean Deviation and its signal without narrowing hidden residuals.</summary>
    internal static ComputeBuffer ComputeErgodicMeanDeviationIndicatorFast(StockData data, ComputeContext context, int length1 = 32,
        int length2 = 5, int length3 = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int signalLength = 5, string? outputKey = null)
    {
        // CalculateErgodicMeanDeviationIndicator publishes "Emdi": the deviation of the chained series from its
        // own moving average, smoothed twice more, followed by a separate signal stage.
        // The exact route retains wide residuals through every stage before publishing an output.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            using var window = new ResidualAverageWindow(maType, length1, maType, length2, length3, signalLength);
            var result = context.Rent(count);
            for (var i = 0; i < count; i++) { var value = window.Next(input[i], true); result.WritableSpan[i] = outputKey == "Signal" ? value.Signal : value.Value; }
            return result;
        }
        using var average = context.Rent(count);
        MovingAverage(data, maType, length1, input, average.WritableSpan);
        var ma = average.Span;

        using var deviation = context.Rent(count);
        var dev = deviation.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            dev[i] = input[i] - ma[i];
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length2, deviation.Span, smoothed.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length3, smoothed.Span, buffer.WritableSpan);
        var signal = context.Rent(count);
        MovingAverage(data, maType, signalLength, buffer.Span, signal.WritableSpan);
        if (outputKey == "Signal") { buffer.Dispose(); return signal; }
        signal.Dispose(); return buffer;
    }

    /// <summary>
    /// Computes Mayer Multiple using zero-allocation fast path.
    /// MayerMultiple = price / MA
    /// </summary>
    internal static ComputeBuffer ComputeMayerMultipleFast(StockData data, ComputeContext context, int length = 200, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var count = data.Count;
        var pool = ArrayPool<double>.Shared;
        var maArray = pool.Rent(count);

        try
        {
            var maSpan = maArray.AsSpan(0, count);

            // Calculate MA of close prices
            MovingAverage(data, maType, length, close, maSpan);

            // Calculate Mayer Multiple = price / MA
            ReadOnlySpan<double> maReadOnly = maSpan;
            var buffer = context.Rent(count);
            VolatilityCore.MayerMultiple(close, maReadOnly, buffer.WritableSpan);

            return buffer;
        }
        finally
        {
            pool.Return(maArray);
        }
    }

    /// <summary>
    /// Computes Gopalakrishnan Range Index using zero-allocation fast path.
    /// GAPO = log(highestHigh - lowestLow) / log(length), then smoothed with MA.
    /// </summary>
    internal static ComputeBuffer ComputeGopalakrishnanRangeIndexFast(StockData data, ComputeContext context, int length = 5, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, string? outputKey = null)
    {
        length = Math.Max(2, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        if (ComponentAverage.HasOverrides) { using var prices = context.Rent(input.Count); MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), prices.WritableSpan); }
        var window = new GopalakrishnanWindow(length); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(data.HighPrices[i], data.LowPrices[i], true);
        using var signal = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType)) MovingAverage(data, maType, length, result.Span, signal.WritableSpan);
        else { using var average = new RocBankAverage(maType, length, input.Count); for (var i = 0; i < input.Count; i++) signal.WritableSpan[i] = average.Next(new RocBankValue(result.Span[i]), true).Publish(); }
        if (outputKey == "Signal") signal.Span.CopyTo(result.WritableSpan);
        return result;
    }

    /// <summary>
    /// Computes High Low Moving Average using zero-allocation fast path.
    /// Returns middle band = (MA(highest high) + MA(lowest low)) / 2.
    /// </summary>
    internal static ComputeBuffer ComputeHighLowMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage, string? outputKey = null)
    {
        // CalculateHighLowMovingAverage smooths the highest high and the lowest low of the window and takes
        // their midpoint. The switch this replaced fell back to a weighted average for every type but three.
        if (!ComponentAverage.HasOverrides && StrengthWindow.Supports(maType))
        {
            var result = context.Rent(data.Count); using var window = new HighLowAverageWindow(maType, length);
            for (var i = 0; i < data.Count; i++)
            {
                var value = window.Next(data.HighPrices[i], data.LowPrices[i], true);
                result.WritableSpan[i] = outputKey == "UpperBand" ? value.Upper : outputKey == "LowerBand" ? value.Lower : value.Middle;
            }
            return result;
        }
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var highest = context.Rent(count);
        using var lowest = context.Rent(count);
        var hh = highest.WritableSpan;
        var ll = lowest.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            hh[i] = highWindow.Max;
            ll[i] = lowWindow.Min;
        }

        using var upperBand = context.Rent(count);
        MovingAverage(data, maType, length, highest.Span, upperBand.WritableSpan);
        using var lowerBand = context.Rent(count);
        MovingAverage(data, maType, length, lowest.Span, lowerBand.WritableSpan);

        var upper = upperBand.Span;
        var lower = lowerBand.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = outputKey == "UpperBand" ? upper[i] : outputKey == "LowerBand" ? lower[i] : HighLowAverageWindow.Midpoint(upper[i], lower[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stiffness Indicator using zero-allocation fast path.
    /// Measures how many closes are above MA - 0.2*StdDev over a period.
    /// </summary>
    internal static ComputeBuffer ComputeStiffnessIndicatorFast(StockData data, ComputeContext context, int length1 = 100,
        int length2 = 60, int smoothingLength = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        length1 = Math.Max(1, length1); smoothingLength = Math.Max(1, smoothingLength);
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; using var window = new StiffnessWindow(maType, length1, length2, smoothingLength); var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var average = context.Rent(input.Count); MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(input), average.WritableSpan);
            using var votes = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) votes.WritableSpan[i] = window.Vote(input[i], true, average.Span[i]);
            MovingAverage(data, MovingAvgType.ExponentialMovingAverage, smoothingLength, votes.Span, result.WritableSpan);
        }
        else for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true);
        return result;
    }

    /// <summary>
    /// Computes Market Meanness Index using zero-allocation fast path.
    /// Counts reversals above/below median in a lookback period.
    /// </summary>
    internal static ComputeBuffer ComputeMarketMeannessIndexFast(StockData data, ComputeContext context, int length = 100, MovingAvgType maType = MovingAvgType.EhlersNoiseEliminationTechnology, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var output = context.Rent(input.Count); using var window = new MeannessWindow(maType, length);
        var custom = ComponentAverage.HasOverrides;
        using var line = context.Rent(input.Count); using var smoothed = context.Rent(input.Count);
        if (custom)
        {
            using var priceAverage = context.Rent(input.Count);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), priceAverage.WritableSpan);
            for (var i = 0; i < input.Count; i++) line.WritableSpan[i] = window.Next(input[i], true).Line;
            MovingAverage(data, maType, length, line.Span, smoothed.WritableSpan);
            for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = outputKey == "MmiSmoothed" ? smoothed.Span[i] : line.Span[i];
        }
        else for (var i = 0; i < input.Count; i++)
        {
            var value = window.Next(input[i], true); output.WritableSpan[i] = outputKey == "MmiSmoothed" ? value.Smoothed : value.Line;
        }
        return output;
    }

    /// <summary>
    /// Computes Sharpe Ratio using zero-allocation fast path.
    /// SharpeRatio = (returns - benchmark) / standardDeviation
    /// </summary>
    internal static ComputeBuffer ComputeSharpeRatioFast(StockData data, ComputeContext context, int length = 30, double bmk = 0.02,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        length = Math.Max(1, length);
        using var window = new ReturnScoreWindow(maType, length, bmk, false);
        var custom = ComponentAverage.HasOverrides;
        using var means = context.Rent(input.Count);
        if (custom)
        {
            using var returns = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) returns.WritableSpan[i] = window.ReturnValue(input[i], i >= length ? input[i - length] : 0).Publish();
            MovingAverage(data, maType, length, returns.Span, means.WritableSpan);
        }
        var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = window.Next(input[i], true, custom ? means.Span[i] : null);
        return output;
    }

    /// <summary>
    /// Computes Sortino Ratio using zero-allocation fast path.
    /// SortinoRatio = (returns - benchmark) / downsideDeviation
    /// </summary>
    internal static ComputeBuffer ComputeSortinoRatioFast(StockData data, ComputeContext context, int length = 30, double bmk = 0.02,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        length = Math.Max(1, length);
        using var window = new SortinoWindow(maType, length, bmk);
        var custom = ComponentAverage.HasOverrides;
        using var means = context.Rent(input.Count);
        using var downsideMeans = context.Rent(input.Count);
        if (custom)
        {
            using var returns = context.Rent(input.Count); using var squares = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++)
            {
                var value = window.ReturnValue(input[i], i >= length ? input[i - length] : 0);
                returns.WritableSpan[i] = value.Publish(); squares.WritableSpan[i] = SortinoWindow.PublishSquare(SortinoWindow.DownsideSquare(value));
            }
            MovingAverage(data, maType, length, returns.Span, means.WritableSpan);
            MovingAverage(data, maType, length, squares.Span, downsideMeans.WritableSpan);
        }
        var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = window.Next(input[i], true, custom ? means.Span[i] : null, custom ? downsideMeans.Span[i] : null);
        return output;
    }

    /// <summary>
    /// Computes Martin Ratio using zero-allocation fast path.
    /// MartinRatio = returns / ulcerIndex
    /// </summary>
    internal static ComputeBuffer ComputeMartinRatioFast(StockData data, ComputeContext context, int length = 30,
        double bmk = 0.02, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        length = Math.Max(1, length);
        using var window = new MartinWindow(maType, length, bmk);
        var custom = ComponentAverage.HasOverrides;
        using var means = context.Rent(input.Count);
        if (custom)
        {
            using var returns = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) returns.WritableSpan[i] = window.ReturnValue(input[i], i >= length ? input[i - length] : 0).Publish();
            MovingAverage(data, maType, length, returns.Span, means.WritableSpan);
        }
        var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = window.Next(input[i], true, custom ? means.Span[i] : null);
        return output;
    }

    /// <summary>
    /// Computes Information Ratio using zero-allocation fast path.
    /// InformationRatio = excessReturns / trackingError
    /// </summary>
    internal static ComputeBuffer ComputeInformationRatioFast(StockData data, ComputeContext context, int length = 30, double bmk = 0.05,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        length = Math.Max(1, length);
        using var window = new ReturnScoreWindow(maType, length, bmk, true);
        var custom = ComponentAverage.HasOverrides;
        using var means = context.Rent(input.Count);
        if (custom)
        {
            using var returns = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) returns.WritableSpan[i] = window.ReturnValue(input[i], i >= length ? input[i - length] : 0).Publish();
            MovingAverage(data, maType, length, returns.Span, means.WritableSpan);
        }
        var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) output.WritableSpan[i] = window.Next(input[i], true, custom ? means.Span[i] : null);
        return output;
    }

    /// <summary>
    /// Computes Optimized Trend Tracker using zero-allocation fast path.
    /// OTT is a trend-following indicator based on MA with percentage bands.
    /// </summary>
    internal static ComputeBuffer ComputeOptimizedTrendTrackerFast(StockData data, ComputeContext context, int length = 2,
        double percent = 1.4, MovingAvgType maType = MovingAvgType.VariableIndexDynamicAverage)
    {
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !OptimizedTrendWindow.Supports(maType);
        using var window = new OptimizedTrendWindow(maType, length, percent, external); using ComputeBuffer? mean = external ? context.Rent(input.Count) : null;
        if (external) MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(input), mean!.Value.WritableSpan);
        var result = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true, external ? mean!.Value.Span[i] : null).Value; return result; }
        catch { result.Dispose(); throw; }
    }

    /// <summary>
    /// Computes Random Walk Index using zero-allocation fast path.
    /// RWI measures trend strength using ATR-normalized price movement.
    /// </summary>
    internal static ComputeBuffer ComputeRandomWalkIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, string? outputKey = null)
    {
        var result = RandomWalkWindow.Calculate(data, maType, length, true);
        var values = outputKey == "RwiLow" ? result.Low : result.High;
        var buffer = context.Rent(values.Length); values.AsSpan().CopyTo(buffer.WritableSpan); return buffer;
    }

    /// <summary>
    /// Computes Price Channel using zero-allocation fast path.
    /// Price Channel = MA +/- percentage bands.
    /// </summary>
    internal static ComputeBuffer ComputePriceChannelFast(StockData data, ComputeContext context, int length = 21, double pct = 0.06,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculatePriceChannel steps its outer channels a fixed percentage either side of the moving average
        // of the chained series, which makes the middle channel that average exactly. One arm now serves all
        // three published channels, and the switch it replaced fell back to an exponential average of the close
        // for every moving average type but two.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        StochasticSmooth(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), output);

        if (band == ChannelBand.Middle)
        {
            return buffer;
        }

        var direction = band == ChannelBand.Upper ? 1 : -1;
        for (var i = 0; i < count; i++)
        {
            output[i] = RoundedPercentageBand.Of(output[i], pct, direction);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Moving Average Bands using zero-allocation fast path.
    /// Returns middle band (average of fast and slow MAs).
    /// </summary>
    /// <summary>
    /// Selects which series of the moving average bands a caller wants.
    /// </summary>
    internal enum MovingAverageBandSeries
    {
        /// <summary>The slow average plus the deviation.</summary>
        UpperBand,

        /// <summary>The slow average, which the bands are centred on.</summary>
        MiddleBand,

        /// <summary>The slow average less the deviation.</summary>
        LowerBand,

        /// <summary>The fast average, published beside the bands.</summary>
        FastMa,

        /// <summary>The width of the bands against the middle, as a percentage.</summary>
        BandWidth
    }

    /// <summary>
    /// Computes the moving average bands as CalculateMovingAverageBands publishes them.
    /// </summary>
    /// <remarks>
    /// The bands are the SLOW average plus and minus a deviation, that deviation being the root mean square
    /// gap between the two averages over the fast length, scaled by the multiplier. The routine this replaced
    /// returned the mean of the two averages, which is a different quantity altogether - it matched only over
    /// the opening bars, while the two averages were still close enough for the deviation to be negligible.
    /// It also read the close rather than the chained series and understood two moving average types.
    ///
    /// CalculateMovingAverageBandWidth chains off this one and publishes the span of the bands against the
    /// middle as a percentage, so it is served here too rather than recomputing the pair.
    /// </remarks>
    private static ComputeBuffer MovingAverageBandLevels(StockData data, ComputeContext context, int fastLength,
        int slowLength, double mult, MovingAvgType maType, MovingAverageBandSeries series)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var window = new MovingAverageBandWindow(maType, fastLength, slowLength, mult, external);
        using var fastAverage = context.Rent(external ? input.Count : 0); using var slowAverage = context.Rent(external ? input.Count : 0);
        if (external)
        {
            MovingAverage(data, maType, fastLength, SpanCompat.AsReadOnlySpan(input), fastAverage.WritableSpan);
            MovingAverage(data, maType, slowLength, SpanCompat.AsReadOnlySpan(input), slowAverage.WritableSpan);
        }
        var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++)
        {
            var value = window.Next(input[i], true, external ? fastAverage.Span[i] : null, external ? slowAverage.Span[i] : null);
            result.WritableSpan[i] = series switch { MovingAverageBandSeries.MiddleBand => value.Middle, MovingAverageBandSeries.LowerBand => value.Lower,
                MovingAverageBandSeries.FastMa => value.Fast, MovingAverageBandSeries.BandWidth => value.Width, _ => value.Upper };
        }
        return result;
    }

    /// <summary>
    /// Computes Moving Average Band Width using zero-allocation fast path.
    /// Returns the width between fast and slow MA bands.
    /// </summary>
    /// <summary>
    /// Computes Moving Average Channel using zero-allocation fast path.
    /// Returns the MA of high-low range.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageChannelFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        if (!ComponentAverage.HasOverrides && StrengthWindow.Supports(maType))
        {
            var result = context.Rent(data.Count); using var window = new PriceAverageChannelWindow(maType, length);
            for (var i = 0; i < data.Count; i++)
            {
                var value = window.Next(data.HighPrices[i], data.LowPrices[i], true);
                result.WritableSpan[i] = band == ChannelBand.Upper ? value.Upper : band == ChannelBand.Lower ? value.Lower : value.Middle;
            }
            return result;
        }
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        var pool = ArrayPool<double>.Shared;
        var highMaArray = pool.Rent(count);
        var lowMaArray = pool.Rent(count);

        try
        {
            var highMaSpan = highMaArray.AsSpan(0, count);
            var lowMaSpan = lowMaArray.AsSpan(0, count);

            // Calculate MA of high and low
            MovingAverage(data, maType, length, high, highMaSpan);
            MovingAverage(data, maType, length, low, lowMaSpan);

            // Return middle (average of high and low MAs)
            var buffer = context.Rent(count);
            for (var i = 0; i < count; i++)
            {
                buffer.WritableSpan[i] = band == ChannelBand.Upper ? highMaSpan[i]
                    : band == ChannelBand.Lower ? lowMaSpan[i] : HighLowAverageWindow.Midpoint(highMaSpan[i], lowMaSpan[i]);
            }

            return buffer;
        }
        finally
        {
            pool.Return(highMaArray);
            pool.Return(lowMaArray);
        }
    }

    /// <summary>
    /// Computes the selected Keltner band using its separate center and true-range periods.
    /// </summary>
    private static ComputeBuffer ComputeKeltnerChannelBand(StockData data, ComputeContext context,
        int centerLength, int rangeLength, double multiplier, MovingAvgType kind, string? key)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count;
        using var atr = context.Rent(count); using var center = context.Rent(count);
        var useStages = ComponentAverage.HasOverrides || !StrengthWindow.Supports(kind);
        if (useStages)
        {
            var ranges = CalculationsHelper.GetTrueRangeList(data);
            MovingAverage(data, MovingAvgType.WildersSmoothingMethod, Math.Max(1, rangeLength), SpanCompat.AsReadOnlySpan(ranges), atr.WritableSpan);
            MovingAverage(data, kind, Math.Max(1, centerLength), SpanCompat.AsReadOnlySpan(input), center.WritableSpan);
        }
        var result = context.Rent(count); using var window = useStages ? null : new KeltnerWindow(kind, centerLength, rangeLength, capacityHint: Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var stages = useStages ? (new RocBankValue(center.Span[i]), new RocBankValue(atr.Span[i])) : window!.Next(high[i], low[i], input[i], true);
            var point = KeltnerWindow.Bands(stages.Item1, stages.Item2, multiplier);
            result.WritableSpan[i] = key == "UpperBand" ? point.Upper : key == "LowerBand" ? point.Lower : point.Middle;
        }
        return result;
    }

    /// <summary>Computes the selected percentage envelope around the configured moving average.</summary>
    internal static ComputeBuffer ComputeMovingAverageEnvelopeFast(StockData data, ComputeContext context, int length = 20,
        double pct = 0.025, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateMovingAverageEnvelope publishes the average itself as its MiddleBand, taken over the
        // CHAINED series with whichever average it was given. This read the close, and chose the average
        // from a switch that knew the simple and exponential types and fell back to simple for the rest, so
        // any other type silently became a simple average and a chained source was ignored entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var pool = ArrayPool<double>.Shared;
        var maArray = pool.Rent(count);

        try
        {
            var maSpan = maArray.AsSpan(0, count);
            StochasticSmooth(data, maType, length, input, maSpan);

            // Scale the requested envelope around its middle average.
            var buffer = context.Rent(count);
            for (var i = 0; i < count; i++)
            {
                buffer.WritableSpan[i] = band == ChannelBand.Middle ? maSpan[i] : RoundedPercentageBand.Of(maSpan[i], pct, band == ChannelBand.Upper ? 1 : -1);
            }

            return buffer;
        }
        finally
        {
            pool.Return(maArray);
        }
    }

    /// <summary>
    /// Computes Moving Average Support/Resistance using zero-allocation fast path.
    /// Returns the MA of close.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageSupportResistanceFast(StockData data, ComputeContext context,
        int length = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle, double factor = 2)
    {
        HighLowBandsWindow.ValidateShift(factor);
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), buffer.WritableSpan);
        else
        {
            using var window = new SupportResistanceWindow(maType, length);
            for (var i = 0; i < input.Count; i++) buffer.WritableSpan[i] = window.Next(input[i], true);
        }
        var output = buffer.WritableSpan;
        for (var i = 0; i < output.Length; i++) output[i] = band == ChannelBand.Upper ? HighLowBandsWindow.Shift(output[i], factor)
            : band == ChannelBand.Lower ? SupportResistanceWindow.Lower(output[i], factor) : output[i];
        return buffer;
    }

    /// <summary>
    /// Computes Variable Moving Average Bands through the shared exact band calculation.
    /// Returns the middle band (VMA).
    /// </summary>
    internal static ComputeBuffer ComputeVariableMovingAverageBandsFast(StockData data, ComputeContext context, int length = 6,
        double mult = 1.5, MovingAvgType maType = MovingAvgType.VariableMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var points=VariableBandWindow.Calculate(data,maType,length,mult);
        var values=band==ChannelBand.Upper ? points.Upper : band==ChannelBand.Lower ? points.Lower : points.Middle;
        var buffer=context.Rent(values.Length); values.AsSpan().CopyTo(buffer.WritableSpan); return buffer;
    }

    /// <summary>
    /// Computes Narrow Sideways Channel using zero-allocation fast path.
    /// Returns the middle band (MA).
    /// </summary>
    internal static ComputeBuffer ComputeNarrowSidewaysChannelFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // Pct is an obsolete no-op; the typed channel uses three population deviations.
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; length = Math.Max(1, length); var result = context.Rent(input.Count);
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides) BollingerArithmetic.Mean(SpanCompat.AsReadOnlySpan(input), result.WritableSpan, length);
        else MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), result.WritableSpan);
        if (band != ChannelBand.Middle)
        {
            using var deviation = new ExactPopulationWindow(length); var multiplier = band == ChannelBand.Upper ? 3 : -3;
            for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = BollingerArithmetic.Band(result.Span[i], deviation.Next(input[i], true), multiplier);
        }
        return result;
    }

    /// <summary>
    /// Computes High Low Bands using zero-allocation fast path.
    /// Returns the middle band (SMA of close).
    /// </summary>
    internal static ComputeBuffer ComputeHighLowBandsFast(StockData data, ComputeContext context, int length = 14, double pctShift = 1,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateHighLowBands centres its bands on the chained series smoothed twice, not on the close
        // smoothed once, and shifts them by a percentage of that centre. A shift of zero is the centre itself.
        HighLowBandsWindow.ValidateShift(pctShift);
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (!ComponentAverage.HasOverrides && StrengthWindow.Supports(maType))
        {
            var result = context.Rent(count); using var window = new HighLowBandsWindow(maType, length);
            for (var i = 0; i < count; i++) result.WritableSpan[i] = HighLowBandsWindow.Shift(window.Next(inputList[i], true), pctShift);
            return result;
        }
        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), smoothed.WritableSpan);

        using var twiceSmoothed = context.Rent(count);
        MovingAverage(data, maType, length, smoothed.Span, twiceSmoothed.WritableSpan);
        var tma = twiceSmoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = HighLowBandsWindow.Shift(tma[i], pctShift);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Auto Dispersion Bands using zero-allocation fast path.
    /// Returns the middle band (WMA of close).
    /// </summary>
    internal static ComputeBuffer ComputeAutoDispersionBandsFast(StockData data, ComputeContext context, int length = 90,
        int smoothLength = 140, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        length = Math.Max(1, length); smoothLength = Math.Max(1, smoothLength); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var window = new AutoDispersionWindow(maType, length, smoothLength, external, Math.Max(1, input.Count)); var result = context.Rent(input.Count);
        if (external)
        {
            using var rawUpper = context.Rent(input.Count); using var rawLower = context.Rent(input.Count); using var first = context.Rent(input.Count); using var upper = context.Rent(input.Count); using var lower = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) { var p = window.Generate(input[i], true); rawUpper.WritableSpan[i] = p.Upper.Publish(); rawLower.WritableSpan[i] = p.Lower.Publish(); }
            MovingAverage(data, maType, length, rawUpper.Span, first.WritableSpan); MovingAverage(data, maType, smoothLength, first.Span, upper.WritableSpan); MovingAverage(data, maType, length, rawLower.Span, first.WritableSpan); MovingAverage(data, maType, smoothLength, first.Span, lower.WritableSpan);
            for (var i = 0; i < input.Count; i++) { var p = AutoDispersionWindow.Bands(new RocBankValue(upper.Span[i]), new RocBankValue(lower.Span[i])); result.WritableSpan[i] = band == ChannelBand.Upper ? p.Upper : band == ChannelBand.Lower ? p.Lower : p.Middle; }
        }
        else for (var i = 0; i < input.Count; i++) { var p = window.Next(input[i], true); result.WritableSpan[i] = band == ChannelBand.Upper ? p.Upper : band == ChannelBand.Lower ? p.Lower : p.Middle; }
        return result;
    }

    /// <summary>
    /// Computes Bollinger Bands Fibonacci Ratios using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsFibonacciRatiosFast(StockData data, ComputeContext context,
        int length = 20, double fibRatio1 = 1.618, double fibRatio2 = 2.618, double fibRatio3 = 4.236,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        return ComputeStollerAverageRangeChannelsFast(data, context, length, fibRatio3, maType, band);
    }

    /// <summary>
    /// Computes Bollinger Bands with ATR Percentage using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsWithAtrPctFast(StockData data, ComputeContext context,
        int length = 14, int bbLength = 20, double stdDevMult = 2,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var basis = context.Rent(count);
        if (external) MovingAverage(data, maType, Math.Max(1, bbLength), SpanCompat.AsReadOnlySpan(input), basis.WritableSpan);
        var result = context.Rent(count); using var window = new AtrPercentBandWindow(maType, length, bbLength, stdDevMult, external, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var point = window.Next(high[i], low[i], input[i], true, external ? new RocBankValue(basis.Span[i]) : null);
            result.WritableSpan[i] = band == ChannelBand.Upper ? point.Upper : band == ChannelBand.Lower ? point.Lower : point.Middle;
        }
        return result;
    }

    /// <summary>
    /// Computes Kirshenbaum Bands using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeTimeSeriesForecastFast(StockData data, ComputeContext context, int length = 500, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; using var window = new TimeSeriesForecastWindow(length); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var p = window.Next(input[i], true); result.WritableSpan[i] = outputKey == "UpperBand" ? p.Upper : outputKey == "LowerBand" ? p.Lower : p.Middle; } return result;
    }

    internal static ComputeBuffer ComputeKirshenbaumBandsFast(StockData data, ComputeContext context,
        int length1 = 30, int length2 = 20, double stdDevFactor = 1,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        HighLowBandsWindow.ValidateShift(stdDevFactor); length1 = Math.Max(1, length1); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var mean = context.Rent(external ? input.Count : 0); if (external) MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(input), mean.WritableSpan);
        using var window = new KirshenbaumWindow(maType, length1, length2, stdDevFactor, external, Math.Max(1, input.Count)); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var p = window.Next(input[i], true, external ? mean.Span[i] : null); result.WritableSpan[i] = band == ChannelBand.Upper ? p.Upper : band == ChannelBand.Lower ? p.Lower : p.Middle; }
        return result;
    }

    /// <summary>
    /// Computes Smoothed Volatility Bands using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeSmoothedVolatilityBandsFast(StockData data, ComputeContext context, int length1 = 20,
        int length2 = 21, double deviation = 2.4, double bandAdjust = 0.9,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count; var period = SmoothedVolatilityWindow.AtrPeriod(length1);
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var atr = context.Rent(count); using var basis = context.Rent(count); using var center = context.Rent(count);
        if (external)
        {
            var ranges = CalculationsHelper.GetTrueRangeList(data);
            MovingAverage(data, maType, period, SpanCompat.AsReadOnlySpan(ranges), atr.WritableSpan);
            MovingAverage(data, maType, Math.Max(1, length1), SpanCompat.AsReadOnlySpan(input), basis.WritableSpan);
            MovingAverage(data, maType, Math.Max(1, length2), SpanCompat.AsReadOnlySpan(input), center.WritableSpan);
        }
        var result = context.Rent(count); using var window = new SmoothedVolatilityWindow(maType, length1, length2, deviation, bandAdjust, external, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var point = window.Next(high[i], low[i], input[i], true, external ? new RocBankValue(atr.Span[i]) : null, external ? new RocBankValue(basis.Span[i]) : null, external ? new RocBankValue(center.Span[i]) : null);
            result.WritableSpan[i] = band == ChannelBand.Upper ? point.Upper : band == ChannelBand.Lower ? point.Lower : point.Middle;
        }
        return result;
    }

    /// <summary>
    /// Computes Stoller Average Range Channels (STARC) using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeStollerAverageRangeChannelsFast(StockData data, ComputeContext context,
        int length = 14, double atrMult = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        ChannelBand band = ChannelBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var center = context.Rent(count); using var atr = context.Rent(count);
        if (external)
        {
            var ranges = CalculationsHelper.GetTrueRangeList(data);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), center.WritableSpan);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(ranges), atr.WritableSpan);
        }
        var result = context.Rent(count); using var window = external ? null : new KeltnerWindow(maType, length, length, maType, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var stages = external ? (new RocBankValue(center.Span[i]), new RocBankValue(atr.Span[i])) : window!.Next(high[i], low[i], input[i], true);
            var point = RangeChannelWindow.Output(input[i], stages.Item1, stages.Item2, atrMult, false);
            result.WritableSpan[i] = band == ChannelBand.Upper ? point.Upper : band == ChannelBand.Lower ? point.Lower : point.Middle;
        }
        return result;
    }

    /// <summary>
    /// Computes Vervoort Volatility Bands using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeVervoortVolatilityBandsFast(StockData data, ComputeContext context, int length1 = 8,
        int length2 = 13, double devMult = 3.55, double lowBandMult = 0.9,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateVervoortVolatilityBands measures the bar's reach - from the previous low when the series
        // rose, from the current low when it fell - and offsets the twice averaged series by a multiple of
        // that reach, by a smaller multiple below than above. The midline is a plain average of the once
        // averaged series, which is not the same as averaging it twice.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);

        using var highBuffer = context.Rent(count);
        using var lowBuffer = context.Rent(count);
        CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
        var lows = lowBuffer.Span;

        using var medianAverages = context.Rent(count);
        MovingAverage(data, maType, length1, input, medianAverages.WritableSpan);
        var medianAverage = medianAverages.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var medianTotal = new RollingSum();
        var reachTotal = new RollingSum();
        using var deviations = context.Rent(count);
        var deviation = deviations.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            medianTotal.Add(medianAverage[i]);

            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;
            var reach = currentValue >= previousValue ? currentValue - previousLow : previousValue - lows[i];
            reachTotal.Add(reach);

            deviation[i] = devMult * reachTotal.Average(length2);
            output[i] = medianTotal.Average(length1);
        }

        using var smoothedMedians = context.Rent(count);
        MovingAverage(data, maType, length1, medianAverages.Span, smoothedMedians.WritableSpan);
        var smoothedMedian = smoothedMedians.Span;

        using var smoothedDeviations = context.Rent(count);
        MovingAverage(data, maType, length1, deviations.Span, smoothedDeviations.WritableSpan);
        var smoothedDeviation = smoothedDeviations.Span;

        if (band == ChannelBand.Middle)
        {
            return buffer;
        }

        var multiplier = band == ChannelBand.Upper ? 1 : -lowBandMult;
        for (var i = 0; i < count; i++)
        {
            output[i] = smoothedMedian[i] + (multiplier * smoothedDeviation[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Trend Trader Bands using zero-allocation fast path.
