            for (var i = 0; i < input.Count; i++) { var point = TrendTraderWindow.Bands(new RocBankValue(result.Span[i]), bandStep); result.WritableSpan[i] = band == ChannelBand.Upper ? point.Upper : band == ChannelBand.Lower ? point.Lower : point.Middle; }
        }
        return result;
    }

    /// <summary>
    /// Computes Scalpers Channel using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeScalpersChannelFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int rangeLength = 15, string? outputKey = null)
    {
        if (outputKey is "UpperBand" or "MiddleBand" or "LowerBand")
        {
            var (_, highValues, lowValues, _, _) = CalculationsHelper.GetInputValuesList(data); var bands = context.Rent(highValues.Count);
            var highs = new RollingMinMax(Math.Max(1, rangeLength)); var lows = new RollingMinMax(Math.Max(1, rangeLength));
            for (var i = 0; i < highValues.Count; i++) { highs.Add(highValues[i]); lows.Add(lowValues[i]); var midpoint = new ExactMeanAccumulator(); midpoint.Add(highs.Max); midpoint.Add(lows.Min); bands.WritableSpan[i] = outputKey == "UpperBand" ? highs.Max : outputKey == "LowerBand" ? lows.Min : midpoint.Mean(2); }
            return bands;
        }
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var average = context.Rent(external ? input.Count : 0); using var atr = context.Rent(external ? input.Count : 0);
        if (external)
        {
            var ranges = CalculationsHelper.GetTrueRangeList(data);
            MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(input), average.WritableSpan);
            MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(ranges), atr.WritableSpan);
        }
        using var window = new ScalperChannelWindow(external ? MovingAvgType.SimpleMovingAverage : maType, rangeLength, length, Math.Max(1, input.Count)); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++)
        {
            var point = window.Next(high[i], low[i], input[i], true, external ? new RocBankValue(average.Span[i]) : null, external ? new RocBankValue(atr.Span[i]) : null);
            result.WritableSpan[i] = outputKey == "UpperBand" ? point.Upper : outputKey == "LowerBand" ? point.Lower : outputKey == "MiddleBand" ? point.Middle : point.Scalper;
        }
        return result;
    }

    /// <summary>
    /// Computes Hurst Cycle Channel using zero-allocation fast path.
    /// Returns the middle line (Wilder smoothed).
    /// </summary>
    /// <summary>
    /// Which of the Hurst cycle channel's eight series an arm has been asked for. Two envelopes and the two
    /// oscillators drawn from them all fall out of one walk, so the series is chosen on the way out.
    /// </summary>
    internal enum HurstCycleSeries
    {
        FastMiddleBand,
        FastUpperBand,
        FastLowerBand,
        SlowMiddleBand,
        SlowUpperBand,
        SlowLowerBand,
        OMed,
        OShort
    }

    internal static ComputeBuffer ComputeHurstCycleChannelFast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 30, double fastMult = 1, double slowMult = 3, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod,
        HurstCycleSeries series = HurstCycleSeries.FastMiddleBand)
    {
        HighLowBandsWindow.ValidateShift(fastMult); HighLowBandsWindow.ValidateShift(slowMult); var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        var fastCycle = HurstCycleWindow.HalfCycle(fastLength); var slowCycle = HurstCycleWindow.HalfCycle(slowLength); var count = external ? input.Count : 0;
        using var fastAtr = context.Rent(count); using var slowAtr = context.Rent(count); using var fastMean = context.Rent(count); using var slowMean = context.Rent(count);
        if (external)
        {
            var ranges = CalculationsHelper.GetTrueRangeList(data); MovingAverage(data, maType, fastCycle, SpanCompat.AsReadOnlySpan(ranges), fastAtr.WritableSpan); MovingAverage(data, maType, slowCycle, SpanCompat.AsReadOnlySpan(ranges), slowAtr.WritableSpan);
            MovingAverage(data, maType, fastCycle, SpanCompat.AsReadOnlySpan(input), fastMean.WritableSpan); MovingAverage(data, maType, slowCycle, SpanCompat.AsReadOnlySpan(input), slowMean.WritableSpan);
        }
        using var window = new HurstCycleWindow(maType, fastLength, slowLength, fastMult, slowMult, external, Math.Max(1, input.Count)); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++)
        {
            var point = window.Next(high[i], low[i], input[i], true, external ? new RocBankValue(fastAtr.Span[i]) : null, external ? new RocBankValue(slowAtr.Span[i]) : null, external ? new RocBankValue(fastMean.Span[i]) : null, external ? new RocBankValue(slowMean.Span[i]) : null);
            result.WritableSpan[i] = series switch { HurstCycleSeries.FastUpperBand => point.FastUpper, HurstCycleSeries.FastLowerBand => point.FastLower, HurstCycleSeries.SlowUpperBand => point.SlowUpper, HurstCycleSeries.SlowMiddleBand => point.SlowMiddle, HurstCycleSeries.SlowLowerBand => point.SlowLower, HurstCycleSeries.OMed => point.OMed, HurstCycleSeries.OShort => point.OShort, _ => point.FastMiddle };
        }
        return result;
    }

    /// <summary>
    /// Computes Price Curve Channel using zero-allocation fast path.
    /// Returns the middle line (Wilder smoothed).
    /// </summary>
    /// <summary>
    /// Which of a channel's three bands an arm has been asked for. A channel computes all three together, so
    /// the band is chosen on the way out rather than by three arms that would each repeat the walk.
    /// </summary>
    internal enum ChannelBand
    {
        Upper,
        Middle,
        Lower
    }

    internal static ComputeBuffer ComputePriceCurveChannelFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, ChannelBand band = ChannelBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using ComputeBuffer? atr = external ? ComputeAtrFast(data, context, Math.Max(1, length), maType) : null;
        using var window = new PriceDriftWindow(external ? MovingAvgType.SimpleMovingAverage : maType, length, true, Math.Max(1, input.Count)); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], true, atr is null ? null : new RocBankValue(atr.Value.Span[i])); result.WritableSpan[i] = band == ChannelBand.Upper ? point.Upper : band == ChannelBand.Lower ? point.Lower : point.Middle; }
        return result;
    }

    /// <summary>
    /// Computes Price Headley Acceleration Bands using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputePriceHeadleyAccelerationBandsFast(StockData data, ComputeContext context,
        int length = 20, double factor = 0.001, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        ChannelBand band = ChannelBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var upper = context.Rent(count); using var middle = context.Rent(count); using var lower = context.Rent(count);
        if (external) MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(input), middle.WritableSpan);
        using var window = external ? null : new HeadleyBandWindow(maType, length, factor, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            if (external) { var bounds = HeadleyBandWindow.Boundaries(high[i], low[i], factor); upper.WritableSpan[i] = bounds.Upper.Publish(); lower.WritableSpan[i] = bounds.Lower.Publish(); }
            else { var point = window!.Next(high[i], low[i], input[i], true); upper.WritableSpan[i] = point.Upper; middle.WritableSpan[i] = point.Middle; lower.WritableSpan[i] = point.Lower; }
        }
        if (external)
        {
            using var stage = context.Rent(count);
            MovingAverage(data, maType, Math.Max(1, length), upper.Span, stage.WritableSpan); stage.Span.CopyTo(upper.WritableSpan);
            MovingAverage(data, maType, Math.Max(1, length), lower.Span, stage.WritableSpan); stage.Span.CopyTo(lower.WritableSpan);
        }
        var result = context.Rent(count); (band == ChannelBand.Upper ? upper.Span : band == ChannelBand.Lower ? lower.Span : middle.Span).CopyTo(result.WritableSpan); return result;
    }

