    }

    /// <summary>Computes the selected ROC envelope output; the default is smoothed ROC.</summary>
    internal static ComputeBuffer ComputeRateOfChangeBandsFast(StockData data, ComputeContext context, int length = 12, int smoothLength = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var count = input.Count;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var raw = context.Rent(count); using var roc = context.Rent(count);
        var result = context.Rent(count); using var window = new RocBandWindow(maType, length, smoothLength, external, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var point = window.Next(input[i], true); raw.WritableSpan[i] = point.RawReturn; roc.WritableSpan[i] = point.Roc;
            result.WritableSpan[i] = outputKey == "UpperBand" ? point.Upper : outputKey == "LowerBand" ? -point.Upper : 0;
        }
        if (external) MovingAverage(data, maType, Math.Max(1, smoothLength), raw.Span, roc.WritableSpan);
        if (outputKey is not ("UpperBand" or "LowerBand" or "MiddleBand")) roc.Span.CopyTo(result.WritableSpan);
        return result;
    }

    /// <summary>
    /// Computes Absolute Strength MTF Indicator using zero-allocation fast path.
    /// Returns the smoothed bulls-bears value.
    /// </summary>
    internal static ComputeBuffer ComputeAbsoluteStrengthMTFFast(StockData data, ComputeContext context, int length = 50,
        int smoothLength = 25, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        BullBearSeries series = BullBearSeries.Bulls)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            var lagged = input.Select((_, i) => i == 0 ? 0 : input[i - 1]).ToArray();
            using var current = context.Rent(input.Count); using var previous = context.Rent(input.Count); using var values = context.Rent(input.Count);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), current.WritableSpan);
            MovingAverage(data, maType, length, lagged, previous.WritableSpan);
            for (var i = 0; i < input.Count; i++)
            {
                var difference = AbsoluteStrengthMtfWindow.Difference(new RocBankValue(current.Span[i]), new RocBankValue(previous.Span[i]));
                values.WritableSpan[i] = series == BullBearSeries.Bulls ? Math.Max(0, difference.Publish()) : Math.Max(0, -difference.Publish());
            }
            MovingAverage(data, maType, smoothLength, values.Span, result.WritableSpan);
        }
        else
        {
            using var window = new AbsoluteStrengthMtfWindow(maType, length, smoothLength, Math.Max(1, input.Count));
            for (var i = 0; i < input.Count; i++) { var value = window.Next(input[i], true); result.WritableSpan[i] = series == BullBearSeries.Bulls ? value.Bulls : value.Bears; }
        }
        return result;
    }

    /// <summary>
    /// Which half of an absolute strength reading an arm has been asked for: the rising half or the falling
    /// half. They are not bands around an average, so they do not fit <see cref="ChannelBand"/>.
    /// </summary>
    internal enum BullBearSeries
    {
        Bulls,
        Bears
    }

    /// <summary>
    /// Computes Adaptive Price Zone Indicator using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeAdaptivePriceZoneFast(StockData data, ComputeContext context, int length = 20, double pct = 2,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count; var period = AdaptiveZoneWindow.Period(length);
        using var center = context.Rent(count); using var width = context.Rent(count);
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        if (external)
        {
            using var first = context.Rent(count); using var range = context.Rent(count); using var rangeFirst = context.Rent(count);
            MovingAverage(data, maType, period, SpanCompat.AsReadOnlySpan(input), first.WritableSpan); MovingAverage(data, maType, period, first.Span, center.WritableSpan);
            for (var i = 0; i < count; i++) range.WritableSpan[i] = high[i] - low[i];
            MovingAverage(data, maType, period, range.Span, rangeFirst.WritableSpan); MovingAverage(data, maType, period, rangeFirst.Span, width.WritableSpan);
        }
        var result = context.Rent(count); using var window = new AdaptiveZoneWindow(maType, length, pct, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var point = external ? AdaptiveZoneWindow.Bands(new RocBankValue(center.Span[i]), new RocBankValue(width.Span[i]), pct) : window.Next(input[i], high[i], low[i], true);
            result.WritableSpan[i] = band == ChannelBand.Upper ? point.Upper : band == ChannelBand.Lower ? point.Lower : point.Middle;
        }
        return result;
    }

    /// <summary>
    /// Computes Dynamic Support and Resistance using zero-allocation fast path.
    /// Returns the Wilder smoothed close.
    /// </summary>
    /// <summary>
    /// Which of a support and resistance indicator's three published series an arm has been asked for. These
    /// are not bands around an average, so they do not fit <see cref="ChannelBand"/>: the support is measured
    /// down from the highest high and the resistance up from the lowest low, and they can cross.
    /// </summary>
    internal enum SupportResistanceBand
    {
        Support,
        Middle,
        Resistance
    }

    internal static ComputeBuffer ComputeDynamicSupportAndResistanceFast(StockData data, ComputeContext context, int length = 25,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, SupportResistanceBand band = SupportResistanceBand.Middle)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var count = input.Count;
        var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var atr = context.Rent(count);
        if (external)
        {
            var ranges = CalculationsHelper.GetTrueRangeList(data);
            MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(ranges), atr.WritableSpan);
        }
        var result = context.Rent(count); using var window = new DynamicSupportWindow(maType, length, external, Math.Max(1, count));
        for (var i = 0; i < count; i++)
        {
            var point = window.Next(high[i], low[i], input[i], true, external ? new RocBankValue(atr.Span[i]) : null);
            result.WritableSpan[i] = band == SupportResistanceBand.Support ? point.Support : band == SupportResistanceBand.Resistance ? point.Resistance : point.Middle;
        }
        return result;
    }

    /// <summary>
    /// Computes Apirine Slow RSI using zero-allocation fast path.
    /// Returns smoothed RSI.
    /// </summary>
    internal static ComputeBuffer ComputeApirineSlowRsiFast(StockData data, ComputeContext context, int length = 14,
        int smoothLength = 6, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateApirineSlowRelativeStrengthIndex measures the chained series against its own moving average
        // rather than against the previous bar, smooths the two one-sided distances with that same average and
        // reads their ratio as a relative strength. OscillatorCore.RelativeStrengthIndex is the ordinary
        // Wilders relative strength index of the close, which is a different indicator entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var window = new ApirineRsiWindow(maType, length, smoothLength, count);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = window.Next(input[i], true);
            return stable;
        }

        using var average = context.Rent(count);
        var substitutions = ComponentAverage.Substitutions;
        MovingAverage(data, maType, smoothLength, input, average.WritableSpan);
        var stableWilder = maType == MovingAvgType.WildersSmoothingMethod && ComponentAverage.Substitutions == substitutions;
        var ema = average.Span;

        using var aboveSeries = context.Rent(count);
        using var belowSeries = context.Rent(count);
        var above = aboveSeries.WritableSpan;
        var below = belowSeries.WritableSpan;
        double residual = 0, previousPrice = 0;
        var retention = 1 - 1d / Math.Max(1, smoothLength);
        for (var i = 0; i < count; i++)
        {
            var value = input[i];
            // Track price minus its Wilder average without subtracting nearly equal prices.
            // A caller-supplied average must retain its own definition.
            residual = stableWilder ? retention * (residual + (value - previousPrice)) : value - ema[i];
            previousPrice = value;
            above[i] = Math.Max(residual, 0);
            below[i] = Math.Max(-residual, 0);
        }

        using var smoothedAbove = context.Rent(count);
        using var smoothedBelow = context.Rent(count);
        MovingAverage(data, maType, length, aboveSeries.Span, smoothedAbove.WritableSpan);
        MovingAverage(data, maType, length, belowSeries.Span, smoothedBelow.WritableSpan);
        var gain = smoothedAbove.Span;
        var loss = smoothedBelow.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var rs = loss[i] != 0 ? gain[i] / loss[i] : 0;
            output[i] = loss[i] == 0 ? 100 : gain[i] == 0 ? 0 : MathHelper.MinOrMax(100 - (100 / (1 + rs)), 100, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Elder Safe Zone Stops using zero-allocation fast path.
    /// Returns the stop line.
    /// </summary>
    internal static ComputeBuffer ComputeElderSafeZoneStopsFast(StockData data, ComputeContext context, int length1 = 63,
        int length2 = 22, int length3 = 3, double factor = 2.5,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var window = new ElderSafeZoneWindow(maType, length1, length2, length3, factor, external); using ComputeBuffer? trend = external ? context.Rent(input.Count) : null;
        if (external) MovingAverage(data, maType, Math.Max(1, length1), SpanCompat.AsReadOnlySpan(input), trend!.Value.WritableSpan); var result = context.Rent(input.Count);
        try { for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(high[i], low[i], input[i], true, external ? trend!.Value.Span[i] : null).Value; return result; }
        catch { result.Dispose(); throw; }
    }

    /// <summary>
    /// Computes Enhanced Index using zero-allocation fast path.
    /// Returns the normalized index or its selected signal mean.
    /// </summary>
    internal static ComputeBuffer ComputeEnhancedIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int signalLength = 8, bool signal = false)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var buffer = context.Rent(input.Count);
        if (!StrengthWindow.Supports(maType) || ComponentAverage.HasOverrides)
        {
            var components = EnhancedIndexWindow.Components(data, input, high, low, maType, length, signalLength, true, signal);
            (signal ? components.Signal : components.Line).AsSpan().CopyTo(buffer.WritableSpan);
        }
        else
        {
            using var window = new EnhancedIndexWindow(maType, length, signalLength);
            for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], true); buffer.WritableSpan[i] = signal ? point.SignalLine : point.Line; }
        }
        return buffer;
    }

    /// <summary>
    /// Computes Fast and Slow Kurtosis Oscillator using zero-allocation fast path.
    /// Returns the smoothed kurtosis value.
    /// </summary>
    internal static ComputeBuffer ComputeFastAndSlowKurtosisFast(StockData data, ComputeContext context, int length = 3, double ratio = 0.03,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new FastSlowKurtosisWindow(length, ratio, maType); var result = context.Rent(input.Count);
        // A missing key is the main-line component contract used by the RSI/Stochastic composites.
        if (outputKey is null) { for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Line(input[i], true).Publish(); }
        else if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var line = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) line.WritableSpan[i] = window.Line(input[i], true).Publish();
            using var signal = context.Rent(input.Count); MovingAverage(data, maType, Math.Max(1, length), line.Span, signal.WritableSpan);
            (outputKey == "Signal" ? signal.Span : line.Span).CopyTo(result.WritableSpan);
        }
        else for (var i = 0; i < input.Count; i++) { var value = window.Next(input[i], true); result.WritableSpan[i] = outputKey == "Signal" ? value.Signal : value.Line; }
        return result;
    }

