    /// <summary>
    /// Computes Kase Dev Stop V2 using zero-allocation fast path.
    /// Returns the trailing stop level based on trend direction and volatility.
    /// </summary>
    private static ComputeBuffer ComputeKaseSerialDependencyFast(StockData data, ComputeContext context, int length, string? key)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var highs = context.Rent(data.Count);
        using var lows = context.Rent(data.Count);
        CustomRange(data, SpanCompat.AsReadOnlySpan(input), highs.WritableSpan, lows.WritableSpan);
        using var returns = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            returns.WritableSpan[i] = i == 0 ? 0 : StableLogRatio.OfSameSign(input[i], input[i - 1]);
        }
        using var deviation = context.Rent(data.Count);
        VolatilityCore.StandardDeviation(returns.Span, deviation.WritableSpan, length);
        var result = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var prior = i < length ? 0 : key == "KsdiDn" ? highs.Span[i - length] : lows.Span[i - length];
            var log = StableLogRatio.OfSameSign(key == "KsdiDn" ? lows.Span[i] : highs.Span[i], prior);
            result.WritableSpan[i] = deviation.Span[i] != 0 ? log / deviation.Span[i] : 0;
        }
        return result;
    }

    internal static ComputeBuffer ComputeKaseDevStopV1Fast(StockData data, ComputeContext context,
        KaseDevStopV1SpecOptions options, string? outputKey)
    {
        var (input, high, low, close) = KaseStopV1Window.Inputs(data); var external = ComponentAverage.HasOverrides; var legacy = !StrengthWindow.Supports(options.MaType); using var window = new KaseStopV1Window(options.MaType, options.FastLength, options.SlowLength, options.Length, options.StdDev1, options.StdDev2, options.StdDev3, options.StdDev4, external);
        using ComputeBuffer? mean = external || legacy ? context.Rent(input.Count) : null; using ComputeBuffer? slow = external ? context.Rent(input.Count) : null; using ComputeBuffer? fast = external ? context.Rent(input.Count) : null;
        if (external || legacy) { MovingAverage(data, options.MaType, options.Length, KaseStopV1Window.PublishedRanges(high, low, close), mean!.Value.WritableSpan); if (external) { MovingAverage(data, options.MaType, options.SlowLength, SpanCompat.AsReadOnlySpan(input), slow!.Value.WritableSpan); MovingAverage(data, options.MaType, options.FastLength, SpanCompat.AsReadOnlySpan(input), fast!.Value.WritableSpan); } }
        var result = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], close[i], input[i], true, external || legacy ? mean!.Value.Span[i] : null, external ? slow!.Value.Span[i] : null, external ? fast!.Value.Span[i] : null); result.WritableSpan[i] = outputKey switch { "WarningLine" => point.WarningLine, "Dev2" => point.Dev2, "Dev3" => point.Dev3, _ => point.Dev1 }; } return result; }
        catch { result.Dispose(); throw; }
    }

    internal static ComputeBuffer ComputeKaseDevStopV2Fast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 21, int length = 20, double stdDev = 0,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var window = new KaseStopV2Window(maType, fastLength, slowLength, length, stdDev, stdDev, stdDev, stdDev, external);
        using ComputeBuffer? fast = external ? context.Rent(input.Count) : null; using ComputeBuffer? slow = external ? context.Rent(input.Count) : null; using ComputeBuffer? mean = external ? context.Rent(input.Count) : null;
        if (external) { MovingAverage(data, maType, Math.Max(1, fastLength), SpanCompat.AsReadOnlySpan(input), fast!.Value.WritableSpan); MovingAverage(data, maType, Math.Max(1, slowLength), SpanCompat.AsReadOnlySpan(input), slow!.Value.WritableSpan); MovingAverage(data, maType, Math.Max(1, length), KaseStopV2Window.PublishedRanges(high, low, input), mean!.Value.WritableSpan); }
        var result = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(high[i], low[i], input[i], true, external ? fast!.Value.Span[i] : null, external ? slow!.Value.Span[i] : null, external ? mean!.Value.Span[i] : null).Dev1; return result; }
        catch { result.Dispose(); throw; }
    }

