    /// <summary>
    /// Computes Multi Vote On Balance Volume using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMultiVoteOnBalanceVolumeFast(StockData data, ComputeContext context)
    {
        // CalculateMultiVoteOnBalanceVolume takes one vote each from the high, the low and the chained
        // series - plus one for a rise, minus one for a fall - and accumulates volume in millions scaled by
        // that total. The arm this replaces returned a moving average of the close, which is not this
        // indicator at all. The average of the accumulation is published under the separate "Signal" key,
        // so the primary path takes neither a length nor a moving average type.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double mvo = 0;
        for (var i = 0; i < count; i++)
        {
            var prevClose = i >= 1 ? input[i - 1] : 0;
            var prevHigh = i >= 1 ? highs[i - 1] : 0;
            var prevLow = i >= 1 ? lows[i - 1] : 0;

            double highVote = highs[i] > prevHigh ? 1 : highs[i] < prevHigh ? -1 : 0;
            double lowVote = lows[i] > prevLow ? 1 : lows[i] < prevLow ? -1 : 0;
            double closeVote = input[i] > prevClose ? 1 : input[i] < prevClose ? -1 : 0;

            mvo += volumes[i] / 1000000 * (highVote + lowVote + closeVote);
            output[i] = mvo;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Natural Directional Combo using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalDirectionalComboFast(StockData data, ComputeContext context, int length = 40,
        int smoothLength = 20, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalDirectionalCombo multiplies the natural directional index by the natural stochastic
        // indicator, both read off the caller's own series with the same two lengths, and takes the signed
        // square root of that. Where the two agree on direction the product is replaced by the average of each
        // one scaled by the other's magnitude, which keeps the sign the pair already share.
        var count = data.Count;

        using var directional = ComputeNaturalDirectionalIndexFast(data, context, length, smoothLength, maType);
        using var stochastic = ComputeNaturalStochasticIndicatorFast(data, context, length, smoothLength, maType);
        var ndxSpan = directional.Span;
        var nstSpan = stochastic.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var ndx = ndxSpan[i];
            var nst = nstSpan[i];
            var v3 = Math.Sign(ndx) != Math.Sign(nst) ? ndx * nst : ((Math.Abs(ndx) * nst) + (Math.Abs(nst) * ndx)) / 2;

            output[i] = Math.Sign(v3) * MathHelper.Sqrt(Math.Abs(v3));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Natural Directional Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalDirectionalIndexFast(StockData data, ComputeContext context, int length = 40,
        int smoothLength = 20, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalDirectionalIndex works on the natural logarithm of the chained series, weighting
        // each lookback by the inverse square root of its distance and dividing by a running absolute sum
        // that grows across the window. The core routine implemented none of that.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;

        using var raw = context.Rent(count);
        var rawNdx = raw.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            ln[i] = input[i] > 0 ? Math.Log(input[i]) * 1000 : 0;

            double weightSum = 0, denomSum = 0, absSum = 0;
            for (var j = 0; j < length; j++)
            {
                var prevLn = i >= j + 1 ? ln[i - (j + 1)] : 0;
                var currLn = i >= j ? ln[i - j] : 0;
                absSum += Math.Abs(prevLn - currLn);
                var frac = absSum != 0 ? (ln[i] - currLn) / absSum : 0;
                var ratio = 1 / MathHelper.Sqrt(j + 1);
                weightSum += frac * ratio;
                denomSum += ratio;
            }

            rawNdx[i] = denomSum != 0 ? weightSum / denomSum * 100 : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, raw.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Market Mirror using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMarketMirrorFast(StockData data, ComputeContext context, int length = 40,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalMarketMirror publishes "Nmm": the moving average of the mean square root weighted
        // change in the log of the chained series across the whole window. The two case switch this replaced was
        // a plain moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            ln[i] = input[i] > 0 ? Math.Log(input[i]) * 1000 : 0;
        }

        using var weightedAverage = context.Rent(count);
        var oiAvg = weightedAverage.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double sum = 0;
            for (var j = 1; j <= length; j++)
            {
                var prevLn = i >= j ? ln[i - j] : 0;

                sum += (ln[i] - prevLn) / MathHelper.Sqrt(j) * 100;
            }

            oiAvg[i] = sum / length;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, weightedAverage.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Market River using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMarketRiverFast(StockData data, ComputeContext context, int length = 40,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalMarketRiver publishes "Nmr": the moving average of a square root weighted sum of the
        // bar to bar changes in the log of the chained series. The two case switch this replaced was a plain
        // moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            ln[i] = input[i] > 0 ? Math.Log(input[i]) * 1000 : 0;
        }

        using var weightedSum = context.Rent(count);
        var oiSum = weightedSum.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double sum = 0;
            for (var j = 0; j < length; j++)
            {
                var currentLn = i >= j ? ln[i - j] : 0;
                var prevLn = i >= j + 1 ? ln[i - (j + 1)] : 0;

                sum += (prevLn - currentLn) * (MathHelper.Sqrt(j) - MathHelper.Sqrt(j + 1));
            }

            oiSum[i] = sum;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, weightedSum.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Market Combo using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMarketComboFast(StockData data, ComputeContext context, int length = 40,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateNaturalMarketCombo publishes "Nmc": the signed square root of the combination of the river
        // and the mirror, both taken over the caller's own series. The spec's smoothLength smooths a series the
        // batch never publishes, so it is not a parameter of this arm.
        using var river = ComputeNaturalMarketRiverFast(data, context, length, maType);
        using var mirror = ComputeNaturalMarketMirrorFast(data, context, length, maType);
        var nmr = river.Span;
        var nmm = mirror.Span;
        var count = nmr.Length;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var v3 = Math.Sign(nmm[i]) != Math.Sign(nmr[i]) ? nmm[i] * nmr[i]
                : ((Math.Abs(nmm[i]) * nmr[i]) + (Math.Abs(nmr[i]) * nmm[i])) / 2;
            output[i] = Math.Sign(v3) * MathHelper.Sqrt(Math.Abs(v3));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Natural Stochastic Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalStochasticIndicatorFast(StockData data, ComputeContext context, int length = 20,
        int smoothLength = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalStochasticIndicator averages the stochastic position of every bar in the window
        // against the window's own high and low AS THEY STOOD at that bar, each weighted by the inverse
        // square root of its distance, then smooths the result. The core routine took a single position.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var highest = context.Rent(count);
        using var lowest = context.Rent(count);
        var hh = highest.WritableSpan;
        var ll = lowest.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            hh[i] = highWindow.Max;
            ll[i] = lowWindow.Min;
        }

        using var raw = context.Rent(count);
        var rawNst = raw.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double weightSum = 0, denomSum = 0;
            for (var j = 0; j < length; j++)
            {
                var high = i >= j ? hh[i - j] : 0;
                var low = i >= j ? ll[i - j] : 0;
                var c = i >= j ? input[i - j] : 0;
                var frac = ExactRangePosition.Fraction(c, low, high);
                var ratio = 1 / MathHelper.Sqrt(j + 1);
                weightSum += frac * ratio;
                denomSum += ratio;
            }

            rawNst[i] = denomSum != 0 ? (200 * weightSum / denomSum) - 100 : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, raw.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Negative Volume Disparity with extended intermediate arithmetic.
    /// </summary>
    internal static ComputeBuffer ComputeNegativeVolumeDisparitySignalFast(StockData data, ComputeContext context, int length,
        int signalLength, MovingAvgType maType, double top = 1.1, double bottom = .9)
    {
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var values = NegativeVolumeDisparityWindow.Calculate(data, input, maType, length, signalLength, top, bottom, callbacks: true, includeSignal: true).SignalLine;
        var result = context.Rent(values.Length);
        values.AsSpan().CopyTo(result.WritableSpan);
        return result;
    }

    internal static ComputeBuffer ComputeNegativeVolumeDisparityFast(StockData data, ComputeContext context, int length = 33,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, double top = 1.1, double bottom = .9)
    {
        var (input, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var values = NegativeVolumeDisparityWindow.Calculate(data, input, maType, length, 1, top, bottom, callbacks: true, includeSignal: false).Line;
        var result = context.Rent(values.Length);
        values.AsSpan().CopyTo(result.WritableSpan);
        return result;
    }

    /// <summary>
    /// Computes Ocean Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOceanIndicatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateOceanIndicator publishes the change in the scaled logarithm of the chained series over the
        // window, divided by the square root of the length so windows of different sizes stay comparable. The
        // moving average of it is the separate signal series, so no average type reaches this one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var root = MathHelper.Sqrt(length);
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevLn = i >= length ? ln[i - length] : 0;

            ln[i] = currentValue > 0 ? Math.Log(currentValue) * 1000 : 0;
            output[i] = (ln[i] - prevLn) / root * 100;
        }

        return buffer;
    }

    /// <summary>
    /// Computes OC Histogram using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOCHistogramFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var custom = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var open = context.Rent(input.Count); using var close = context.Rent(input.Count);
        if (custom)
        {
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.OpenPrices), open.WritableSpan);
            MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), close.WritableSpan);
        }
        var result = context.Rent(input.Count); using var window = new OpenCloseHistogramWindow(maType, length);
        for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(data.OpenPrices[i], input[i], true, custom ? open.Span[i] : null, custom ? close.Span[i] : null);
        return result;
    }

    /// <summary>
    /// Computes On Balance Volume Modified using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOnBalanceVolumeModifiedFast(StockData data, ComputeContext context, int length1 = 7,
        int length2 = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count); using var window = new ModifiedObvWindow(maType, length1, length2);
        for (var i = 0; i < input.Count; i++)
        { var value = window.Next(input[i], i < data.Volumes.Count ? data.Volumes[i] : 0, true); buffer.WritableSpan[i] = outputKey == "Signal" ? value.Signal : value.Line; }
        return buffer;
    }

