    internal static ComputeBuffer ComputeEhlersPhaseCalculationFast(StockData data, ComputeContext context, int length = 15, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, bool signal = false)
    {
        length = Math.Max(2, length); var external = signal && (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType)); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new FourierPhaseWindow(length, maType, !signal || external); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true); result.WritableSpan[i] = signal && !external ? point.Signal : point.Phase; }
        return external ? SmoothPublished(data, context, result, length, maType) : result;
    }

    internal static ComputeBuffer ComputeEhlersRestoringPullIndicatorFast(StockData data, ComputeContext context,
        int minLength = 8, int maxLength = 50, int length1 = 40, int length2 = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, bool signal = false)
    {
        // The core bank keeps each period's recurrence separate and bounds the cycle to the
        // scanned band. Signal is the requested moving average of the volume-scaled pull.
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.ClosePrices);
        var volume = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = data.Count;

        var buffer = context.Rent(count);
        OscillatorCore.EhlersRestoringPullIndicator(close, volume, buffer.WritableSpan,
            minLength, maxLength, length1, length2);
        if (!signal) return buffer;
        using (buffer)
        {
            var finite = FiniteSignalInput.Create(buffer.ToArray(), out var finiteCount);
            var smoothed = context.Rent(count);
            MovingAverage(data, maType, Math.Max(1, minLength), SpanCompat.AsReadOnlySpan(finite), smoothed.WritableSpan);
            for (var i = finiteCount; i < count; i++) smoothed.WritableSpan[i] = double.NaN;
            return smoothed;
        }
    }

    internal static ComputeBuffer ComputeEhlersRocketRsiFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 8, double mult = 1, MovingAvgType maType = MovingAvgType.Ehlers2PoleSuperSmootherFilterV2)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var external = ComponentAverage.HasOverrides || !RocketRsiWindow.Supports(maType);
        using var window = new RocketRsiWindow(maType, length1, length2, mult, external); var result = context.Rent(input.Count);
        if (external)
        {
            using var arguments = context.Rent(input.Count); using var smoothed = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) arguments.WritableSpan[i] = window.Prepare(input[i], true);
            MovingAverage(data, maType, Math.Max(1, length2), arguments.Span, smoothed.WritableSpan);
            for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Finish(smoothed.Span[i], true);
        }
        else for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true);
        return result;
    }

    internal static ComputeBuffer ComputeEhlersSimpleWindowIndicatorFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        length = Math.Max(1, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new EhlersSimpleWindow(maType, length); var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var changes = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) changes.WritableSpan[i] = EhlersSimpleWindow.Difference(input[i], data.OpenPrices[i]).Publish();
            using var first = context.Rent(input.Count); using var second = context.Rent(input.Count); using var third = context.Rent(input.Count);
            MovingAverage(data, maType, length, changes.Span, first.WritableSpan); MovingAverage(data, maType, length, first.Span, second.WritableSpan); MovingAverage(data, maType, length, second.Span, third.WritableSpan);
            for (var i = 0; i < input.Count; i++) { var value = window.Finish(new RocBankValue(first.Span[i]), new RocBankValue(third.Span[i]), true); result.WritableSpan[i] = outputKey == "Roc" ? value.Roc : value.Line; }
        }
        else for (var i = 0; i < input.Count; i++) { var value = window.Next(data.OpenPrices[i], input[i], true); result.WritableSpan[i] = outputKey == "Roc" ? value.Roc : value.Line; }
        return result;
    }

    internal static ComputeBuffer ComputeEhlersSmoothedAdaptiveMomentumFast(StockData data, ComputeContext context,
        int length1 = 5, int length2 = 8, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        MacdSeries series = MacdSeries.Line)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var window = new SmoothedAdaptiveMomentumWindow(length1, length2, maType);
        var buffer = context.Rent(input.Count); var smoothed = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true); buffer.WritableSpan[i] = point.Line; smoothed.WritableSpan[i] = point.Signal; }
        if (ComponentAverage.HasOverrides || !SmoothedAdaptiveMomentumWindow.Supports(maType)) MovingAverage(data, maType, Math.Max(2, length2), buffer.Span, smoothed.WritableSpan);
        if (series == MacdSeries.Signal) { buffer.Dispose(); return smoothed; }
        smoothed.Dispose(); return buffer;
    }

    /// <summary>
    /// Selects which of the three series the snake filter routine publishes.
    /// </summary>
    internal enum SnakeFilterSeries
    {
        /// <summary>The filter itself, which the indicator stands for.</summary>
        Erf,

        /// <summary>The root mean square of the filter over length2.</summary>
        UpperBand,

        /// <summary>Its negation.</summary>
        LowerBand
    }

    internal static ComputeBuffer ComputeEhlersSnakeUniversalTradingFilterFast(StockData data, ComputeContext context,
        int length1 = 23, int length2 = 50, double bw = 1.4,
        MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage, SnakeFilterSeries band = SnakeFilterSeries.Erf)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var external = ComponentAverage.HasOverrides || !UniversalTradingWindow.Supports(maType);
        using var window = new UniversalTradingWindow(maType, length1, length2, bw, true, external); var result = context.Rent(input.Count);
        if (external)
        {
            using var raw = context.Rent(input.Count); using var filtered = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) raw.WritableSpan[i] = window.Prepare(input[i], true); MovingAverage(data, maType, Math.Max(1, length1), raw.Span, filtered.WritableSpan);
            for (var i = 0; i < input.Count; i++) { var point = window.Finish(filtered.Span[i], true); result.WritableSpan[i] = band == SnakeFilterSeries.UpperBand ? point.Upper : band == SnakeFilterSeries.LowerBand ? point.Lower : point.Line; }
        }
        else for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true); result.WritableSpan[i] = band == SnakeFilterSeries.UpperBand ? point.Upper : band == SnakeFilterSeries.LowerBand ? point.Lower : point.Line; }
        return result;
    }

    internal static ComputeBuffer ComputeEhlersTrendExtractionFast(StockData data, ComputeContext context, int length = 20, double delta = 0.1,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool bandPassOnly = false)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var external = ComponentAverage.HasOverrides || !TrendExtractionWindow.Supports(maType);
        using var window = new TrendExtractionWindow(maType, length, delta, external); var result = context.Rent(input.Count);
        if (bandPassOnly) for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Prepare(input[i], true);
        else if (external)
        {
            using var bands = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) bands.WritableSpan[i] = window.Prepare(input[i], true);
            MovingAverage(data, maType, TrendExtractionWindow.ExternalPeriod(length), bands.Span, result.WritableSpan);
        }
        else for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], true).Trend;
        return result;
    }

    internal static ComputeBuffer ComputeEhlersTripleDelaySignalFast(StockData data, ComputeContext context, int length, MovingAvgType maType)
        => ComputeEhlersTripleDelayLineDetrenderFast(data, context, length, maType, true);

    internal static ComputeBuffer ComputeEhlersTripleDelayLineDetrenderFast(StockData data, ComputeContext context, int length = 14, MovingAvgType maType = MovingAvgType.EhlersModifiedOptimumEllipticFilter, bool signal = false)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; length = Math.Max(1, length);
        using var window = new TripleDelayWindow(maType, length); var output = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !TripleDelayWindow.Supports(maType))
        {
            using var raw = context.Rent(input.Count); using var line = context.Rent(input.Count); using var smooth = context.Rent(input.Count);
            for (var i = 0; i < input.Count; i++) raw.WritableSpan[i] = window.Detrend(input[i], true).Publish();
            MovingAverage(data, maType, length, raw.Span, line.WritableSpan); MovingAverage(data, maType, length, line.Span, smooth.WritableSpan);
            (signal ? smooth.Span : line.Span).CopyTo(output.WritableSpan);
        }
        else for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true); output.WritableSpan[i] = signal ? point.Signal : point.Line; }
        return output;
    }

