            for (var i = 0; i < input.Count; i++) { var point = window.Finish(filtered.Span[i], true); result.WritableSpan[i] = outputKey == "UpperBand" ? point.Upper : outputKey == "LowerBand" ? point.Lower : point.Line; }
        }
