        for (var i = 0; i < input.Count; i++) { var point = window.Next(input[i], true); if (external) raw[i] = point.Value; result.WritableSpan[i] = outputKey == "Signal" ? point.Average : point.Value; }
        if (external) { var average = ComponentAverage.Take(raw, length2) ?? CalculationsHelper.GetMovingAverageList(data, maType, length2, raw.ToList()).ToArray(); if (outputKey == "Signal") for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = average[i]; } return result;
    }

    /// <summary>
    /// Writes the dominant cycle of <paramref name="roofingFilter"/> into <paramref name="output"/>: the
    /// autocorrelation of the filtered series at every lag, transformed by a discrete Fourier sum, and
    /// resolved to the centre of gravity of the periods carrying at least half of the peak power.
    /// </summary>
    /// <remarks>
    /// This is CalculateEhlersAutoCorrelationPeriodogram taken over CalculateEhlersAutoCorrelationIndicator.
    /// The four adaptive V2 indicators all open with exactly that pair on the caller's own series, so they
    /// share one pass of it here. The power array is carried across bars, which is what makes the r value
    /// recursive, so it is cleared once and never re-rented inside the loop.
    /// </remarks>
    private static void EhlersDominantCycle(ComputeContext context, ReadOnlySpan<double> roofingFilter, int length1,
        int length2, int length3, Span<double> output)
    {
        var count = roofingFilter.Length;
        length3 = Math.Max(length3, 0);
        var stride = length1 + 1;

        using var correlation = context.Rent(count);
        var corr = correlation.WritableSpan;

        EhlersAutocorrelation.Compute(roofingFilter, corr, length1);

        using var cosineTable = context.Rent(stride * stride);
        using var sineTable = context.Rent(stride * stride);
        var cosines = cosineTable.WritableSpan;
        var sines = sineTable.WritableSpan;
        for (var j = length2; j <= length1; j++)
        {
            for (var k = length3; k <= length1; k++)
            {
                var angle = 2 * Math.PI * ((double)k / j);
                cosines[(j * stride) + k] = Math.Cos(angle);
                sines[(j * stride) + k] = Math.Sin(angle);
            }
        }

        using var powerBuffer = context.Rent(stride);
        var powers = powerBuffer.WritableSpan;
        powers.Clear();

        for (var i = 0; i < count; i++)
        {
            double maxPower = 0;
            for (var j = length2; j <= length1; j++)
            {
                double cosPart = 0;
                double sinPart = 0;
                for (var k = length3; k <= length1; k++)
                {
                    var value = i >= k ? corr[i - k] : 0;
                    cosPart += value * cosines[(j * stride) + k];
                    sinPart += value * sines[(j * stride) + k];
                }

                var squareSum = (cosPart * cosPart) + (sinPart * sinPart);
                var power = (0.2 * (squareSum * squareSum)) + (0.8 * powers[j]);
                powers[j] = power;
                maxPower = Math.Max(power, maxPower);
            }

            double weightedSum = 0;
            double powerSum = 0;
            for (var j = length2; j <= length1; j++)
            {
                var scaled = maxPower != 0 ? powers[j] / maxPower : 0;
                if (scaled >= 0.5)
                {
                    weightedSum += j * scaled;
                    powerSum += scaled;
                }
            }

            output[i] = powerSum != 0 ? weightedSum / powerSum : 0;
        }
    }

    /// <summary>
    /// Which of the Mesa predict indicator's three published series an arm has been asked for: the smoothed
    /// filter it starts from, the autoregressive prediction, or the straight-line extrapolation of the same
    /// window that the prediction is measured against.
    /// </summary>
    internal enum MesaPredictSeries
    {
        Filter,
        Predict,
        Extrapolate
    }

    internal static ComputeBuffer ComputeEhlersMesaPredictIndicatorV2Fast(StockData data, ComputeContext context,
        int length1 = 5, int length2 = 135, int length3 = 12, int length4 = 4,
        MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage, MesaPredictSeries series = MesaPredictSeries.Filter)
    {
        // CalculateEhlersMesaPredictIndicatorV2 high-pass filters the series, super-smooths it, then runs a
        // five-tap autoregression forward over the last length1 filter values. OscillatorCore's routine, which
        // this arm was bound to, took the raw close and produced something else from bar 0 onwards.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);
        length4 = Math.Max(length4, 1);
        length4 = Math.Min(length4, length1);

        Span<double> coefficients = stackalloc double[5] { 4.525, -8.45, 8.145, -4.045, 0.825 };

        var a1 = MathHelper.Exp(MathHelper.MinOrMax(-1.414 * Math.PI / length2, -0.01, -0.99));
        var b1 = 2 * a1 * Math.Cos(MathHelper.MinOrMax(1.414 * Math.PI / length2, 0.99, 0.01));
        var c2 = b1;
        var c3 = -a1 * a1;
        var c1 = (1 + c2 - c3) / 4;

        var a = MathHelper.Exp(MathHelper.MinOrMax(-1.414 * Math.PI / length3, -0.01, -0.99));
        var b = 2 * a * Math.Cos(MathHelper.MinOrMax(1.414 * Math.PI / length3, 0.99, 0.01));
        var coef2 = b;
        var coef3 = -a * a;
        var coef1 = 1 - coef2 - coef3;

        using var superSmoothed = context.Rent(count);
        var ssf = superSmoothed.WritableSpan;
        using var highPassed = context.Rent(count);
        var hp = highPassed.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue1 = i >= 1 ? input[i - 1] : 0;
            var previousValue2 = i >= 2 ? input[i - 2] : 0;
            var previousHp1 = i >= 1 ? hp[i - 1] : 0;
            var previousHp2 = i >= 2 ? hp[i - 2] : 0;
            var previousSsf1 = i >= 1 ? ssf[i - 1] : 0;
            var previousSsf2 = i >= 2 ? ssf[i - 2] : 0;

            hp[i] = i < 4 ? 0 : (c1 * (input[i] - (2 * previousValue1) + previousValue2)) + (c2 * previousHp1) + (c3 * previousHp2);
            ssf[i] = i < 3 ? hp[i] : (coef1 * ((hp[i] + previousHp1) / 2)) + (coef2 * previousSsf1) + (coef3 * previousSsf2);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length3, superSmoothed.Span, buffer.WritableSpan);
        if (series == MesaPredictSeries.Filter)
        {
            return buffer;
        }

        using var filtered = buffer;
        var filt = filtered.Span;
        var result = context.Rent(count);
        var output = result.WritableSpan;

        var bufferLength = Math.Max((2 * length1) + 2, length1 + length4 + 2);
        var pool = ArrayPool<double>.Shared;
        var scratch = pool.Rent(bufferLength);
        try
        {
            for (var i = 0; i < count; i++)
            {
                Array.Clear(scratch, 0, bufferLength);
                for (var j = 1; j <= length1; j++)
                {
                    scratch[j] = i >= length1 - j ? filt[i - (length1 - j)] : 0;
                }

                if (series == MesaPredictSeries.Predict)
                {
                    for (var j = 1; j <= length1; j++)
                    {
                        // All five coefficients multiply completed observations, at lags one through five.
                        for (var k = 1; k <= 5; k++)
                        {
                            var offset = length1 + j - k;
                            scratch[length1 + j] += coefficients[k - 1] * (offset >= 0 ? scratch[offset] : 0);
                        }
                    }
                }
                else
                {
                    for (var j = 0; j <= length1; j++)
                    {
                        scratch[length1 + j + 1] = (2 * scratch[length1 + j]) - scratch[length1 + j - 1];
                    }
                }

                output[i] = scratch[length1 + length4];
            }
        }
        finally
        {
            pool.Return(scratch);
        }

        return result;
    }

    internal static ComputeBuffer ComputeEhlersSignalToNoiseRatioV1Fast(StockData data, ComputeContext context, int length = 7, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        length = Math.Max(1, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues; var average = ComponentAverage.Take(SpanCompat.AsReadOnlySpan(input), length); using var window = new HilbertNoiseWindow(maType, length, true); var result = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Next(input[i], data.HighPrices[i], data.LowPrices[i], true, average?[i] ?? 0).Value; return result;
    }

    internal static ComputeBuffer ComputeEhlersSignalToNoiseRatioV2Fast(StockData data, ComputeContext context, int length = 6, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        return ComputeMamaNoiseFast(data, context, length, 1, "Esnr");
    }

    // Batch 27 - Trend and Volatility Indicators

    internal static ComputeBuffer ComputeTrendExhaustionIndicatorFast(StockData data, ComputeContext context, int length = 10)
    {
        // CalculateTrendExhaustionIndicator counts, from the first bar onwards, how often the series has risen
        // and how often the high has broken the highest high of the previous window, and smooths the ratio of
        // the two exponentially. The counts are running totals, not windowed ones. maType smooths only the
        // "Signal" series, which this arm does not publish, so it is not a parameter of it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var smoothingConstant = (double)2 / (length + 1);
        var highWindow = new RollingMinMax(Math.Max(length, 2));
        double advances = 0;
        double breakouts = 0;
        double previousHighest = 0;
        double previousValue = 0;
        for (var i = 0; i < count; i++)
        {
            advances += input[i] > previousValue ? 1 : 0;
            breakouts += highs[i] > previousHighest ? 1 : 0;

            var ratio = advances != 0 ? breakouts / advances : 0;
            var previous = i >= 1 ? output[i - 1] : 0;
            output[i] = previous + (smoothingConstant * (ratio - previous));

            // The highest high the next bar is measured against is the one ending on this bar.
            highWindow.Add(highs[i]);
            previousHighest = highWindow.Max;
            previousValue = input[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTrendImpulseFilterFast(StockData data, ComputeContext context, int length1 = 100, int length2 = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // V1 Algorithm: Trend Impulse Filter
        // 1. Calculate highest/lowest over length1 bars
        // 2. If price breaks above highest or below lowest, a=1, else a=0
        // 3. b = (a * price) + ((1-a) * prevB)
        // 4. Apply EMA to b with length2
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;

        // Calculate rolling highest and lowest
        var bBuffer = context.Rent(count);
        var bSpan = bBuffer.WritableSpan;

        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double prevB = i >= 1 ? bSpan[i - 1] : currentValue;

            // Calculate highest and lowest from previous bars (not including current)
            double highest = double.MinValue;
            double lowest = double.MaxValue;
            int startIdx = Math.Max(0, i - Math.Max(2, length1));
            for (int j = startIdx; j < i; j++)
            {
                if (close[j] > highest) highest = close[j];
                if (close[j] < lowest) lowest = close[j];
            }

            // Handle first bar
            if (i == 0)
            {
                bSpan[i] = currentValue;
                continue;
            }

            // Determine if breakout occurred
            double a = (currentValue > highest || currentValue < lowest) ? 1 : 0;
            bSpan[i] = (a * currentValue) + ((1 - a) * prevB);
        }

        // Apply EMA to b values
        var result = context.Rent(count);
        StochasticSmooth(data, maType, length2, bBuffer.Span, result.WritableSpan);

        bBuffer.Dispose();
        return result;
    }

    internal static ComputeBuffer ComputeTrendDirectionForceIndexFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 30, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateTrendDirectionForceIndex double-smooths the chained series scaled by a thousand over half of
        // length1, cubes the average of the two smoothing changes, scales it by the gap between the two averages
        // and normalises by the highest absolute force of the last length2 bars. It is not the force index, which
        // is what VolumeCore.ForceIndex computed here: that reads the volume, and this reads none.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        if (!ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var kernel = new Streaming.TrendForceKernel(maType, length1, length2);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = kernel.Next(input[i], true);
            return stable;
        }

        var halfLength = Math.Max(1, Math.Min(530, (int)Math.Ceiling((double)length1 / 2)));

        using var scaled = context.Rent(count);
        var source = scaled.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            source[i] = input[i] * 1000;
        }

        using var firstPass = context.Rent(count);
        using var secondPass = context.Rent(count);
        MovingAverage(data, maType, halfLength, scaled.Span, firstPass.WritableSpan);
        MovingAverage(data, maType, halfLength, firstPass.Span, secondPass.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var absoluteWindow = new RollingMinMax(length2);
        for (var i = 0; i < count; i++)
        {
            var ema1 = firstPass.Span[i];
            var ema2 = secondPass.Span[i];
            var ema1Change = ema1 - (i >= 1 ? firstPass.Span[i - 1] : 0);
            var ema2Change = ema2 - (i >= 1 ? secondPass.Span[i - 1] : 0);
            var averageChange = (ema1Change + ema2Change) / 2;

            double force;
            try
            {
                force = Math.Abs(ema1 - ema2) * MathHelper.Pow(averageChange, 3);
            }
            catch (OverflowException)
            {
                // Prices scaled by a thousand and then cubed can leave the range of the arithmetic they are
                // computed in. The batch saturates rather than propagating, and an arm that propagated instead
                // would part company with it on exactly the bars where it matters.
                force = double.MaxValue;
            }

            absoluteWindow.Add(Math.Abs(force));
            var highest = absoluteWindow.Max;
            output[i] = highest != 0 ? force / highest : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTrendAnalysisIndexFast(StockData data, ComputeContext context, int length1 = 28, int length2 = 5,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        var values = TrendAnalysisIndexWindow.Calculate(data, maType, length1, length2, outputKey == "Signal");
        var selected = outputKey == "Signal" ? values.SignalLine : values.Line;
        var output = context.Rent(selected.Length); selected.AsSpan().CopyTo(output.WritableSpan); return output;
    }

    internal static ComputeBuffer ComputeTrendAnalysisIndicatorFast(StockData data, ComputeContext context, int length1 = 21,
        int length2 = 4, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        var values = TrendAnalysisIndicatorWindow.Calculate(data, maType, length1, length2, outputKey == "Signal", false);
        var selected = outputKey == "Signal" ? values.SignalLine : values.Line;
        var output = context.Rent(selected.Length); selected.AsSpan().CopyTo(output.WritableSpan); return output;
    }

    /// <summary>
    /// Selects which of the three series the trender routine publishes.
    /// </summary>
    internal enum TrenderSeries
    {
        /// <summary>The trend line the indicator stands for.</summary>
        Trender,

        /// <summary>The upward stop.</summary>
        TrendUp,

        /// <summary>The downward stop.</summary>
        TrendDown
    }

    internal static ComputeBuffer ComputeTrenderFast(StockData data, ComputeContext context, int length = 14,
        double atrMult = 2, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        TrenderSeries series = TrenderSeries.Trender)
    {
        var (input, high, low, _, _) = CalculationsHelper.GetInputValuesList(data); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType);
        using var window = new TrenderWindow(maType, length, atrMult, external); using ComputeBuffer? mean = external ? context.Rent(input.Count) : null;
        if (external) MovingAverage(data, maType, Math.Max(1, length), SpanCompat.AsReadOnlySpan(input), mean!.Value.WritableSpan);
        using ComputeBuffer? atr = external ? ComputeAtrFast(data, context, Math.Max(1, length), maType) : null; using ComputeBuffer? adaptive = external ? context.Rent(input.Count) : null;
        if (external) MovingAverage(data, maType, Math.Max(1, length), TrenderWindow.PublishedAdaptive(input, mean!.Value.ToArray(), atr!.Value.ToArray()), adaptive!.Value.WritableSpan);
        var result = context.Rent(input.Count); try { for (var i = 0; i < input.Count; i++) { var point = window.Next(high[i], low[i], input[i], true, external ? mean!.Value.Span[i] : null, external ? atr!.Value.Span[i] : null, external ? adaptive!.Value.Span[i] : null); result.WritableSpan[i] = series == TrenderSeries.TrendUp ? point.TrendUp : series == TrenderSeries.TrendDown ? point.TrendDn : point.Trender; } return result; }
        catch { result.Dispose(); throw; }
    }

