    internal static ComputeBuffer ComputeVolatilityBasedMomentumFast(StockData data, ComputeContext context, int length1 = 22, int length2 = 65,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, string? outputKey = null)
    {
        length1 = Math.Max(1, length1); length2 = Math.Max(1, length2);
        if (StrengthWindow.Supports(maType))
        {
            var key = outputKey == "Signal" ? "Signal" : "Vbm";
            var values = VolatilityMomentumWindow.Calculate(data, maType, length1, length2, key).Outputs[key];
            var result = context.Rent(values.Length);
            try { values.AsSpan().CopyTo(result.WritableSpan); return result; } catch { result.Dispose(); throw; }
        }
        if (outputKey == "Signal") return SmoothPublished(data, context, ComputeVolatilityBasedMomentumFast(data, context, length1, length2, maType), length1, maType);
        // CalculateVolatilityBasedMomentum publishes the raw ratio: the rate of change of the chained series
        // over length1 divided by the average true range over length2. Its average of that ratio feeds only the
        // separately published signal, so this helper stops at the ratio.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var averageTrueRange = ComputeAtrFast(data, context, length2, maType);
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length1 ? input[i - length1] : 0;
            var rateOfChange = CalculationsHelper.MinPastValues(i, length1, input[i] - prevValue);
            output[i] = atr[i] != 0 ? rateOfChange / atr[i] : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolatilitySwitchIndicatorFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        length = Math.Max(1, length); var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new VolatilitySwitchWindow(maType, length); var result = context.Rent(input.Count);
        if (ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType))
        {
            using var deviation = context.Rent(input.Count); for (var i = 0; i < input.Count; i++) deviation.WritableSpan[i] = window.Deviation(input[i], true).Publish();
            MovingAverage(data, maType, length, deviation.Span, result.WritableSpan);
            if (ComponentAverage.HasOverrides) { using var unused = context.Rent(input.Count); MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), unused.WritableSpan); }
        }
        else for (var i = 0; i < input.Count; i++) result.WritableSpan[i] = window.Value(input[i], true);
        return result;
    }

