    internal static ComputeBuffer ComputeStochasticRegularFast(StockData data, ComputeContext context, int length1 = 5, int length2 = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
        => ComputeStochasticKFast(data, context, length1);

    // Batch 31 - Relative and Statistical Indicators

    internal static ComputeBuffer ComputeRecursiveRelativeStrengthIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var result = RecursiveRsiWindow.Calculate(data, maType, length, true);
        var buffer = context.Rent(result.Values.Length); result.Values.AsSpan().CopyTo(buffer.WritableSpan); return buffer;
    }

    internal static ComputeBuffer ComputeRelativeSpreadStrengthFast(StockData data, ComputeContext context, int fastLength = 10, int slowLength = 40, int length = 14, int smoothLength = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        if (ComponentAverage.HasOverrides)
        {
            using var fast = context.Rent(data.Count);
            using var slow = context.Rent(data.Count);
            using var rsi = context.Rent(data.Count);
            MovingAverage(data, maType, fastLength, SpanCompat.AsReadOnlySpan(input), fast.WritableSpan);
            MovingAverage(data, maType, slowLength, SpanCompat.AsReadOnlySpan(input), slow.WritableSpan);
            using var strength = new Streaming.RelativeSpreadKernel(maType, fastLength, slowLength, length, smoothLength);
            for (var i = 0; i < data.Count; i++)
            {
                Streaming.StreamingInputValidation.Finite(fast.Span[i], "fast"); Streaming.StreamingInputValidation.Finite(slow.Span[i], "slow");
                rsi.WritableSpan[i] = strength.StrengthFromSpread(MacZWindow.Number.Of(fast.Span[i]) - MacZWindow.Number.Of(slow.Span[i]), true);
            }
            var result = context.Rent(data.Count);
            MovingAverage(data, maType, smoothLength, rsi.Span, result.WritableSpan);
            return result;
        }
        var buffer = context.Rent(data.Count);
        using var kernel = new Streaming.RelativeSpreadKernel(maType, fastLength, slowLength, length, smoothLength);
        for (var i = 0; i < data.Count; i++) buffer.WritableSpan[i] = kernel.Next(input[i], true);
        return buffer;
    }

    /// <summary>
    /// Writes the original relative volatility index of <paramref name="series"/> into
    /// <paramref name="output"/>: the relative strength routine with the standard deviation of the window in
    /// place of the price change, which is what CalculateRelativeVolatilityIndexV1 computes.
    /// </summary>
    private static void RelativeVolatilityIndexV1(StockData data, ComputeContext context, ReadOnlySpan<double> series,
        int length, int smoothLength, MovingAvgType maType, Span<double> output)
    {
        smoothLength = Math.Max(1, smoothLength); var external = ComponentAverage.HasOverrides || !StrengthWindow.Supports(maType); using var window = new RelativeVolatilityWindow(maType, length, smoothLength, external, series.Length);
        if (external)
        {
            using var up = context.Rent(series.Length); using var down = context.Rent(series.Length); using var upMean = context.Rent(series.Length); using var downMean = context.Rent(series.Length);
            for (var i = 0; i < series.Length; i++) { var p = window.Generate(series[i], true); up.WritableSpan[i] = p.Up; down.WritableSpan[i] = p.Down; }
            MovingAverage(data, maType, smoothLength, up.Span, upMean.WritableSpan); MovingAverage(data, maType, smoothLength, down.Span, downMean.WritableSpan);
            for (var i = 0; i < series.Length; i++) output[i] = RelativeVolatilityWindow.Ratio(new RocBankValue(upMean.Span[i]), new RocBankValue(downMean.Span[i]));
        }
        else for (var i = 0; i < series.Length; i++) output[i] = window.Next(series[i], true);
    }

    internal static ComputeBuffer ComputeRelativeVolatilityIndexV2Fast(StockData data, ComputeContext context, int length = 10,
        int smoothLength = 14, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateRelativeVolatilityIndexV2 takes the original index of the high series and of the low series
        // and averages the two. VolatilityCore.RelativeVolatilityIndex ran the routine once over the close, so
        // it was a different quantity from its first bar on.
        var count = data.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var highIndex = context.Rent(count);
        using var lowIndex = context.Rent(count);
        RelativeVolatilityIndexV1(data, context, highs, length, smoothLength, maType, highIndex.WritableSpan);
        RelativeVolatilityIndexV1(data, context, lows, length, smoothLength, maType, lowIndex.WritableSpan);

        var buffer = context.Rent(count);
        var rvi = buffer.WritableSpan;
        var rviHigh = highIndex.Span;
        var rviLow = lowIndex.Span;
        for (var i = 0; i < count; i++)
        {
            rvi[i] = RelativeVolatilityWindow.Mean(rviHigh[i], rviLow[i]);
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeRelativeVolumeIndicatorFast(StockData data, ComputeContext context, int length = 60, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool demandPrice = false)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var custom = ComponentAverage.HasOverrides;
        using var means = context.Rent(data.Count);
        if (custom) MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.Volumes), means.WritableSpan);
        var output = context.Rent(data.Count);
        using var window = new RelativeVolumeWindow(maType, length);
        for (var i = 0; i < data.Count; i++)
        {
            var (score, demand) = window.Next(input[i], data.Volumes[i], true, custom ? means.Span[i] : null);
            output.WritableSpan[i] = demandPrice ? demand : score;
        }
        return output;
    }

    /// <summary>
    /// Selects which of the four series the self adjusting relative strength index publishes.
    /// </summary>
    internal enum SelfAdjustingRsiSeries
    {
        /// <summary>The relative strength index itself.</summary>
        SaRsi,

        /// <summary>Its smoothing over the smoothing length.</summary>
        Signal,

        /// <summary>Fifty plus the multiplied deviation of the index.</summary>
        ObLevel,

        /// <summary>Fifty less it.</summary>
        OsLevel
    }

    internal static ComputeBuffer ComputeSelfAdjustingRsiFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int smoothingLength = 21, double mult = 2,
        SelfAdjustingRsiSeries series = SelfAdjustingRsiSeries.SaRsi)
    {
        // CalculateSelfAdjustingRelativeStrengthIndex publishes the relative strength index, its smoothing
        // over smoothingLength, and two levels that sit at 50 plus and minus mult deviations OF THE INDEX
        // taken over length - not over the smoothing length. Only the index was produced, so all three of
        // the others answered with it and neither smoothingLength nor mult reached the arm at all.
        //
        // The routine this replaced fixed the average at Wilders and read the close, where the batch smooths
        // gains and losses with whichever average it is given and reads the chained series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        var buffer = context.Rent(count);
        if (series == SelfAdjustingRsiSeries.SaRsi)
        {
            RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(inputList), length, maType, buffer.WritableSpan);
            return buffer;
        }

        using var index = context.Rent(count);
        RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(inputList), length, maType, index.WritableSpan);

        if (series == SelfAdjustingRsiSeries.Signal)
        {
            if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
            {
                using var signal = new StrengthAverage(maType, smoothingLength, count);
                for (var i = 0; i < count; i++) buffer.WritableSpan[i] = signal.Next(new StrengthValue(index.Span[i]), true).Mantissa;
            }
            else MovingAverage(data, maType, smoothingLength, index.Span, buffer.WritableSpan);
            return buffer;
        }

        using var deviation = context.Rent(count);
        using var population = new ExactPopulationWindow(length);
        for (var i = 0; i < count; i++) deviation.WritableSpan[i] = population.Next(index.Span[i], true);

        var output = buffer.WritableSpan;
        var stdDev = deviation.Span;
        for (var i = 0; i < count; i++)
        {
            var adjusting = mult * stdDev[i];
            output[i] = series == SelfAdjustingRsiSeries.OsLevel ? 50 - adjusting : 50 + adjusting;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeSmoothedWilliamsAccumulationDistributionFast(StockData data, ComputeContext context, int length = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var window = new WilliamsAccumulationWindow();
        var standard = StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides;
        using var average = standard ? new RocBankAverage(maType, length, input.Count) : null;
        using var values = context.Rent(input.Count); using var signals = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++)
        {
            var value = window.Next(data.HighPrices[i], data.LowPrices[i], input[i], true);
            values.WritableSpan[i] = value.Publish();
            if (standard) signals.WritableSpan[i] = average!.Next(value, true).Publish();
        }
        if (!standard) MovingAverage(data, maType, Math.Max(1, length), values.Span, signals.WritableSpan);
        var output = context.Rent(input.Count);
        (outputKey == "Signal" ? signals.Span : values.Span).CopyTo(output.WritableSpan);
        return output;
    }

    internal static ComputeBuffer ComputeStatisticalVolatilityFast(StockData data, ComputeContext context, int length1 = 30,
        int length2 = 253, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count); using var window = new StatisticalVolatilityWindow(maType, length1, length2);
        for (var i = 0; i < input.Count; i++)
        { var point = window.Next(data.HighPrices[i], data.LowPrices[i], input[i], true); buffer.WritableSpan[i] = outputKey == "Signal" ? point.Signal : point.Line; }
        return buffer;
    }

    /// <summary>
    /// Selects which of the five series the traders dynamic index routine publishes.
    /// </summary>
    internal enum TradersDynamicSeries
    {
        /// <summary>The length3 average of the relative strength index, which the indicator stands for.</summary>
        Tdi,

        /// <summary>The length4 average of it.</summary>
        Signal,

        /// <summary>The index's own signal line plus the band offset.</summary>
        UpperBand,

        /// <summary>The midpoint of the two bands.</summary>
        MiddleBand,

        /// <summary>The index's own signal line less the band offset.</summary>
        LowerBand
    }

    internal static ComputeBuffer ComputeTradersDynamicIndexFast(StockData data, ComputeContext context, int length1 = 13,
        int length3 = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length2 = 34, int length4 = 7,
        TradersDynamicSeries series = TradersDynamicSeries.Tdi)
    {
        // CalculateTradersDynamicIndex publishes five series off one relative strength index of the chained
        // series: Tdi is its length3 average, Signal its length4 average, and the three bands sit around the
        // index's OWN signal line, offset by 1.6185 deviations of the index over length2. Only Tdi was being
        // produced, so the other four keys answered with it, and length2 and length4 reached nothing at all.
        //
        // The index's signal line is its own maType average over length2. CalculateRelativeStrengthIndex
        // has TWO branches: it uses a Wilder average only when it was GIVEN the Wilder type, and otherwise
        // the average it was given. Reading only the first branch had this taking a Wilder average always,
        // which put bar 0 at 100/34 where the batch has a simple average still filling its window at zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var relativeStrength = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length1, maType, relativeStrength.WritableSpan);
        var rsi = relativeStrength.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (series == TradersDynamicSeries.Tdi)
        {
            MovingAverage(data, maType, length3, rsi, output);
            return buffer;
        }

        if (series == TradersDynamicSeries.Signal)
        {
            MovingAverage(data, maType, length4, rsi, output);
            return buffer;
        }

        using var indexSignal = context.Rent(count);
        if (StrengthWindow.Supports(maType) && !ComponentAverage.HasOverrides)
        {
            // Match the RSI component's signal-stage rounding, including warmup.
            using var signalWindow = new StrengthAverage(maType, length2, Math.Max(1, count));
            for (var i = 0; i < count; i++) indexSignal.WritableSpan[i] = signalWindow.Next(new StrengthValue(rsi[i]), true).Mantissa;
        }
        else MovingAverage(data, maType, length2, rsi, indexSignal.WritableSpan);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(rsi, deviation.WritableSpan, length2);

        var signalLine = indexSignal.Span;
        var stdDev = deviation.Span;
        for (var i = 0; i < count; i++)
        {
            var offset = 1.6185 * stdDev[i];
            var upper = signalLine[i] + offset;
            var lower = signalLine[i] - offset;

            output[i] = series switch
            {
                TradersDynamicSeries.UpperBand => upper,
                TradersDynamicSeries.LowerBand => lower,
                _ => (upper + lower) / 2
            };
        }

        return buffer;
    }

    // Batch 32 - Remaining Indicators (Part 1)

    internal static ComputeBuffer ComputeGrandTrendForecastingFast(StockData data, ComputeContext context, int length = 100, int forecastLength = 200, double mult = 2, string? outputKey = null)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var window = new GrandForecastWindow(length, forecastLength, mult); var output = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++)
        { var point = window.Next(input[i], true); output.WritableSpan[i] = outputKey switch { "UpperBand" => point.Upper, "MiddleBand" => point.Middle, "LowerBand" => point.Lower, _ => point.Trend }; }
        return output;
    }

    internal static ComputeBuffer ComputeFunctionToCandlesFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, CandleSeries series = CandleSeries.Close)
    {
        // CalculateFunctionToCandles publishes four relative strength indexes, one per candle series, and
        // never publishes their average. The Close key is the index of the caller's own series; the High and
        // Low are of the per-bar range that series makes, which is what CustomRange applies.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (StrengthWindow.Supports(maType))
        {
            double[] prices;
            if (series == CandleSeries.Open) prices = data.OpenPrices.ToArray();
            else if (series is CandleSeries.High or CandleSeries.Low)
            { using var high = context.Rent(count); using var low = context.Rent(count); CustomRange(data, input, high.WritableSpan, low.WritableSpan); prices = (series == CandleSeries.High ? high.Span : low.Span).ToArray(); }
            else prices = input.ToArray();
            var result = context.Rent(count); FunctionCandleRsi.Calculate(prices, maType, length, true).AsSpan().CopyTo(result.WritableSpan); return result;
        }

        var buffer = context.Rent(count);
        switch (series)
        {
            case CandleSeries.Open:
                RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(data.OpenPrices), length, maType,
                    buffer.WritableSpan);
                break;
            case CandleSeries.High:
            case CandleSeries.Low:
                using (var highBuffer = context.Rent(count))
                using (var lowBuffer = context.Rent(count))
                {
                    CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
                    var ranged = series == CandleSeries.High ? highBuffer.Span : lowBuffer.Span;
                    RelativeStrengthIndex(data, context, ranged, length, maType, buffer.WritableSpan);
                }

                break;
            default:
                RelativeStrengthIndex(data, context, input, length, maType, buffer.WritableSpan);
                break;
        }

        return buffer;
    }

